INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批评者", "is_correct": true, "explanation": "正确：“指出”的主语应是能提出意见的人，“批评者”指提出负面评价、指出局限的人，最合适。"}, {"text": "符号", "is_correct": false, "explanation": "语义：符号不能“指出”问题，“指出”的主语要能发表意见，与“符号”不合。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是机构或场所，不能发表意见或“指出”局限，此处讲不通。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然物，不能发表意见或“指出”问题。"}], "explanations": {"批评者": "正确：“指出”的主语应是能提出意见的人，“批评者”指提出负面评价、指出局限的人，最合适。", "符号": "语义：符号不能“指出”问题，“指出”的主语要能发表意见，与“符号”不合。", "工厂": "语义：工厂是机构或场所，不能发表意见或“指出”局限，此处讲不通。", "雨水": "语义：雨水是自然物，不能发表意见或“指出”问题。"}, "sentence_index": 0, "correct_answer": "批评者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们俱乐部最忠实的批评者，每场比赛都大声为球队加油。", "explanation": "这里应该用〈支持者〉。“批评者”指提出批评意见的人，不会为球队加油；“支持者”才指支持并为之加油的人。"}, {"text": "比赛的批评者宣布了最后的结果。", "explanation": "这里应该用〈评判者〉。宣布比赛结果是评判者的职责；“批评者”只提出看法，不负责裁决。"}, {"text": "妈妈是我最热情的批评者，总是夸我做得好。", "explanation": "这里应该用〈鼓励者〉。“批评者”重在指出缺点，不会一味夸奖；总是夸我的人应是鼓励者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评者", "is_correct": true, "explanation": "正确：“听……的意见”的对象应是能提出意见的人，“批评者”符合。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能提出意见，“听植物的意见”讲不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不会提出意见，与“听……的意见”的语义不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能提出意见，“听石头的意见”讲不通。"}], "explanations": {"批评者": "正确：“听……的意见”的对象应是能提出意见的人，“批评者”符合。", "植物": "语义：植物不能提出意见，“听植物的意见”讲不通。", "水果": "语义：水果不会提出意见，与“听……的意见”的语义不合。", "石头": "语义：石头不能提出意见，“听石头的意见”讲不通。"}, "sentence_index": 6, "correct_answer": "批评者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这起事故的唯一批评者，法庭上他出庭作证，说明了当时的经过。", "explanation": "这里应该用〈证人〉。“批评者”指提出负面评价的人，不负责出庭作证；出庭说明当时经过的是证人。"}, {"text": "他是我们公司最优秀的批评者，每个月都超额完成销售任务。", "explanation": "这里应该用〈销售员〉。“批评者”指提出负面意见的人，不负责销售；超额完成销售任务的是销售员。"}, {"text": "她是这家医院的优秀批评者，每天认真为病人看病。", "explanation": "这里应该用〈医生〉。“批评者”指指出缺点或错误的人，不负责诊治病人；为病人看病的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们公司一只严厉的批评者。", "corrected_sentence": "他是我们公司一位严厉的批评者。", "error_description": "量词错误。“批评者”指人，量词应用“位”或“个”，“只”多用于动物，不能用来修饰人。应说“一位严厉的批评者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几只批评者都很认真。", "corrected_sentence": "这几位批评者都很认真。", "error_description": "量词错误。“批评者”指人，量词应用“位”，不能用“只”。应说“这几位批评者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遮盖阻挡，使事物无法显露或难以看见。", "primary_collocate": null, "pronunciation": "zhē bì", "ipa": "ʈʂɤ˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "学术界亦开始探讨其作为“视觉修辞”的效力：一方面，它成功将复杂的资源代谢过程简化为可被大众认知的符号；另一方面，批评者指出，这种美学化的呈现可能遮蔽回收系统的实际局限，例如某些塑料的低再利用率或全球废料贸易中的不平等结构。", "target_word": "遮蔽", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "厚厚的乌云遮蔽了整个天空。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高楼遮蔽了阳光，院子里很暗。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浓雾遮蔽了山路，司机只好慢慢开。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大树的枝叶遮蔽着小路，路上很凉快。", "target_word": "遮蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙尘遮蔽了远处的山，什么也看不见。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他撑起大伞，遮蔽了头顶的阳光。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别让眼前的小利遮蔽了你的判断。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗帘很厚，能遮蔽外面的光线。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去的成见遮蔽了他的眼睛，他没有看到真相。", "target_word": "遮蔽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遮蔽了", "label": "完成体"}, {"form": "遮蔽着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "遮盖阻挡，使事物无法显露或难以看见（可指具体物体，也可比喻）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遮蔽", "is_correct": true, "explanation": "遮蔽：使事物难以显露，与“呈现可能……局限”的批评语境相合。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是事物外观，不能用来处置“实际局限”。"}, {"text": "加速", "is_correct": false, "explanation": "语义：“加速”指使速度变快，与“局限”不相容。"}, {"text": "培育", "is_correct": false, "explanation": "搭配：“培育”用于生物或人才，不能用于“局限”。"}], "explanations": {"遮蔽": "遮蔽：使事物难以显露，与“呈现可能……局限”的批评语境相合。", "装饰": "搭配：“装饰”的对象是事物外观，不能用来处置“实际局限”。", "加速": "语义：“加速”指使速度变快，与“局限”不相容。", "培育": "搭配：“培育”用于生物或人才，不能用于“局限”。"}, "sentence_index": 0, "correct_answer": "遮蔽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书遮蔽进了箱子。", "explanation": "这里应该用〈装〉。遮蔽是遮盖阻挡，不能表示把东西放进容器。"}, {"text": "老师在教室里遮蔽作业。", "explanation": "这里应该用〈批改〉。遮蔽是遮盖阻挡，不能用于检查和评定作业。"}, {"text": "他在操场上遮蔽了三圈。", "explanation": "这里应该用〈跑〉。遮蔽是遮盖阻挡，不能用于计算跑步的圈数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遮蔽", "is_correct": true, "explanation": "遮蔽：挡住阳光，与“撑起大伞”的动作相合。"}, {"text": "照耀", "is_correct": false, "explanation": "语义：“照耀”是发光照亮，与撑伞挡光的动作相反。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”的对象是实体，不能用于“阳光”。"}, {"text": "穿透", "is_correct": false, "explanation": "搭配：“穿透”指透过障碍，撑伞不能说“穿透阳光”。"}], "explanations": {"遮蔽": "遮蔽：挡住阳光，与“撑起大伞”的动作相合。", "照耀": "语义：“照耀”是发光照亮，与撑伞挡光的动作相反。", "切割": "搭配：“切割”的对象是实体，不能用于“阳光”。", "穿透": "搭配：“穿透”指透过障碍，撑伞不能说“穿透阳光”。"}, "sentence_index": 6, "correct_answer": "遮蔽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里遮蔽饺子。", "explanation": "这里应该用〈包〉。遮蔽是遮盖阻挡使人看不见，不能表示包饺子。"}, {"text": "孩子们在河边遮蔽鱼。", "explanation": "这里应该用〈钓〉。遮蔽是遮盖阻挡，不能用于捕捉鱼。"}, {"text": "孩子们在操场上遮蔽足球。", "explanation": "这里应该用〈踢〉。遮蔽是遮盖阻挡，不能用于踢球这类运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厚厚的云层遮蔽在了月亮。", "corrected_sentence": "厚厚的云层遮蔽了月亮。", "error_description": "错误：“遮蔽在了”。正确：“遮蔽了”。遮蔽后直接接受事宾语，不用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨幕了遮蔽远处的山峰。", "corrected_sentence": "雨幕遮蔽远处的山峰。", "error_description": "错误在于“了”放在了“遮蔽”之前（“雨幕了遮蔽”）。“了”是完成标记，不能放在动词前面；“遮蔽”是双音节词，应直接写作“雨幕遮蔽远处的山峰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理论", "is_correct": true, "explanation": "正确：“理论”与“实际”相对，“把知识联系实际”中二者形成对立。"}, {"text": "音乐", "is_correct": false, "explanation": "无反义关系：音乐与“实际”的真实情况义不构成对立。"}, {"text": "桌子", "is_correct": false, "explanation": "无反义关系：桌子是具体物品，与“实际”没有对立关系。"}, {"text": "河流", "is_correct": false, "explanation": "无反义关系：河流是地理事物，与“实际”的真实情况义不构成对立。"}], "correct_answer": "理论", "explanations": {"理论": "正确：“理论”与“实际”相对，“把知识联系实际”中二者形成对立。", "音乐": "无反义关系：音乐与“实际”的真实情况义不构成对立。", "桌子": "无反义关系：桌子是具体物品，与“实际”没有对立关系。", "河流": "无反义关系：河流是地理事物，与“实际”的真实情况义不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理想", "is_correct": true, "explanation": "正确：“理想”与“实际”相对，“相差太远”正是指理想与真实情况之间的差距。"}, {"text": "窗户", "is_correct": false, "explanation": "无反义关系：窗户是建筑部件，与“实际”没有对立关系。"}, {"text": "汽车", "is_correct": false, "explanation": "无反义关系：汽车是交通工具，与“实际”的真实情况义不构成对立。"}, {"text": "咖啡", "is_correct": false, "explanation": "无反义关系：咖啡是饮品，与“实际”没有对立关系。"}], "correct_answer": "理想", "explanations": {"理想": "正确：“理想”与“实际”相对，“相差太远”正是指理想与真实情况之间的差距。", "窗户": "无反义关系：窗户是建筑部件，与“实际”没有对立关系。", "汽车": "无反义关系：汽车是交通工具，与“实际”的真实情况义不构成对立。", "咖啡": "无反义关系：咖啡是饮品，与“实际”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指真实的情况或客观存在的事实。", "primary_collocate": null, "pronunciation": "shí jì", "ipa": "ʂʅ˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他的想法很好，但是不符合实际。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划要从实际出发。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理想很美，实际却很难。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把学到的知识联系实际。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法太脱离实际了。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话和实际不一样。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的内容和实际有很大差别。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该面对实际，不要只想好事。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的计划脱离实际，所以没用。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案与实际相差太远，只好放弃。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實際", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：真实的情况、客观事实（符合实际、从实际出发）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：shí jì，指真实的情况或客观存在的事实。"}, {"text": "时机", "is_correct": false, "explanation": "shí jī（第一声）与 shí jì（第四声）声调不同，意思是时机。"}, {"text": "事迹", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是事迹。"}, {"text": "十级", "is_correct": false, "explanation": "shí jí（第二声）与 shí jì（第四声）声调不同，意思是十级。"}, {"text": "十几", "is_correct": false, "explanation": "shí jǐ（第三声）与 shí jì（第四声）声调不同，意思是十几。"}], "explanations": {"实际": "正确：shí jì，指真实的情况或客观存在的事实。", "时机": "shí jī（第一声）与 shí jì（第四声）声调不同，意思是时机。", "事迹": "shì（第四声）与 shí（第二声）声调不同，意思是事迹。", "十级": "shí jí（第二声）与 shí jì（第四声）声调不同，意思是十级。", "十几": "shí jǐ（第三声）与 shí jì（第四声）声调不同，意思是十几。"}, "sentence_index": null, "correct_answer": "实际"}, "level_3": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：“不符合实际”指想法与真实情况不相符，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“不符合”要接标准或情况，天气不能作为“符合”的对象，讲不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“符合”一般接规定、标准等抽象要求，不能说“不符合味道”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是评判想法的标准，“不符合颜色”讲不通。"}], "explanations": {"实际": "正确：“不符合实际”指想法与真实情况不相符，符合语境。", "天气": "语义：“不符合”要接标准或情况，天气不能作为“符合”的对象，讲不通。", "味道": "搭配：“符合”一般接规定、标准等抽象要求，不能说“不符合味道”。", "颜色": "语义：颜色不是评判想法的标准，“不符合颜色”讲不通。"}, "sentence_index": 0, "correct_answer": "实际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆里陈列着很多珍贵的实际，吸引了不少游客。", "explanation": "这里应该用〈实物〉。“实物”指真实存在的具体物品，“实际”指真实情况，不能用来指陈列的物品。"}, {"text": "这个消息是实际，大家都不相信。", "explanation": "这里应该用〈事实〉。判断句“是事实”指某件事确实发生，“实际”不能直接作这种判断的宾语。"}, {"text": "这位英雄的实际被拍成了电影，感动了全国人民。", "explanation": "这里应该用〈事迹〉。事迹指人做过的具体事情，可以拍成电影；实际指真实情况，不能被拍成电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：shí jì，指真实的情况或客观存在的事实。"}, {"text": "世纪", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是世纪。"}, {"text": "实质", "is_correct": false, "explanation": "第二个音节 zhì 与 jì 声母不同，意思是事物的本质。"}, {"text": "石器", "is_correct": false, "explanation": "第二个音节 qì 与 jì 声母不同，意思是石头制成的工具。"}], "explanations": {"实际": "正确：shí jì，指真实的情况或客观存在的事实。", "世纪": "shì（第四声）与 shí（第二声）声调不同，意思是世纪。", "实质": "第二个音节 zhì 与 jì 声母不同，意思是事物的本质。", "石器": "第二个音节 qì 与 jì 声母不同，意思是石头制成的工具。"}, "sentence_index": null, "correct_answer": "实际"}, "level_3": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：“和实际有很大差别”中，“实际”指真实情况，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空与书上的内容没有可比性，“和天空有很大差别”讲不通。"}, {"text": "容貌", "is_correct": false, "explanation": "语义：容貌是人的外貌，不能拿来与书上的内容比较差别。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是动作，与书上的内容不能比较差别，讲不通。"}], "explanations": {"实际": "正确：“和实际有很大差别”中，“实际”指真实情况，符合语境。", "天空": "语义：天空与书上的内容没有可比性，“和天空有很大差别”讲不通。", "容貌": "语义：容貌是人的外貌，不能拿来与书上的内容比较差别。", "脚步": "语义：脚步是动作，与书上的内容不能比较差别，讲不通。"}, "sentence_index": 6, "correct_answer": "实际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家做了一个实际，结果证明了猜想。", "explanation": "这里应该用〈实验〉。“实验”指科学研究中的试验，“实际”指真实情况，不能指试验。"}, {"text": "他大学毕业后在公司实际，学到了很多东西。", "explanation": "这里应该用〈实习〉。“实习”是动词，指在实际工作中学习；“实际”不能表示这个动作。"}, {"text": "这次考试他的实际很好，考了全班第一。", "explanation": "这里应该用〈成绩〉。成绩指考试或工作的结果；实际指真实情况，不能用来说考试的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们做决定要实际出发，不能靠感觉。", "corrected_sentence": "我们做决定要从实际出发，不能靠感觉。", "error_description": "漏掉介词“从”。“从实际出发”是固定说法，“从”表示以什么为依据，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告的数据在实际有很大出入。", "corrected_sentence": "这份报告的数据和实际有很大出入。", "error_description": "介词错误：此处应用“和”，说“和实际有很大出入”。“在实际”不成立，“在”不能与“实际”这样搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
