INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用率指实际使用量与可用总量的比例，反映资源被有效使用的程度。", "primary_collocate": null, "pronunciation": "lì yòng lǜ", "ipa": "li˥˩ yʊŋ˥˩ ly˥˩", "syllable_count": 3, "sentences": [{"text": "这条生产线的利用率还有提升空间。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的利用率很低。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的利用率提高了。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想提高水的利用率。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室一天只用两小时，利用率不高。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新办法提高了设备利用率。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个停车场的利用率已经到了百分之九十。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地利用率太低，真可惜。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理每个月都检查电脑的利用率。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提高资源利用率对环境有好处。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：实际使用量占可用总量的比例（提高利用率）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利用率", "is_correct": true, "explanation": "“利用率”指使用比例，“这条生产线的……还有提升空间”成立。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”不能用来说生产线的使用比例，“生产线的人口还有提升空间”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不是可提升的指标，“生产线的年龄还有提升空间”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与生产线无关，“生产线的天气还有提升空间”说不通。"}], "explanations": {"利用率": "“利用率”指使用比例，“这条生产线的……还有提升空间”成立。", "人口": "语义：“人口”不能用来说生产线的使用比例，“生产线的人口还有提升空间”说不通。", "年龄": "语义：“年龄”不是可提升的指标，“生产线的年龄还有提升空间”说不通。", "天气": "语义：“天气”与生产线无关，“生产线的天气还有提升空间”说不通。"}, "sentence_index": 0, "correct_answer": "利用率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写报告的利用率很高，一个小时就写完了。", "explanation": "这里应该用〈效率〉。利用率指资源被使用的比例，人做事的快慢要用效率。"}, {"text": "他的汉语利用率很高，口语说得很流利。", "explanation": "这里应该用〈水平〉。利用率只用于资源的使用比例，人的能力要用水平。"}, {"text": "这次考试他的利用率很好。", "explanation": "这里应该用〈成绩〉。利用率说的是资源的使用比例，考试结果要用成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利用率", "is_correct": true, "explanation": "“利用率”可以用百分比表示停车场的使用比例，符合“到了百分之九十”的说法。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”不能用百分比表示，停车场没有身高，也说不通“到了百分之九十”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能到达百分之九十，这个说法对停车场的年龄无意义。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“气味”不能与“到了百分之九十”搭配，不能说气味的比例。"}], "explanations": {"利用率": "“利用率”可以用百分比表示停车场的使用比例，符合“到了百分之九十”的说法。", "身高": "语义：“身高”不能用百分比表示，停车场没有身高，也说不通“到了百分之九十”。", "年龄": "语义：“年龄”不能到达百分之九十，这个说法对停车场的年龄无意义。", "气味": "搭配：“气味”不能与“到了百分之九十”搭配，不能说气味的比例。"}, "sentence_index": 6, "correct_answer": "利用率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天音乐会的利用率很多，门口挤满了人。", "explanation": "这里应该用〈观众〉。利用率指资源被使用的比例，不能说“很多”，来听音乐会的人要说观众。"}, {"text": "他开车的利用率很快，十分钟就到了。", "explanation": "这里应该用〈速度〉。利用率不能用来说人开车的快慢，应用速度。"}, {"text": "她今天的利用率很好，一直在笑。", "explanation": "这里应该用〈心情〉。利用率说的是资源被使用的比例，人高兴不高兴要用心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间教室的利用率比去年快了很多。", "corrected_sentence": "这间教室的利用率比去年高了很多。", "error_description": "形容词搭配错误：“利用率”说高低，不能说“快”。应说“利用率比去年高了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座仓库的利用率已经吃到了百分之八十。", "corrected_sentence": "这座仓库的利用率已经达到了百分之八十。", "error_description": "搭配错误：“利用率”可以“达到”某个比例，不能说“吃到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
