INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指人与人之间在地位、权利、机会等方面没有差别。", "primary_collocate": null, "pronunciation": "píng děng", "ipa": "pʰiŋ˧˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "法律面前，人人平等。", "target_word": "平等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师平等地对待每个学生。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男人和女人应该平等。", "target_word": "平等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要平等地对待每个人。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样对孩子们不平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这家公司，大家的机会是平等的。", "target_word": "平等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子和大人应该平等相处。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，兄弟之间要平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平等的关系让我们成了好朋友。", "target_word": "平等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望得到平等的机会。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不平等", "label": "复合"}, {"form": "平等地", "label": "复合"}, {"form": "男女平等", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：人与人在地位、权利、机会上没有差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平等", "is_correct": true, "explanation": "正确：“人人平等”说明法律面前人人地位相同，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：法律面前讲的是地位与权利，“聪明”说智力，与句意不合。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”形容外貌，与法律面前的地位和权利无关。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”说身体状况，与法律面前的地位和权利无关。"}], "explanations": {"平等": "正确：“人人平等”说明法律面前人人地位相同，符合句意。", "聪明": "语义：法律面前讲的是地位与权利，“聪明”说智力，与句意不合。", "美丽": "体貌：“美丽”形容外貌，与法律面前的地位和权利无关。", "健康": "语义：“健康”说身体状况，与法律面前的地位和权利无关。"}, "sentence_index": 0, "correct_answer": "平等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两根绳子的粗细很平等。", "explanation": "这里应该用〈一样〉。平等指人在地位、权利上的相同；两样东西粗细相同要说一样。"}, {"text": "蛋糕要平等地切成三份。", "explanation": "这里应该用〈平均〉。平等指人与人之间地位、权利相同，切分物品要用平均。"}, {"text": "这两条边的长度平等。", "explanation": "这里应该用〈相等〉。平等不用于说明长度或数量的相同，长度相同要用相等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平等", "is_correct": true, "explanation": "正确：“平等相处”表示双方地位相同地交往，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来说两代人“高大地相处”。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指彼此不熟悉，与“应该相处”的要求相反。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指经济条件，与人际相处的方式无关。"}], "explanations": {"平等": "正确：“平等相处”表示双方地位相同地交往，符合句意。", "高大": "体貌：“高大”形容身材，不能用来说两代人“高大地相处”。", "陌生": "语义：“陌生”指彼此不熟悉，与“应该相处”的要求相反。", "富裕": "语义：“富裕”指经济条件，与人际相处的方式无关。"}, "sentence_index": 6, "correct_answer": "平等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家的帽子很平等。", "explanation": "这里应该用〈相同〉。平等指地位、权利相同，不用来描述物品。"}, {"text": "两个人的想法很平等。", "explanation": "这里应该用〈相同〉。想法的相同要说相同，平等指地位、权利的相同。"}, {"text": "他们的身高很平等。", "explanation": "这里应该用〈相近〉。平等指地位、权利相同；身高接近要用相近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种规定对女性没平等。", "corrected_sentence": "这种规定对女性不平等。", "error_description": "错误：用“没”否定形容词“平等”。正确：应用“不”，说“不平等”。否定形容词要用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩的地位很平等地。", "corrected_sentence": "我们俩的地位很平等。", "error_description": "错误：句末多加了“地”。“平等地”是状语形式，要修饰后面的动词，不能作谓语结尾。正确：应说“我们俩的地位很平等。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示已经发生或已经达到某种状态。", "primary_collocate": null, "pronunciation": "yǐ rán", "ipa": "i˨˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "由此，一个原本功能性的设计，已然升华为当代生态意识的文化镜像，折射出技术理想、消费现实与道德诉求之间的张力。", "target_word": "已然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天已然黑了，我们该回家了。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已然成为这家公司的经理。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天已然来到，花都开了。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题已然解决，不用再担心。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家已然做好了准备。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她已然忘记了那件小事。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车已然开走了，我们没赶上。", "target_word": "已然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市已然变得很热闹。", "target_word": "已然", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛已然结束，观众慢慢离开了。", "target_word": "已然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "已然：副词，表示事情已经发生或已经达到某种状态，用在动词或形容词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "已然", "is_correct": true, "explanation": "正确答案。已然是副词，表示已经发生或已经达到某种状态。"}, {"text": "依然", "is_correct": false, "explanation": "依然 yīrán 与 已然 yǐrán 第一个音节声调不同（第一声与第三声），意思是仍旧，不表示已经发生。"}, {"text": "怡然", "is_correct": false, "explanation": "怡然 yírán 与 已然 yǐrán 第一个音节声调不同（第二声与第三声），意思是安适愉快的样子。"}, {"text": "易燃", "is_correct": false, "explanation": "易燃 yìrán 与 已然 yǐrán 第一个音节声调不同（第四声与第三声），意思是容易燃烧。"}], "explanations": {"已然": "正确答案。已然是副词，表示已经发生或已经达到某种状态。", "依然": "依然 yīrán 与 已然 yǐrán 第一个音节声调不同（第一声与第三声），意思是仍旧，不表示已经发生。", "怡然": "怡然 yírán 与 已然 yǐrán 第一个音节声调不同（第二声与第三声），意思是安适愉快的样子。", "易燃": "易燃 yìrán 与 已然 yǐrán 第一个音节声调不同（第四声与第三声），意思是容易燃烧。"}, "sentence_index": null, "correct_answer": "已然"}, "level_3": {"options": [{"text": "已然", "is_correct": true, "explanation": "正确答案。已然表示设计已经升华为文化镜像，与“由此”后面的结论相符。"}, {"text": "尚未", "is_correct": false, "explanation": "体貌：尚未表示动作还没有实现，与“折射出”所述的既成结果相矛盾。"}, {"text": "毫不", "is_correct": false, "explanation": "语法：毫不只能修饰少数双音节动词或形容词（如毫不犹豫），不能修饰“升华为”。"}, {"text": "不必", "is_correct": false, "explanation": "语义：不必表示没有必要，与“原本功能性的设计”已经发生变化这一既成事实不合。"}], "explanations": {"已然": "正确答案。已然表示设计已经升华为文化镜像，与“由此”后面的结论相符。", "尚未": "体貌：尚未表示动作还没有实现，与“折射出”所述的既成结果相矛盾。", "毫不": "语法：毫不只能修饰少数双音节动词或形容词（如毫不犹豫），不能修饰“升华为”。", "不必": "语义：不必表示没有必要，与“原本功能性的设计”已经发生变化这一既成事实不合。"}, "sentence_index": 0, "correct_answer": "已然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已然明天去北京。", "explanation": "这里应该用〈将〉。已然表示已经发生或已经达到的状态，不能用来说尚未发生的将来行为。"}, {"text": "我每天已然吃早饭，身体很好。", "explanation": "这里应该用〈总是〉。已然表示某件事已经发生并完成，不用于每天重复的习惯。"}, {"text": "请你已然坐下来吧。", "explanation": "这里是请求，应直接说“请你坐下来吧”。已然表示已经达到的状态，不能用于要求对方去做的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已然", "is_correct": true, "explanation": "正确答案。已然表示她已经忘记了那件小事，与后面的“了”所表示的完成相符。"}, {"text": "将", "is_correct": false, "explanation": "体貌：将表示将来，与后面的“了”所表示的完成相冲突。"}, {"text": "没", "is_correct": false, "explanation": "语义：没否定动作，与“了”所表示的已完成语义相矛盾。"}, {"text": "正", "is_correct": false, "explanation": "体貌：正表示动作进行中，与“了”所表示的完成相冲突。"}], "explanations": {"已然": "正确答案。已然表示她已经忘记了那件小事，与后面的“了”所表示的完成相符。", "将": "体貌：将表示将来，与后面的“了”所表示的完成相冲突。", "没": "语义：没否定动作，与“了”所表示的已完成语义相矛盾。", "正": "体貌：正表示动作进行中，与“了”所表示的完成相冲突。"}, "sentence_index": 6, "correct_answer": "已然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还在吃饭，已然吃完了。", "explanation": "已然表示动作已经完成，与“还在吃饭”所说的正在进行相矛盾。"}, {"text": "如果天气好，我们已然去公园。", "explanation": "这里应该用〈要〉。已然表示已经发生的事，与“如果天气好”这一尚未确定的假设相矛盾，应改用将来时。"}, {"text": "这件事我已然还没做完。", "explanation": "已然表示已经发生，与“还没做完”的否定结果相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很已然走了，我们别等了。", "corrected_sentence": "他已然走了，我们别等了。", "error_description": "错误形式“他很已然走了”在副词“已然”前加了程度副词“很”，副词不能再由“很”修饰。正确形式“他已然走了”直接用“已然”修饰动词“走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子已然的睡着了。", "corrected_sentence": "孩子已然睡着了。", "error_description": "错误形式“孩子已然的睡着了”在副词“已然”后多加了“的”，副词后不能加“的”。正确形式“孩子已然睡着了”直接用“已然”修饰动词“睡着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
