INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12562, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示刚好、恰好，或强调时间、程度等正好合适。", "primary_collocate": null, "pronunciation": "qià", "ipa": "tɕʰja˥˩", "syllable_count": 1, "sentences": [{"text": "从历史纵深来看，这一标志的演化轨迹恰与全球环保运动的阶段性跃迁相呼应。", "target_word": "恰", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我刚走到门口，恰有人来敲门。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话恰是我想说的。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我进门时，电话恰在响。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的大小恰合我的脚。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来访时，我恰在书房工作。", "target_word": "恰", "complexity_tier": "T3", "furigana": "tā lái fǎng shí, wǒ qià zài shūfáng gōngzuò.", "sentence_source": "generated"}, {"text": "她说的恰与事实相反。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课铃声响起，老师恰讲完最后一句话。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字恰是一百。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到时，雨恰停了。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰好", "label": "复合"}, {"form": "恰巧", "label": "复合"}], "register": "书面", "sense_fingerprint": "恰|副词|刚好、正好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：听到的是 qià（第四声），意思是刚好、正好。"}, {"text": "下", "is_correct": false, "explanation": "xià（第四声）与 qià 声母不同（x 与 q），意思是下面。"}, {"text": "卡", "is_correct": false, "explanation": "qiǎ（第三声）与 qià 只有声调不同，意思是卡住。"}, {"text": "掐", "is_correct": false, "explanation": "qiā（第一声）与 qià 只有声调不同，意思是用手指按压。"}, {"text": "嫁", "is_correct": false, "explanation": "jià（第四声）与 qià 声母不同（j 与 q），意思是出嫁。"}], "explanations": {"恰": "恰：听到的是 qià（第四声），意思是刚好、正好。", "下": "xià（第四声）与 qià 声母不同（x 与 q），意思是下面。", "卡": "qiǎ（第三声）与 qià 只有声调不同，意思是卡住。", "掐": "qiā（第一声）与 qià 只有声调不同，意思是用手指按压。", "嫁": "jià（第四声）与 qià 声母不同（j 与 q），意思是出嫁。"}, "sentence_index": null, "correct_answer": "恰"}, "level_3": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：副词，表示刚好、正好，此处说演化轨迹正好与环保运动相合。"}, {"text": "挺", "is_correct": false, "explanation": "语域：「挺」是口语口吻，与这句书面语的语域不合。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词或心理动词，不能修饰「与……相呼应」这样的结构。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能直接修饰「与……相呼应」这样的结构。"}], "explanations": {"恰": "恰：副词，表示刚好、正好，此处说演化轨迹正好与环保运动相合。", "挺": "语域：「挺」是口语口吻，与这句书面语的语域不合。", "很": "搭配：「很」修饰形容词或心理动词，不能修饰「与……相呼应」这样的结构。", "非常": "搭配：「非常」修饰形容词或心理动词，不能直接修饰「与……相呼应」这样的结构。"}, "sentence_index": 0, "correct_answer": "恰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想帮他，他恰偏不让我帮。", "explanation": "这里应该去掉〈恰〉。恰表示刚好、正好，与〈偏〉叠用不通；“他偏不让我帮”才对。"}, {"text": "这件事恰很重要。", "explanation": "这里应该用〈很〉。恰表示正好、刚好，不表示程度高；“这件事很重要”才对。"}, {"text": "他恰以为你不来了。", "explanation": "这里应该用〈还〉。恰表示正好，不表示出乎意料；“他还以为你不来了”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12562, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：听到的是 qià（第四声），意思是刚好、正好。"}, {"text": "怯", "is_correct": false, "explanation": "qiè（第四声）与 qià 韵母不同（e 与 a），意思是害怕。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 qià 声母不同（j 与 q），意思是价格。"}, {"text": "架", "is_correct": false, "explanation": "jià（第四声）与 qià 声母不同（j 与 q），意思是架子。"}], "explanations": {"恰": "恰：听到的是 qià（第四声），意思是刚好、正好。", "怯": "qiè（第四声）与 qià 韵母不同（e 与 a），意思是害怕。", "价": "jià（第四声）与 qià 声母不同（j 与 q），意思是价格。", "架": "jià（第四声）与 qià 声母不同（j 与 q），意思是架子。"}, "sentence_index": null, "correct_answer": "恰"}, "level_3": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：副词，表示正好、恰好相反，此处说她说的话与事实正好相反。"}, {"text": "太", "is_correct": false, "explanation": "搭配：「太」只修饰形容词，不能修饰「与事实相反」。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」表示程度高，不能修饰「与事实相反」这样的介宾结构，也不表示正好。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然，与「说的话与事实相反」的关系不合。"}], "explanations": {"恰": "恰：副词，表示正好、恰好相反，此处说她说的话与事实正好相反。", "太": "搭配：「太」只修饰形容词，不能修饰「与事实相反」。", "非常": "搭配：「非常」表示程度高，不能修饰「与事实相反」这样的介宾结构，也不表示正好。", "忽然": "语义：「忽然」表示突然，与「说的话与事实相反」的关系不合。"}, "sentence_index": 6, "correct_answer": "恰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一说，我恰就明白了。", "explanation": "这里应该只用〈就〉。恰表示正好、刚好，不表示“一……就……”的承接，与〈就〉叠用不通；“他一说，我就明白了”才对。"}, {"text": "他恰常常迟到。", "explanation": "这里应该用〈经常〉。恰表示正好、刚好，不表示次数多；“他经常迟到”才对。"}, {"text": "他不但没生气，恰笑了。", "explanation": "这里应该用〈反而〉。恰不表示与前面情况相反的转折；“他不但没生气，反而笑了”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车票是恰十块钱。", "corrected_sentence": "车票恰是十块钱。", "error_description": "“恰”是副词，应放在“是”之前，说“车票恰是十块钱”；“是恰十块钱”把“恰”放在“是”后面，位置错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室里有恰一个空位。", "corrected_sentence": "教室里恰有一个空位。", "error_description": "“恰”应放在“有”之前修饰整个存现句，说“恰有一个空位”；“有恰一个”把“恰”放在“有”与数量之间，位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
