INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12563, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物发展变化过程中，根据特定标准或时间划分出的一个段落或时期所表现出的属性或状态。", "primary_collocate": null, "pronunciation": "jiē duàn xìng", "ipa": "tɕjɛ˥ twan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "从历史纵深来看，这一标志的演化轨迹恰与全球环保运动的阶段性跃迁相呼应。", "target_word": "阶段性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这只是阶段性的结果。", "target_word": "阶段性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们取得了阶段性成果。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司公布了阶段性计划。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题是阶段性的，会过去。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的阶段性考试下周开始。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的进步有阶段性的特点。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阶段性的工作已经完成了。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变冷只是阶段性的现象。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要做阶段性的总结。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "阶段性：属于发展过程中某一阶段的，常修饰成果、计划、总结等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阶段性", "is_correct": true, "explanation": "正确：阶段性修饰“跃迁”，指发展过程中的某一段落，与“演化轨迹”的语境相符。"}, {"text": "地域性", "is_correct": false, "explanation": "语义：地域性指局部地区的特征，与“全球”的范围相冲突。"}, {"text": "瞬时性", "is_correct": false, "explanation": "语义：瞬时性指极短时间内完成，与“历史纵深”“演化轨迹”的长期过程冲突。"}, {"text": "静态性", "is_correct": false, "explanation": "语义：静态性指静止不变，与“跃迁”“演化”的动态过程相反。"}], "explanations": {"阶段性": "正确：阶段性修饰“跃迁”，指发展过程中的某一段落，与“演化轨迹”的语境相符。", "地域性": "语义：地域性指局部地区的特征，与“全球”的范围相冲突。", "瞬时性": "语义：瞬时性指极短时间内完成，与“历史纵深”“演化轨迹”的长期过程冲突。", "静态性": "语义：静态性指静止不变，与“跃迁”“演化”的动态过程相反。"}, "sentence_index": 0, "correct_answer": "阶段性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张木椅是阶段性的，可以折叠起来。", "explanation": "这里应该用〈折叠式〉。阶段性强调发展过程中某一段时期的状况，说椅子能折叠要用折叠式。"}, {"text": "这杯水很阶段性，刚倒出来很烫。", "explanation": "这里误把阶段性当成描述温度的〈烫〉。阶段性指发展过程中某一时期的状况，不能用来形容水的温度，应该用〈烫〉。"}, {"text": "这场比赛很阶段性，观众看得很过瘾。", "explanation": "这里误把阶段性当成〈精彩〉的意思。阶段性指发展过程中分段的特点，评价比赛精彩与否要用精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阶段性", "is_correct": true, "explanation": "正确：阶段性修饰“特点”，说明进步呈现分段的特征。"}, {"text": "退化性", "is_correct": false, "explanation": "语义：退化性指功能或水平倒退，与“进步”的方向相反。"}, {"text": "静止性", "is_correct": false, "explanation": "语义：静止性指不动、没有变化，与“进步”的发展含义冲突。"}, {"text": "群体性", "is_correct": false, "explanation": "搭配：“他的进步”指个人的变化，不能用群体性来修饰。"}], "explanations": {"阶段性": "正确：阶段性修饰“特点”，说明进步呈现分段的特征。", "退化性": "语义：退化性指功能或水平倒退，与“进步”的方向相反。", "静止性": "语义：静止性指不动、没有变化，与“进步”的发展含义冲突。", "群体性": "搭配：“他的进步”指个人的变化，不能用群体性来修饰。"}, "sentence_index": 6, "correct_answer": "阶段性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很阶段性，坐起来很舒服。", "explanation": "这里误把阶段性当成描述实物〈舒适〉的形容词。阶段性只说明发展过程中某一时期的状况，形容椅子应用〈舒适〉。"}, {"text": "我们要吃阶段性的早餐，每天都不一样。", "explanation": "这里误把阶段性当成〈多样〉的意思。阶段性指分段发展的某一时期的状况，每天口味不同的早餐应用〈多样〉。"}, {"text": "我的名字很阶段性，从出生到现在一直没变过。", "explanation": "这里误把阶段性当成〈固定〉的意思。阶段性指变化过程中分段出现的状况，名字长期不变应用〈固定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的工作有很阶段性的收获。", "corrected_sentence": "他们的工作有阶段性的收获。", "error_description": "错误形式“有很阶段性的收获”在“阶段性”前加了程度副词“很”，“阶段性”只作定语，不能受“很”修饰。正确形式“有阶段性的收获”应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们写阶段性地总结。", "corrected_sentence": "老师让我们写阶段性的总结。", "error_description": "错误形式“阶段性地总结”误用了状语标记“地”；这里“总结”是名词，阶段性作定语应用“的”。正确形式为“阶段性的总结”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
