INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12564, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指量子力学中粒子从一个状态突然转变到另一个状态；也比喻事物发生质的飞跃或大幅度提升。", "primary_collocate": null, "pronunciation": "yuè qiān", "ipa": "ɥe˥˩ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "从历史纵深来看，这一标志的演化轨迹恰与全球环保运动的阶段性跃迁相呼应。", "target_word": "跃迁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电子吸收能量后，会从低能级跃迁到高能级。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原子吸收光子，电子就会跃迁到更高的轨道。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司靠新技术，从地方品牌跃迁为全国品牌。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队经过改革，实力一下子跃迁到了联赛前列。", "target_word": "跃迁", "complexity_tier": "T3", "furigana": "zhè zhī qiú duì jīng guò gǎi gé, shí lì yí xiàzi yuèqiān dào le liánsài qiánliè.", "sentence_source": "generated"}, {"text": "这座城市靠新兴产业，经济很快跃迁到了新阶段。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光的产生，来自电子在能级之间的跃迁。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现，电子跃迁时会放出光。", "target_word": "跃迁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次改革后，学校的教学质量跃迁到了新的高度。", "target_word": "跃迁", "complexity_tier": "T3", "furigana": "zhè cì gǎi gé hòu, xuéxiào de jiàoxué zhìliàng yuèqiān dào le xīn de gāodù.", "sentence_source": "generated"}, {"text": "要想事业跃迁，就要先学会不断积累经验。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跃迁了", "label": "完成体"}, {"form": "跃迁过", "label": "经历体"}, {"form": "能级跃迁", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "粒子能级突变，或事物发生质的飞跃、大幅提升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跃迁", "is_correct": true, "explanation": "跃迁：指质的飞跃，与“演化轨迹”和“阶段性”相合，符合句意。"}, {"text": "平移", "is_correct": false, "explanation": "语义：“平移”指整体位置的移动，不指演化中的质变，与“演化轨迹”不相合。"}, {"text": "振动", "is_correct": false, "explanation": "语义：“振动”指往复摆动，与朝一个方向推进的演化不符。"}, {"text": "倒影", "is_correct": false, "explanation": "搭配：“倒影”是映照出的影像，不能用“阶段性”修饰，也不能与“相呼应”的演化过程搭配。"}], "explanations": {"跃迁": "跃迁：指质的飞跃，与“演化轨迹”和“阶段性”相合，符合句意。", "平移": "语义：“平移”指整体位置的移动，不指演化中的质变，与“演化轨迹”不相合。", "振动": "语义：“振动”指往复摆动，与朝一个方向推进的演化不符。", "倒影": "搭配：“倒影”是映照出的影像，不能用“阶段性”修饰，也不能与“相呼应”的演化过程搭配。"}, "sentence_index": 0, "correct_answer": "跃迁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家小公司的注册资金跃迁了一块钱。", "explanation": "这里应该用〈增加〉。跃迁指大幅度的飞跃，只增加一块钱的微小变化不能用跃迁。"}, {"text": "这个孩子的性格慢慢地从幼稚跃迁到成熟。", "explanation": "这里应该用〈过渡〉。跃迁是一下子转到更高状态，不能与“慢慢地”搭配；渐进的转变要用过渡。"}, {"text": "他的数学成绩一直在稳步跃迁。", "explanation": "这里应该用〈提高〉。跃迁是突然的质变，不能用于「稳步」这种渐进过程；成绩逐步上升要用提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跃迁", "is_correct": true, "explanation": "跃迁：指电子在能级之间突然转变，与“能级之间”和“激光”的语境相合。"}, {"text": "摆动", "is_correct": false, "explanation": "语义：“摆动”指来回晃动，不指能级之间的状态突变。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”的主体须是能自主行走的人或动物，不能用于电子。"}, {"text": "闲逛", "is_correct": false, "explanation": "搭配：“闲逛”指悠闲地四处走动，不能用来描述电子在能级间的变化。"}], "explanations": {"跃迁": "跃迁：指电子在能级之间突然转变，与“能级之间”和“激光”的语境相合。", "摆动": "语义：“摆动”指来回晃动，不指能级之间的状态突变。", "散步": "搭配：“散步”的主体须是能自主行走的人或动物，不能用于电子。", "闲逛": "搭配：“闲逛”指悠闲地四处走动，不能用来描述电子在能级间的变化。"}, "sentence_index": 6, "correct_answer": "跃迁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家企业的年利润跃迁，每年只涨一点点。", "explanation": "这里应该用〈缓慢增长〉。跃迁指大幅度的飞跃，与“每年只涨一点点”的小幅渐进相矛盾。"}, {"text": "这次改革后，工厂的事故率跃迁了，一个月只减少了一起。", "explanation": "这里应该用〈下降〉。跃迁是大幅度的提升，与“只减少了一起”的小幅变化相矛盾，减少要用下降。"}, {"text": "这个地区的治安去年跃迁到了很低的水平。", "explanation": "这里应该用〈滑落〉。跃迁是向更高层次的飞跃，不能用于“很低的水平”这种向下的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电子吸收光子后，会跃迁上激发态。", "corrected_sentence": "电子吸收光子后，会跃迁到激发态。", "error_description": "错误：“跃迁上激发态”。正确：“跃迁到激发态”。表示状态转变到达某处，应用补语“到”，不用“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂通过技术改造，生产水平跃迁了到新阶段。", "corrected_sentence": "工厂通过技术改造，生产水平跃迁到了新阶段。", "error_description": "错误：“跃迁了到”。正确：“跃迁到了”。“了”应放在补语“到”之后，不能插在动词和“到”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
