INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彼此一呼一应，形容配合默契或相互关联。", "primary_collocate": null, "pronunciation": "hū yìng", "ipa": "xu˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "从历史纵深来看，这一标志的演化轨迹恰与全球环保运动的阶段性跃迁相呼应。", "target_word": "呼应", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "文章的开头和结尾互相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两句话前后呼应，很有力量。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的树和屋里的花互相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位演员配合默契，互相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行动与他说的话相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间的颜色和窗帘的颜色呼应得很好。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥与对岸的塔遥相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求作文首尾呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的政策互相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遥相呼应", "label": "复合"}, {"form": "首尾呼应", "label": "复合"}, {"form": "前后呼应", "label": "复合"}], "register": "书面", "sense_fingerprint": "呼应|动词|相互配合、相互关联", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼应", "is_correct": true, "explanation": "呼应：动词，表示彼此一呼一应、相互关联，此处说轨迹与运动相互配合。"}, {"text": "相识", "is_correct": false, "explanation": "搭配：「相识」指人与人互相认识，「轨迹」与「运动」不能相识。"}, {"text": "相隔", "is_correct": false, "explanation": "语义：「相隔」表示距离上的分隔，此句说的是彼此关联，不是空间间隔。"}, {"text": "相爱", "is_correct": false, "explanation": "搭配：「相爱」用于人之间的感情，不能用于「轨迹」与「运动」。"}], "explanations": {"呼应": "呼应：动词，表示彼此一呼一应、相互关联，此处说轨迹与运动相互配合。", "相识": "搭配：「相识」指人与人互相认识，「轨迹」与「运动」不能相识。", "相隔": "语义：「相隔」表示距离上的分隔，此句说的是彼此关联，不是空间间隔。", "相爱": "搭配：「相爱」用于人之间的感情，不能用于「轨迹」与「运动」。"}, "sentence_index": 0, "correct_answer": "呼应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在门口呼应一下屋子。", "explanation": "这里应该用〈看〉。呼应指彼此相配、相互关联，或一方回答另一方，不指观看；“我在门口看了一下屋子”才对。"}, {"text": "他把我的话呼应了一遍。", "explanation": "这里应该用〈重复〉。呼应指彼此相配、相互关联，不指照原样说一遍；“把我的话重复了一遍”才对。"}, {"text": "他很会呼应客人。", "explanation": "这里应该用〈招待〉。呼应指彼此相配、相互关联，不指接待客人；“很会招待客人”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼应", "is_correct": true, "explanation": "呼应：动词，表示彼此相配、相互关联，此处说颜色与窗帘配合得好。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：「排斥」表示互相推开，与「得很好」所说的相配之义相反。"}, {"text": "争吵", "is_correct": false, "explanation": "搭配：颜色不能争吵，「争吵」与「颜色」搭配不当。"}, {"text": "冲撞", "is_correct": false, "explanation": "搭配：颜色不会冲撞，「冲撞」与「颜色」搭配不当，且与「得很好」所说的相配之义不合。"}], "explanations": {"呼应": "呼应：动词，表示彼此相配、相互关联，此处说颜色与窗帘配合得好。", "排斥": "语义：「排斥」表示互相推开，与「得很好」所说的相配之义相反。", "争吵": "搭配：颜色不能争吵，「争吵」与「颜色」搭配不当。", "冲撞": "搭配：颜色不会冲撞，「冲撞」与「颜色」搭配不当，且与「得很好」所说的相配之义不合。"}, "sentence_index": 6, "correct_answer": "呼应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "磁铁能呼应周围的铁屑。", "explanation": "这里应该用〈感应〉。呼应指彼此相配、关联，不指物理上的感应吸引。"}, {"text": "他没有呼应我的问题。", "explanation": "这里应该用〈回应〉。呼应强调彼此相配、相互关联，不用于一般地答复问题。"}, {"text": "他很会呼应，见人就问好。", "explanation": "这里应该用〈问候〉。呼应指彼此相配、相互关联，或一方回答另一方，不指主动问候；“见人就问好”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司的计划互相呼应着了。", "corrected_sentence": "两家公司的计划互相呼应了。", "error_description": "动态助词错误：“呼应”完成义要用“了”，说“互相呼应了”；“着”表示持续，不能与“了”叠用，“呼应着了”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两幅画的风格呼应的很好。", "corrected_sentence": "这两幅画的风格呼应得很好。", "error_description": "结构助词错误：“呼应”后的程度补语应用“得”，说“呼应得很好”；误用“的”，说“呼应的很好”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
