INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12567, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "清除不需要的东西，使整洁。", "primary_collocate": null, "pronunciation": "qīng lǐ", "ipa": "tɕʰiŋ˥ li˨˩", "syllable_count": 2, "sentences": [{"text": "它见证了从早期以清理行动为主的“浅绿”思潮，向强调系统变革的“深绿”哲学的转型。", "target_word": "清理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "周末我们一起清理房间。", "target_word": "清理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想清理一下手机里没用的照片。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以前，我清理了很多旧衣服。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年年底都会清理仓库里的旧货。", "target_word": "清理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你清理一下电脑里不用的文件。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈正在清理冰箱里过期的食物。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们清理书包里没用的东西。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把抽屉里的旧东西都清理了。", "target_word": "清理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬进新家前，先清理不要的东西。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "清理了", "label": "完成体标"}, {"form": "清理过", "label": "经历体标"}, {"form": "清理清理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "清理：清除不需要的旧物、文件等，使环境或空间整洁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12567, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清理", "is_correct": true, "explanation": "清理：清除不需要的东西，使整洁，即本词。"}, {"text": "情理", "is_correct": false, "explanation": "「情理」第一音节 qíng（第二声）与 qīng（第一声）只差声调，意思是道理，与清除杂物无关。"}, {"text": "倾力", "is_correct": false, "explanation": "「倾力」第二音节 lì（第四声）与 lǐ（第三声）只差声调，意思是全力以赴。"}, {"text": "经理", "is_correct": false, "explanation": "「经理」声母 j 与 q 不同，意思是负责管理的人。"}, {"text": "清丽", "is_correct": false, "explanation": "「清丽」第二音节 lì（第四声）与 lǐ（第三声）声调不同，意思是清秀美丽。"}], "explanations": {"清理": "清理：清除不需要的东西，使整洁，即本词。", "情理": "「情理」第一音节 qíng（第二声）与 qīng（第一声）只差声调，意思是道理，与清除杂物无关。", "倾力": "「倾力」第二音节 lì（第四声）与 lǐ（第三声）只差声调，意思是全力以赴。", "经理": "「经理」声母 j 与 q 不同，意思是负责管理的人。", "清丽": "「清丽」第二音节 lì（第四声）与 lǐ（第三声）声调不同，意思是清秀美丽。"}, "sentence_index": null, "correct_answer": "清理"}, "level_3": {"options": [{"text": "清理", "is_correct": true, "explanation": "「清理」与「行动」组成定语，指清除不要东西的行动，符合语境。"}, {"text": "思考", "is_correct": false, "explanation": "语义：「思考」是心理活动，不能修饰清除杂物的“行动”。"}, {"text": "相信", "is_correct": false, "explanation": "搭配：「相信」不能修饰「行动」，句中的“行动”指具体的清除动作。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：「讨厌」表示厌恶的情绪，不能用来描述一种具体的行动。"}], "explanations": {"清理": "「清理」与「行动」组成定语，指清除不要东西的行动，符合语境。", "思考": "语义：「思考」是心理活动，不能修饰清除杂物的“行动”。", "相信": "搭配：「相信」不能修饰「行动」，句中的“行动”指具体的清除动作。", "讨厌": "语义：「讨厌」表示厌恶的情绪，不能用来描述一种具体的行动。"}, "sentence_index": 0, "correct_answer": "清理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上清理一杯咖啡。", "explanation": "这里应该用〈喝〉。清理指清除不要的东西，喝咖啡要用喝。"}, {"text": "这次比赛他的表现清理得很好。", "explanation": "这里应该用〈发挥〉。清理指清除不要的东西，表现要用发挥。"}, {"text": "他把这首歌清理得很熟。", "explanation": "这里应该用〈唱〉。清理指清除不要的东西，把歌练熟要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清理", "is_correct": true, "explanation": "「清理」指清除不要的食物，与“过期的食物”相符。"}, {"text": "种植", "is_correct": false, "explanation": "语义：食物不是种出来的，句中“过期的食物”也不能被种植。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“冰箱里”的食物已在家中，不能说“购买冰箱里的食物”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：过期的食物不值得欣赏，与句意不符。"}], "explanations": {"清理": "「清理」指清除不要的食物，与“过期的食物”相符。", "种植": "语义：食物不是种出来的，句中“过期的食物”也不能被种植。", "购买": "搭配：“冰箱里”的食物已在家中，不能说“购买冰箱里的食物”。", "欣赏": "语义：过期的食物不值得欣赏，与句意不符。"}, "sentence_index": 6, "correct_answer": "清理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃饭前要清理双手。", "explanation": "这里应该用〈清洗〉。清理指清除不要的东西，洗手要用清洗。"}, {"text": "他已经清理完了一道数学题。", "explanation": "这里应该用〈做完〉。清理指清除不要的东西，做题要用做完。"}, {"text": "他很快清理了这场考试。", "explanation": "这里应该用〈通过〉。清理指清除不要的东西，考试要用通过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房间清理很干净。", "corrected_sentence": "他把房间清理得很干净。", "error_description": "“清理”后接程度补语“很干净”时要用“得”连接，应说“清理得很干净”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天把那个旧抽屉清理。", "corrected_sentence": "我昨天把那个旧抽屉清理了。", "error_description": "“把”字句中的动词后要带“了”或其他成分，应说“清理了”，不能只说“清理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
