INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12569, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在一定时期内，社会上流行的、具有广泛影响的思想倾向或潮流。", "primary_collocate": null, "pronunciation": "sī cháo", "ipa": "sɨ˥ ʈʂʰaʊ˧˥", "syllable_count": 2, "sentences": [{"text": "它见证了从早期以清理行动为主的“浅绿”思潮，向强调系统变革的“深绿”哲学的转型。", "target_word": "思潮", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "二十世纪初，中国出现了新的思潮。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种思潮影响了很多年轻人。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会思潮常常随着时代改变。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个时期，文学思潮非常活跃。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一股新思潮在大学里慢慢兴起。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了西方的哲学思潮。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了五四时期的思潮。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的思潮在这个时代互相影响。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这股思潮后来影响了整个国家。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股思潮", "label": "量词"}, {"form": "社会思潮", "label": "复合"}, {"form": "文学思潮", "label": "复合"}], "register": "书面", "sense_fingerprint": "思潮：一个时期内社会上流行并有广泛影响的思想倾向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12569, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思潮", "is_correct": true, "explanation": "正确。“思潮”指一个时期社会上流行的思想倾向，与“浅绿”“深绿”的理念对比及“哲学”的转型相符，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为“浅绿”与“深绿”之间转型的对象。"}, {"text": "演员", "is_correct": false, "explanation": "配价：“转型”的对象应是理念或观念，演员是人，不能作为从一种哲学转向另一种哲学的对象。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：“浅绿”“深绿”修饰的是理念或运动，不能修饰石油这类能源物质。"}], "explanations": {"思潮": "正确。“思潮”指一个时期社会上流行的思想倾向，与“浅绿”“深绿”的理念对比及“哲学”的转型相符，句意通顺。", "天气": "语义：天气是自然现象，不能作为“浅绿”与“深绿”之间转型的对象。", "演员": "配价：“转型”的对象应是理念或观念，演员是人，不能作为从一种哲学转向另一种哲学的对象。", "石油": "搭配：“浅绿”“深绿”修饰的是理念或运动，不能修饰石油这类能源物质。"}, "sentence_index": 0, "correct_answer": "思潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的思潮一直很开明。", "explanation": "这里应该用〈思想〉。思潮指一个时期社会上流行的思想倾向，多指群体，不用来说个人的想法。"}, {"text": "我对这件事的思潮很明确。", "explanation": "这里应该用〈看法〉。思潮指社会上流行的思想倾向，不指个人对某件事的看法。"}, {"text": "这件衣服是今年的思潮。", "explanation": "这里应该用〈时尚〉。思潮指思想上的潮流，不用于衣服等物品的流行款式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思潮", "is_correct": true, "explanation": "正确。“哲学思潮”指一个时期流行的哲学思想倾向，与“西方的”“介绍”搭配自然，句意通顺。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能作为“哲学”的类别或内容被介绍。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“哲学”前可接“思潮”“流派”等词，不能接运动项目。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，与书中所介绍的哲学内容毫无关联。"}], "explanations": {"思潮": "正确。“哲学思潮”指一个时期流行的哲学思想倾向，与“西方的”“介绍”搭配自然，句意通顺。", "面包": "语义：面包是食物，不能作为“哲学”的类别或内容被介绍。", "足球": "搭配：“哲学”前可接“思潮”“流派”等词，不能接运动项目。", "地铁": "语义：地铁是交通工具，与书中所介绍的哲学内容毫无关联。"}, "sentence_index": 6, "correct_answer": "思潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张思潮后来影响了整个国家。", "explanation": "这里应该用〈股〉。“张”用于纸张、桌子等平面的东西，思潮不用“张”计量。"}, {"text": "这座思潮后来影响了整个国家。", "explanation": "这里应该用〈股〉。“座”用于山、房屋等大型固定的东西，思潮不用“座”计量。"}, {"text": "这把思潮后来影响了整个国家。", "explanation": "这里应该用〈股〉。“把”用于有把手的器具，如椅子、雨伞，不用于思潮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二十年前，国内兴起了一只新思潮。", "corrected_sentence": "二十年前，国内兴起了一股新思潮。", "error_description": "量词错误：“只”多用于动物、船、鞋等个体事物，不能修饰思潮。思潮可用“股”计量，如“一股新思潮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一新股思潮在城市里慢慢兴起。", "corrected_sentence": "一股新思潮在城市里慢慢兴起。", "error_description": "语序错误：“新”应放在量词“股”之后、“思潮”之前，应说“一股新思潮”，不能说“一新股思潮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
