INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "会议或活动中待讨论或处理的事项的列表。", "primary_collocate": null, "pronunciation": "yì chéng", "ipa": "i˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "会议的议程需要主任在开会前统一确定。", "target_word": "议程", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "会议的议程已经发给大家了。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的议程有三项，第一项是预算。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先看一下议程，再决定去不去。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主任把新的议程贴在了墙上。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的议程很满，没有休息时间。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按照议程，一项一项地讨论。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议程上写着，下午两点开始发言。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提前改了议程，把报告放在最后。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个议程太长了，会开不完。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "議程", "label": "繁体"}, {"form": "议程表", "label": "复合"}], "register": "书面", "sense_fingerprint": "会议或活动中待处理事项的列表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“议程”指会议要讨论的事项清单，读作 yì chéng。"}, {"text": "一成", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是十分之一。"}, {"text": "以诚", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用真诚的态度。"}, {"text": "已成", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经形成。"}], "explanations": {"议程": "正确：“议程”指会议要讨论的事项清单，读作 yì chéng。", "一成": "yī（第一声）与 yì（第四声）声调不同，意思是十分之一。", "以诚": "yǐ（第三声）与 yì（第四声）声调不同，意思是用真诚的态度。", "已成": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经形成。"}, "sentence_index": null, "correct_answer": "议程"}, "level_3": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“会议的议程”指会议要讨论的事项，由主任在开会前确定，与语境相合。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，会议没有体温，也不需要主任确定。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指食物的滋味，不能指会议要讨论的事项。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：会议没有颜色可言，开会前要确定的是讨论事项。"}], "explanations": {"议程": "正确：“会议的议程”指会议要讨论的事项，由主任在开会前确定，与语境相合。", "体温": "语义：体温是身体的温度，会议没有体温，也不需要主任确定。", "味道": "语义：味道指食物的滋味，不能指会议要讨论的事项。", "颜色": "语义：会议没有颜色可言，开会前要确定的是讨论事项。"}, "sentence_index": 0, "correct_answer": "议程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的操作议程很复杂，要仔细学。", "explanation": "这里应该用〈流程〉。议程指会议要讨论的事项清单，机器的操作步骤要说“流程”，不能说“议程”。"}, {"text": "这首歌的议程很好听。", "explanation": "这里应该用〈旋律〉。议程是会议要讨论的事项清单，歌曲好听的是“旋律”，不能说“议程”。"}, {"text": "饭店的议程上有很多好吃的菜。", "explanation": "这里应该用〈菜单〉。菜单是列出菜品的清单，议程不能用来点菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12570, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“议程”指会议要讨论的事项清单，读作 yì chéng。"}, {"text": "一程", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是一段路程。"}, {"text": "一城", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是一座城市。"}, {"text": "已成", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经形成。"}], "explanations": {"议程": "正确：“议程”指会议要讨论的事项清单，读作 yì chéng。", "一程": "yī（第一声）与 yì（第四声）声调不同，意思是一段路程。", "一城": "yī（第一声）与 yì（第四声）声调不同，意思是一座城市。", "已成": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经形成。"}, "sentence_index": null, "correct_answer": "议程"}, "level_3": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“按照议程”指按会议安排的事项，与“一项一项地讨论”相合。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，不是可以逐项讨论的事项，句意不通。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：“乐谱”是记录音乐的符号，与“讨论”无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“按照天气”后不能接“一项一项地讨论”，天气不是可以逐项讨论的事项。"}], "explanations": {"议程": "正确：“按照议程”指按会议安排的事项，与“一项一项地讨论”相合。", "体温": "语义：“体温”是身体的温度，不是可以逐项讨论的事项，句意不通。", "乐谱": "语义：“乐谱”是记录音乐的符号，与“讨论”无关。", "天气": "搭配：“按照天气”后不能接“一项一项地讨论”，天气不是可以逐项讨论的事项。"}, "sentence_index": 6, "correct_answer": "议程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这趟火车的议程很准确。", "explanation": "这里应该用〈时间表〉。议程是会议要讨论的事项清单，火车的发车和到站时间要说“时间表”，不能说“议程”。"}, {"text": "剧本的议程很感人。", "explanation": "这里应该用〈情节〉。议程是会议事项清单，不能用来形容故事感人。"}, {"text": "这道菜的议程很简单。", "explanation": "这里应该用〈做法〉。议程是会议讨论的事项，菜的做法不能说成议程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿了一把议程。", "corrected_sentence": "他拿了一份议程。", "error_description": "量词错误：纸质的议程用“份”，“把”用于有柄的东西，不能用来数议程，应说“一份议程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把议程的改了一下。", "corrected_sentence": "他把议程改了一下。", "error_description": "结构错误：“议程”后面不能加“的”，应说“把议程改了一下”，“的”多余，使“议程的改了”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
