INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12573, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用黑白方块组成的图形，用来存储信息，用手机扫描可以快速访问网页或支付。", "primary_collocate": null, "pronunciation": "èr wéi mǎ", "ipa": "ɑɻ˥˩ weɪ˧˥ ma˨˩˦", "syllable_count": 3, "sentences": [{"text": "请用手机扫一下这个二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口贴着一张二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你扫二维码就能付钱。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上的二维码，扫一下就能点菜。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把二维码发给了我。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扫二维码以后，网页就打开了。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票上的二维码坏了，扫不出来。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的二维码可以用来付钱。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把二维码放在了书的后面。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，我没法扫二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个二维码", "label": "量词"}, {"form": "一张二维码", "label": "量词"}, {"form": "二維碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "黑白方块组成、可用手机扫描访问网页或付款的图形码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水杯", "is_correct": false, "explanation": "搭配：“扫”的对象是码或图形，不能说扫水杯。"}, {"text": "二维码", "is_correct": true, "explanation": "正确：“扫一下”的对象是可扫描的图形码，与“用手机扫”一致。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是能用手机扫描读取信息的东西，句意说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是写字的墙面，不能用手机扫描。"}], "explanations": {"水杯": "搭配：“扫”的对象是码或图形，不能说扫水杯。", "二维码": "正确：“扫一下”的对象是可扫描的图形码，与“用手机扫”一致。", "书包": "语义：书包不是能用手机扫描读取信息的东西，句意说不通。", "黑板": "语义：黑板是写字的墙面，不能用手机扫描。"}, "sentence_index": 0, "correct_answer": "二维码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商品上的二维码是一排粗细不同的黑线，收银员用扫码枪读取价格。", "explanation": "这里应该用〈条形码〉。条形码是一排粗细不同的线条，二维码是黑白方块组成的图形。"}, {"text": "登录时我要输入二维码。", "explanation": "这里应该用〈验证码〉。二维码要用手机扫描，不能靠输入使用。"}, {"text": "想打开这个网页，直接在地址栏输入二维码就行。", "explanation": "这里应该用〈网址〉。网址是文字，可以直接输入地址栏；二维码是图形，要用手机扫描。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座位", "is_correct": false, "explanation": "语义：座位不是可以扫描读取的码，“扫不出来”不能用于座位。"}, {"text": "二维码", "is_correct": true, "explanation": "正确：“扫不出来”说的是可扫描的码，二维码坏了就无法扫描。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“坏了”说的是物件，不说价格坏了。"}, {"text": "印章", "is_correct": false, "explanation": "语义：印章是盖在纸上的印记，不能用扫描读取，“扫不出来”说不通。"}], "explanations": {"座位": "语义：座位不是可以扫描读取的码，“扫不出来”不能用于座位。", "二维码": "正确：“扫不出来”说的是可扫描的码，二维码坏了就无法扫描。", "价格": "搭配：“坏了”说的是物件，不说价格坏了。", "印章": "语义：印章是盖在纸上的印记，不能用扫描读取，“扫不出来”说不通。"}, "sentence_index": 6, "correct_answer": "二维码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请在表格里填写收件人的二维码。", "explanation": "这里应该用〈邮编〉。邮编是要填写的数字，二维码是图形，不能这样填写。"}, {"text": "开门时要按一下二维码，门才会打开。", "explanation": "这里应该用〈指纹〉。指纹要用手指按压，二维码要用手机扫描，不能按。"}, {"text": "合同的最后一页要签上你的二维码。", "explanation": "这里应该用〈签名〉。签名是写下自己的名字，二维码是图形，不能拿来签。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口有一只二维码。", "corrected_sentence": "门口有一个二维码。", "error_description": "量词错误：“二维码”常用量词“个”或“张”，不能用“只”（“只”多用于动物或成对物件中的一个）。正确说法是“门口有一个二维码”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个二维码我扫不来出。", "corrected_sentence": "这个二维码我扫不出来。", "error_description": "补语错误：“出来”是补语，须紧跟动词，可能补语应为“扫不出来”，“扫不来出”的语序不对。正确说法是“这个二维码我扫不出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
