INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先显示。", "primary_collocate": null, "pronunciation": "yù shì", "ipa": "y˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这些前沿探索预示着：清洁能源的终极形态，或是将整个建成环境转化为无感而持续的能量代谢网络。", "target_word": "预示", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份报告预示了公司未来的方向。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结果预示着新技术很有前途。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这些数字预示了经济会变好。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的第一部电影预示了他以后的成功。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩预示着他会进步。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个现象预示着气候正在变化。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的好奇心预示着他会爱上科学。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的开头预示了最后的结局。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这些变化预示着病情会好转。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "預示", "label": "繁体"}, {"form": "预示着", "label": "体标"}, {"form": "预示了", "label": "体标"}], "register": "书面", "sense_fingerprint": "预先显示未来的趋势或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确：“预示”指事先显示将来的趋势或结果，读作 yù shì。"}, {"text": "玉石", "is_correct": false, "explanation": "后字 shí（第二声）与 shì（第四声）声调不同，意思是玉石。"}, {"text": "鱼市", "is_correct": false, "explanation": "首字 yú（第二声）与 yù（第四声）声调不同，意思是鱼类市场。"}, {"text": "余事", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是其余的事。"}, {"text": "雨势", "is_correct": false, "explanation": "首字 yǔ（第三声）与 yù（第四声）声调不同，意思是雨的势头。"}], "explanations": {"预示": "正确：“预示”指事先显示将来的趋势或结果，读作 yù shì。", "玉石": "后字 shí（第二声）与 shì（第四声）声调不同，意思是玉石。", "鱼市": "首字 yú（第二声）与 yù（第四声）声调不同，意思是鱼类市场。", "余事": "yú（第二声）与 yù（第四声）声调不同，意思是其余的事。", "雨势": "首字 yǔ（第三声）与 yù（第四声）声调不同，意思是雨的势头。"}, "sentence_index": null, "correct_answer": "预示"}, "level_3": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确：“预示着”表示显露将来的迹象，与句中对“终极形态”的推测相符。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”指推迟，不能说“前沿探索拖延着”，句意不通。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”指表演音乐，与“前沿探索”和能源形态无关。"}, {"text": "玩耍", "is_correct": false, "explanation": "语域：“玩耍”是口语，不适合这句书面语的学术表述。"}], "explanations": {"预示": "正确：“预示着”表示显露将来的迹象，与句中对“终极形态”的推测相符。", "拖延": "语义：“拖延”指推迟，不能说“前沿探索拖延着”，句意不通。", "演奏": "语义：“演奏”指表演音乐，与“前沿探索”和能源形态无关。", "玩耍": "语域：“玩耍”是口语，不适合这句书面语的学术表述。"}, "sentence_index": 0, "correct_answer": "预示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都预示明天的功课。", "explanation": "这里应该用〈预习〉。“预示”指显露将来的迹象，学习前的准备要用“预习”。"}, {"text": "他预示同意这个计划。", "explanation": "这里应该用〈表示〉。“预示”的主语应是现象或迹象，人表达态度要用“表示”。"}, {"text": "我提前预示了医生。", "explanation": "这里应该用〈预约〉。“预示”不能表示预先约定，预约医生要用“预约”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确：“预示”指事先显示将来的趋势或结果，读作 yù shì。"}, {"text": "于是", "is_correct": false, "explanation": "首字 yú（第二声）与 yù（第四声）声调不同，“于是”是连词，表示承接。"}, {"text": "鱼食", "is_correct": false, "explanation": "yú shí（第二声、第二声）与 yù shì（第四声、第四声）声调不同，意思是喂鱼的饲料。"}, {"text": "御史", "is_correct": false, "explanation": "后字 shǐ（第三声）与 shì（第四声）声调不同，意思是古代的监察官员。"}], "explanations": {"预示": "正确：“预示”指事先显示将来的趋势或结果，读作 yù shì。", "于是": "首字 yú（第二声）与 yù（第四声）声调不同，“于是”是连词，表示承接。", "鱼食": "yú shí（第二声、第二声）与 yù shì（第四声、第四声）声调不同，意思是喂鱼的饲料。", "御史": "后字 shǐ（第三声）与 shì（第四声）声调不同，意思是古代的监察官员。"}, "sentence_index": null, "correct_answer": "预示"}, "level_3": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确：“这个现象预示着气候正在变化”，表示现象显露出未来的迹象。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”要求有情感的主语，“现象”不能喜欢气候。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”指取笑他人，与“现象”和“气候变化”不相关。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”要求有意识的人作主语，“现象”不能批评气候。"}], "explanations": {"预示": "正确：“这个现象预示着气候正在变化”，表示现象显露出未来的迹象。", "喜欢": "配价：“喜欢”要求有情感的主语，“现象”不能喜欢气候。", "嘲笑": "语义：“嘲笑”指取笑他人，与“现象”和“气候变化”不相关。", "批评": "配价：“批评”要求有意识的人作主语，“现象”不能批评气候。"}, "sentence_index": 6, "correct_answer": "预示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨预示了昨天的事故。", "explanation": "这里应该用〈说明〉。“预示”指事情发生前显露的迹象，已经发生的事故不能用“预示”，应说“说明”。"}, {"text": "他预示世界末日会来。", "explanation": "这里应该用〈预言〉。“预示”的主语应是现象或迹象，人对未来作出判断要说“预言”。"}, {"text": "我们预示了晚饭。", "explanation": "这里应该用〈预备〉。“预示”指显露迹象，不能表示人准备饭菜，要用“预备”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些迹象预示着过天气会变冷。", "corrected_sentence": "这些迹象预示着天气会变冷。", "error_description": "体标错误：“着”表示动态持续，后面不能再接“过”，应去掉“过”，说“预示着天气会变冷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的笑容预示着了好运。", "corrected_sentence": "他的笑容预示着好运。", "error_description": "体标错误：“着”与“了”不能同时用在“预示”之后，应去掉“了”，说“预示着好运”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动态", "is_correct": true, "explanation": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。"}, {"text": "颜色", "is_correct": false, "explanation": "“颜色”与“静态”的“不动”义没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是具体名词，与“静态”的“不动”义没有反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "“声音”与“静态”的“不动”义没有反义关系。"}], "correct_answer": "动态", "explanations": {"动态": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。", "颜色": "“颜色”与“静态”的“不动”义没有反义关系。", "桌子": "“桌子”是具体名词，与“静态”的“不动”义没有反义关系。", "声音": "“声音”与“静态”的“不动”义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动态", "is_correct": true, "explanation": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。"}, {"text": "植物", "is_correct": false, "explanation": "“植物”与“静态”的“不动”义没有反义关系。"}, {"text": "墨水", "is_correct": false, "explanation": "“墨水”与“静态”的“不动”义没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”与“静态”的“不动”义没有反义关系。"}], "correct_answer": "动态", "explanations": {"动态": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。", "植物": "“植物”与“静态”的“不动”义没有反义关系。", "墨水": "“墨水”与“静态”的“不动”义没有反义关系。", "窗户": "“窗户”与“静态”的“不动”义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "事物没有运动或变化的状态；不活动。", "primary_collocate": null, "pronunciation": "jìng tài", "ipa": "tɕiŋ˥˩ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这张照片是静态的，视频是动态的。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面一直处于静态。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体从静态变成动态，需要力。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的杯子是静态的，不会自己动。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢画静态的东西，比如花和水果。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动态和静态是两种不同的状态。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，球一直处于静态。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "静态的画面里，只有一只猫。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的一切都是静态的。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物会跑，石头是静态的。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "靜態", "label": "繁体"}, {"form": "静态图", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物不运动、不变化的状态，与动态相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文字", "is_correct": false, "explanation": "语义：这里说的是照片的状态，文字不是照片的状态。"}, {"text": "静态", "is_correct": true, "explanation": "正确：“静态”指没有运动的状态，与后半句的“动态”相对。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是……的”描述照片的状态，不说照片是颜色的。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：照片不会吵闹，句意说不通。"}], "explanations": {"文字": "语义：这里说的是照片的状态，文字不是照片的状态。", "静态": "正确：“静态”指没有运动的状态，与后半句的“动态”相对。", "颜色": "搭配：“是……的”描述照片的状态，不说照片是颜色的。", "吵闹": "语义：照片不会吵闹，句意说不通。"}, "sentence_index": 0, "correct_answer": "静态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气是静态的，一生气就大喊。", "explanation": "这里应该用〈暴躁〉。“静态”指事物不动、不变化的状态，不能形容人的脾气；一生气就大喊是脾气暴躁。"}, {"text": "孩子在操场上跑来跑去，身体一直处于静态。", "explanation": "这里应该用〈动态〉。跑来跑去是运动，要用“动态”；“静态”指没有运动、不动，与“跑来跑去”矛盾。"}, {"text": "这首歌的节奏是静态的，听起来很快。", "explanation": "这里应该用〈有动感〉。形容节奏要用“有动感”；“静态”指不变化、不动，与“听起来很快”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡眠", "is_correct": false, "explanation": "搭配：“处于”后面接的是状态，要说“处于睡眠状态”，不能直接说“处于睡眠”。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：球不会处于饥饿的状态。"}, {"text": "静态", "is_correct": true, "explanation": "正确：“处于静态”指球没有运动，与“比赛前”的语境一致。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：球不会处于噪音之中，句意说不通。"}], "explanations": {"睡眠": "搭配：“处于”后面接的是状态，要说“处于睡眠状态”，不能直接说“处于睡眠”。", "饥饿": "语义：球不会处于饥饿的状态。", "静态": "正确：“处于静态”指球没有运动，与“比赛前”的语境一致。", "噪音": "语义：球不会处于噪音之中，句意说不通。"}, "sentence_index": 6, "correct_answer": "静态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河是静态的，水流很急。", "explanation": "这里应该用〈流动〉。河水在流动，“静态”指不动，与“水流很急”矛盾。"}, {"text": "这辆车处于静态，开得很快。", "explanation": "这里应该用〈行驶〉。车在行驶，“静态”指不动，与“开得很快”矛盾。"}, {"text": "我们的计划是静态的，每天都在变。", "explanation": "这里应该用〈灵活〉。计划要随时调整，“静态”指不变化，与“每天都在变”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块石头是静态了。", "corrected_sentence": "这块石头是静态的。", "error_description": "了的错误：“是……的”判断句不用“了”。正确说法是“这块石头是静态的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "石头放在静态，没有动。", "corrected_sentence": "石头处于静态，没有动。", "error_description": "搭配错误：“静态”后面要用“处于”，不能说“放在静态”。正确说法是“石头处于静态，没有动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
