INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "接口是不同系统、设备或软件之间进行连接、通信或交互的端口、规范或方式。", "primary_collocate": null, "pronunciation": "jiē kǒu", "ipa": "tɕjɛ˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个软件的接口很容易用。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测试新的接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个系统用接口交换数据。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑要通过接口连接。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给开发者提供了一个接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接口出了问题，数据发不过去。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧系统的接口改好了。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的接口说明写得很清楚。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有接口，两个软件就不能交换数据。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序员每天都在写接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网络接口", "label": "复合"}], "register": "中性", "sense_fingerprint": "软件或系统之间用来连接和交换数据的规范或方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接口", "is_correct": true, "explanation": "“接口”指软件之间连接、交换数据的规范，“很容易用”说的正是接口好用。"}, {"text": "插座", "is_correct": false, "explanation": "语义：“插座”是电源的插口，与软件之间的连接规范无关。"}, {"text": "硬盘", "is_correct": false, "explanation": "语义：“硬盘”是存储设备，与软件的连接或使用无关。"}, {"text": "键盘", "is_correct": false, "explanation": "搭配：“软件”一般说界面、功能，不说“软件的键盘”。"}], "explanations": {"接口": "“接口”指软件之间连接、交换数据的规范，“很容易用”说的正是接口好用。", "插座": "语义：“插座”是电源的插口，与软件之间的连接规范无关。", "硬盘": "语义：“硬盘”是存储设备，与软件的连接或使用无关。", "键盘": "搭配：“软件”一般说界面、功能，不说“软件的键盘”。"}, "sentence_index": 0, "correct_answer": "接口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衬衫的接口很漂亮，大家都喜欢。", "explanation": "这里应该用〈领口〉。“接口”指系统、设备之间连接的端口或规范，不指衣服的部位。"}, {"text": "这家银行设了十个接口，方便大家办理业务。", "explanation": "这里应该用〈窗口〉。“接口”指系统、设备之间连接的端口或规范，不指银行办理业务的营业窗口。"}, {"text": "他按了一下接口，屏幕就亮了。", "explanation": "这里应该用〈按钮〉。按钮是可以按下去的部件，“接口”是系统或设备之间连接的端口或规范，不能按。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接口", "is_correct": true, "explanation": "“接口”是系统的连接规范，能被“改好”，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“旧系统”不与“厨房”搭配，厨房不是软件系统的部分。"}, {"text": "座椅", "is_correct": false, "explanation": "语义：“座椅”是家具，与软件系统无关，句意不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是房间的装饰品，与软件系统无关，句意不通。"}], "explanations": {"接口": "“接口”是系统的连接规范，能被“改好”，符合句意。", "厨房": "搭配：“旧系统”不与“厨房”搭配，厨房不是软件系统的部分。", "座椅": "语义：“座椅”是家具，与软件系统无关，句意不通。", "窗帘": "语义：“窗帘”是房间的装饰品，与软件系统无关，句意不通。"}, "sentence_index": 6, "correct_answer": "接口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的接口很多。", "explanation": "这里应该用〈人口〉。“接口”指系统或设备之间的连接，不指城市里居住的人数。"}, {"text": "这个接口有很多车。", "explanation": "这里应该用〈路口〉。“接口”指系统或设备之间连接的端口或规范，不指道路的交叉处。"}, {"text": "两个系统之间交换接口。", "explanation": "这里应该用〈数据〉。“接口”指连接的端口或规范，不是可以被交换的信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们给这个系统写了一根接口。", "corrected_sentence": "我们给这个系统写了一个接口。", "error_description": "“接口”的量词用“个”，“根”多用于线、棍等细长物，应说“一个接口”，不说“一根接口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们刚发布了一个很新接口。", "corrected_sentence": "我们刚发布了一个新接口。", "error_description": "“很”修饰形容词“新”，作定语时应说“很新的接口”；“很新接口”缺少“的”，不自然，应去掉“很”，说“一个新接口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
