INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "达到最高程度，表示非常、特别。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "然而，无论形式如何变迁，其核心精神始终未变：以极简之形，承载文明对自我延续的深刻追问。", "target_word": "极", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天的天气极好。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法极有用。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得极快，没有人追得上。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题极难，很多人都不会做。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的风景极美。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对学汉语的人极有帮助。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的身体极好，每天都去走路。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务极差，我不会再去了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事极不满意。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，放在形容词或动词前，表示非常、特别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极", "is_correct": true, "explanation": "正确：极（jí）表示达到最高程度，与听到的读音一致。"}, {"text": "积", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是打击。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}, {"text": "其", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是其他、它的。"}, {"text": "齐", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是整齐。"}], "explanations": {"极": "正确：极（jí）表示达到最高程度，与听到的读音一致。", "积": "jī（第一声）与 jí（第二声）声调不同，意思是积累。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是打击。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "己": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。", "其": "qí 与 jí 声母不同，意思是其他、它的。", "齐": "qí 与 jí 声母不同，意思是整齐。"}, "sentence_index": null, "correct_answer": "极"}, "level_3": {"options": [{"text": "不", "is_correct": false, "explanation": "语义：“不简”与“极简”所说的追求简约相反，此处不成立。"}, {"text": "极", "is_correct": true, "explanation": "正确：“极简之形”表示达到最简约的程度，“极”修饰形容词“简”。"}, {"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示“刚刚”，不能修饰形容词“简”作定语，“刚简之形”不通。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”表示并列或追加，不能直接修饰“简”，“也简之形”不通。"}], "explanations": {"不": "语义：“不简”与“极简”所说的追求简约相反，此处不成立。", "极": "正确：“极简之形”表示达到最简约的程度，“极”修饰形容词“简”。", "刚": "搭配：“刚”表示“刚刚”，不能修饰形容词“简”作定语，“刚简之形”不通。", "也": "搭配：“也”表示并列或追加，不能直接修饰“简”，“也简之形”不通。"}, "sentence_index": 0, "correct_answer": "极"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班跑得极快的是他，他拿了冠军。", "explanation": "这里应该用“最”。“极”表示程度，不用于在一个范围内居首的比较，这里要说“最快的”。"}, {"text": "这件衣服极贵了，我们还是别买了。", "explanation": "这里应该用“太”。“极”表示达到最高程度，不用于表示超出合适范围的抱怨，这里要用“太”。"}, {"text": "这次比赛中，他极快，是全场第一的那位选手。", "explanation": "这里应该用“最”。“极”表示程度，不用于在一群选手中居首的比较，这里要用“最快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极", "is_correct": true, "explanation": "正确：极（jí）表示达到最高程度，与听到的读音一致。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是计算。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。"}, {"text": "奇", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是奇怪。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}], "explanations": {"极": "正确：极（jí）表示达到最高程度，与听到的读音一致。", "机": "jī（第一声）与 jí（第二声）声调不同，意思是机器。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "计": "jì（第四声）与 jí（第二声）声调不同，意思是计算。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。", "奇": "qí 与 jí 声母不同，意思是奇怪。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, "sentence_index": null, "correct_answer": "极"}, "level_3": {"options": [{"text": "被", "is_correct": false, "explanation": "语法：“被”是表被动的介词，不能直接放在“有帮助”前，“被有帮助”不通。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“只有”或“刚刚”，与前文泛指的积极评价不符。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”后要接宾语和处置动作，不能修饰“有帮助”，“把有帮助”不通。"}, {"text": "极", "is_correct": true, "explanation": "正确：“极有帮助”表示帮助的程度达到最高，“极”修饰“有”。"}], "explanations": {"被": "语法：“被”是表被动的介词，不能直接放在“有帮助”前，“被有帮助”不通。", "才": "语义：“才”表示“只有”或“刚刚”，与前文泛指的积极评价不符。", "把": "语法：“把”后要接宾语和处置动作，不能修饰“有帮助”，“把有帮助”不通。", "极": "正确：“极有帮助”表示帮助的程度达到最高，“极”修饰“有”。"}, "sentence_index": 6, "correct_answer": "极"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件大衣极贵了，我们都买不起。", "explanation": "这里应该用“太”。“极”表示达到最高程度，不用于表示超出合适范围的抱怨，这里要用“太”。"}, {"text": "这座山在全省极高，是第一。", "explanation": "这里应该用〈最〉。“极”表示程度，不用于在一个范围内居首的比较，这里要说“最高”。"}, {"text": "他是我们班极聪明的那一个。", "explanation": "这里应该用“最”。“极”表示程度，不用于在一个班的人中居首的比较，这里要用“最聪明的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的夏天很极热。", "corrected_sentence": "这里的夏天极热。", "error_description": "“极”与“很”都是程度副词，不能同时修饰同一个形容词，应只用“极”，说“极热”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做饭做极好。", "corrected_sentence": "她做饭做得极好。", "error_description": "补语前要用“得”，应说“做得极好”；“做极好”少了“得”，不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "“中断”与“延续”在“持续不断”这一义上构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“延续”既非反义也非近义，不构成对应关系。"}, {"text": "打扫", "is_correct": false, "explanation": "“打扫”与“延续”没有反义或近义关系。"}, {"text": "询问", "is_correct": false, "explanation": "“询问”与“延续”没有反义或近义关系。"}], "correct_answer": "中断", "explanations": {"中断": "“中断”与“延续”在“持续不断”这一义上构成反义。", "散步": "“散步”与“延续”既非反义也非近义，不构成对应关系。", "打扫": "“打扫”与“延续”没有反义或近义关系。", "询问": "“询问”与“延续”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
