INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持续不断，一直保持下去。", "primary_collocate": null, "pronunciation": "yán xù", "ipa": "jɛn˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "然而，无论形式如何变迁，其核心精神始终未变：以极简之形，承载文明对自我延续的深刻追问。", "target_word": "延续", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个村子的老传统一直延续到今天。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷希望家里的好习惯能延续下去。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的友谊从小学一直延续着。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年吃饺子的习俗延续了几百年。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望大家把这个好习惯延续下去。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店延续着一百年前的做法。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用新办法延续这门老手艺。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日的传统在我们家延续了很多年。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的老文化至今还在延续。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延续着", "label": "体标（着）"}, {"form": "延续了", "label": "体标（了）"}, {"form": "延续过", "label": "体标（过）"}, {"form": "延续下去", "label": "复合（趋向补语）"}], "register": "中性", "sense_fingerprint": "延续：传统、习惯等事物持续不断，一直保持下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延续", "is_correct": true, "explanation": "“延续”指持续不断地保持下去，与“始终未变”“承载文明”的持续之义一致，只有它能填入此处。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清扫卫生，不能用于抽象的“自我”，句意不通。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”指算数，不能与“自我”构成“深刻追问”的对象，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是身体运动，与抽象的“自我延续”无关，句意不通。"}], "explanations": {"延续": "“延续”指持续不断地保持下去，与“始终未变”“承载文明”的持续之义一致，只有它能填入此处。", "打扫": "语义：“打扫”指清扫卫生，不能用于抽象的“自我”，句意不通。", "计算": "搭配：“计算”指算数，不能与“自我”构成“深刻追问”的对象，句意不通。", "游泳": "语义：“游泳”是身体运动，与抽象的“自我延续”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "延续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把我的裤子延续了两厘米。", "explanation": "这里应该用〈加长〉。“延续”指事情或传统不间断地保持下去，不用于衣物长度的加长。"}, {"text": "他把绳子延续了三米。", "explanation": "这里应该用〈延长〉。“延长”指把长度或时间拉长，“延续”指事物不断保持下去，不用于绳子的加长。"}, {"text": "他把旧手机的屏幕延续了三次。", "explanation": "这里应该用〈更换〉。“延续”指持续保持，不用于屏幕的更换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延续", "is_correct": true, "explanation": "“延续”指长久保持下去，与“一百年前的做法”相承接，符合句意。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指彻底否定，与老店沿用旧做法的意思相反。"}, {"text": "忘记", "is_correct": false, "explanation": "体貌：“忘记”是瞬间完成的动作，不能与表示持续的“着”搭配。"}, {"text": "淘汰", "is_correct": false, "explanation": "语义：“淘汰”指去掉不合适的事物，与“延续一百年前的做法”相反。"}], "explanations": {"延续": "“延续”指长久保持下去，与“一百年前的做法”相承接，符合句意。", "推翻": "语义：“推翻”指彻底否定，与老店沿用旧做法的意思相反。", "忘记": "体貌：“忘记”是瞬间完成的动作，不能与表示持续的“着”搭配。", "淘汰": "语义：“淘汰”指去掉不合适的事物，与“延续一百年前的做法”相反。"}, "sentence_index": 6, "correct_answer": "延续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的产量延续了三倍。", "explanation": "这里应该用〈增长〉。“延续”指事情持续进行或事物长久保持，不用于产量的成倍增加。"}, {"text": "今年报名的人数延续了一倍。", "explanation": "这里应该用〈增加〉。“延续”不表示数量的增加，人数增加要用“增加”。"}, {"text": "他的存款延续了一半。", "explanation": "这里应该用〈减少〉。“延续”不表示数量的减少，存款变少要用“减少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门手艺在他家里一直延续了着。", "corrected_sentence": "这门手艺在他家里一直延续着。", "error_description": "“延续”后不能同时用“了”和“着”两个体标，表示持续状态只用“着”，应说“一直延续着”；“延续了着”的体标重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个习俗一直延续过。", "corrected_sentence": "这个习俗一直延续着。", "error_description": "“过”表示曾经有过的经历，不能表示正在持续进行，此处应用“着”，说“一直延续着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
