INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指为了深入了解或得到更详细的回答而继续提问。", "primary_collocate": null, "pronunciation": "zhuī wèn", "ipa": "ʈʂweɪ˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "然而，无论形式如何变迁，其核心精神始终未变：以极简之形，承载文明对自我延续的深刻追问。", "target_word": "追问", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "记者继续追问这件事的原因。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师追问了我一句。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈追问我昨天去了哪里。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不停地追问，直到弄明白为止。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再追问他的过去了。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生追问老师为什么会这样。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察追问了三次，他才说实话。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别追问了，我真的不知道。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她追问着结果，眼睛一直看着我。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追问了", "label": "体标"}, {"form": "追问过", "label": "体标"}, {"form": "追问着", "label": "体标"}], "register": "中性", "sense_fingerprint": "为了弄清楚更多而接着提问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追赶", "is_correct": false, "explanation": "搭配：“追赶”指快跑赶上某个对象，不能修饰“深刻”这类抽象的追问。"}, {"text": "追悼", "is_correct": false, "explanation": "语义：“追悼”指悼念死者，与“自我延续”的语境不符。"}, {"text": "追问", "is_correct": true, "explanation": "正确：“深刻的追问”指对自我延续问题的反复深入提问。"}, {"text": "追捕", "is_correct": false, "explanation": "语义：“追捕”指追赶并抓捕人或逃犯，与抽象的“自我延续”无关，句意不通。"}], "explanations": {"追赶": "搭配：“追赶”指快跑赶上某个对象，不能修饰“深刻”这类抽象的追问。", "追悼": "语义：“追悼”指悼念死者，与“自我延续”的语境不符。", "追问": "正确：“深刻的追问”指对自我延续问题的反复深入提问。", "追捕": "语义：“追捕”指追赶并抓捕人或逃犯，与抽象的“自我延续”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "追问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直在追问末班车。", "explanation": "这里应该用“追赶”。“追问”的对象是人或问题，不能用于“末班车”这类物体。"}, {"text": "他一直追问那只受伤的小鸟。", "explanation": "这里应该用〈照顾〉。“追问”的对象是人或问题，不能用于受伤的小鸟。"}, {"text": "人们追问那辆逃走的汽车。", "explanation": "这里应该用〈追赶〉。“追问”的对象是人或问题，不能用于汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追悔", "is_correct": false, "explanation": "语义：“追悔”指事后后悔，与“学生问老师为什么会这样”的提问不符。"}, {"text": "追捧", "is_correct": false, "explanation": "搭配：“追捧”指热烈推崇人或事物，不能接“为什么会这样”这类疑问内容。"}, {"text": "追问", "is_correct": true, "explanation": "正确：“学生追问老师为什么会这样”指学生接连提问，想弄清原因。"}, {"text": "追随", "is_correct": false, "explanation": "配价：“追随”的宾语是人或思想，不能接“为什么会这样”这类疑问小句。"}], "explanations": {"追悔": "语义：“追悔”指事后后悔，与“学生问老师为什么会这样”的提问不符。", "追捧": "搭配：“追捧”指热烈推崇人或事物，不能接“为什么会这样”这类疑问内容。", "追问": "正确：“学生追问老师为什么会这样”指学生接连提问，想弄清原因。", "追随": "配价：“追随”的宾语是人或思想，不能接“为什么会这样”这类疑问小句。"}, "sentence_index": 6, "correct_answer": "追问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常常追问童年的玩具。", "explanation": "这里应该用〈怀念〉。“追问”是提问，不能用于怀念旧物。"}, {"text": "猎人在山里追问野兔。", "explanation": "这里应该用“追踪”。“追问”的对象是人或问题，不能用于动物。"}, {"text": "他终于追问了前面的队伍。", "explanation": "这里应该用“追上”。“追问”表示提问，不表示赶上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他追问我了三次。", "corrected_sentence": "他追问了我三次。", "error_description": "“了”应紧跟动词，说“追问了我三次”；“追问我了”把“了”放在宾语后，不符合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她追问了着我的去向，语气很急。", "corrected_sentence": "她追问着我的去向，语气很急。", "error_description": "“了”和“着”不能同时用在同一个动词上；“追问了着”重复了体标，应只用“着”，即“追问着我的去向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
