INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指心里产生了购买的愿望。", "primary_collocate": null, "pronunciation": "xiǎng mǎi", "ipa": "ɕjɑŋ˨˩˦ maɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "想买的人多，房子就更贵。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我想买一个新手机。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买什么东西？", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想买那条红裙子。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就想买这本书了。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买房子，可是钱不够。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想买一辆自行车。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想买些水果回家。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太贵，我不想买了。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买哪一种茶？", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想买了", "label": "体标"}, {"form": "想买过", "label": "体标"}, {"form": "不想买", "label": "否定"}], "register": "中性", "sense_fingerprint": "心里产生购买的愿望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想买", "is_correct": true, "explanation": "正确。“想买”的人多，购买需求大，所以房子更贵。"}, {"text": "想卖", "is_correct": false, "explanation": "语义：想卖的人多意味着供应增加，房价会下降，与“房子就更贵”的因果相反。"}, {"text": "想吃", "is_correct": false, "explanation": "搭配：“想吃”的人多与房子的价格没有关系，“吃”的对象也不是房子。"}, {"text": "想拆", "is_correct": false, "explanation": "语义：想拆房子的人多与房价更贵没有合理的因果关系。"}], "explanations": {"想买": "正确。“想买”的人多，购买需求大，所以房子更贵。", "想卖": "语义：想卖的人多意味着供应增加，房价会下降，与“房子就更贵”的因果相反。", "想吃": "搭配：“想吃”的人多与房子的价格没有关系，“吃”的对象也不是房子。", "想拆": "语义：想拆房子的人多与房价更贵没有合理的因果关系。"}, "sentence_index": 0, "correct_answer": "想买"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想买一场雨。", "explanation": "这里不能说“买”。“买”的对象应是可以交易的商品，雨是天气现象，不能被买。"}, {"text": "他想买一片大海。", "explanation": "“买”的对象应是可以交易的商品，大海是自然景物，不能被买。"}, {"text": "她想买那个星期天。", "explanation": "“买”的对象不能是时间。“星期天”不是商品，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想买", "is_correct": true, "explanation": "正确。“弟弟想买一辆自行车”，表示心里产生了购买的愿望。"}, {"text": "想喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能说“喝一辆自行车”。"}, {"text": "想听", "is_correct": false, "explanation": "语义：自行车没有声音可以“听”，与句中购买的语境不符。"}, {"text": "想尝", "is_correct": false, "explanation": "搭配：“尝”的对象是食物，不能说“尝一辆自行车”。"}], "explanations": {"想买": "正确。“弟弟想买一辆自行车”，表示心里产生了购买的愿望。", "想喝": "搭配：“喝”的对象是饮料，不能说“喝一辆自行车”。", "想听": "语义：自行车没有声音可以“听”，与句中购买的语境不符。", "想尝": "搭配：“尝”的对象是食物，不能说“尝一辆自行车”。"}, "sentence_index": 6, "correct_answer": "想买"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想买一句道歉。", "explanation": "“道歉”是言语行为，不是可以交易的商品，不能用“买”。"}, {"text": "我想买昨天。", "explanation": "“买”的对象应是可以交易的商品，“昨天”是时间，不能被买。"}, {"text": "我想买一个笑话。", "explanation": "这里应该用〈讲〉。“买”不用于笑话，讲笑话才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈早就想买着那台冰箱。", "corrected_sentence": "妈妈早就想买那台冰箱。", "error_description": "体标错误：“着”表示动作正在持续，“想买”是心理活动，不能与“着”连用；应去掉“着”，说“早就想买那台冰箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很想买了那辆车，可是没钱。", "corrected_sentence": "他很想买那辆车，可是没钱。", "error_description": "体标错误：“想买”表示心里的愿望，购买并没有发生，不能在后面加表示动作完成的“了”。“可是没钱”也说明车没有买成。应去掉“了”，说“很想买那辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赔", "is_correct": true, "explanation": "正确：赔与赚构成反义，指损失钱，与“赚钱”相对。"}, {"text": "写", "is_correct": false, "explanation": "写是书写，与赚没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是歌唱，与赚没有反义关系。"}, {"text": "修", "is_correct": false, "explanation": "修是修理，与赚没有反义关系。"}], "correct_answer": "赔", "explanations": {"赔": "正确：赔与赚构成反义，指损失钱，与“赚钱”相对。", "写": "写是书写，与赚没有反义关系。", "唱": "唱是歌唱，与赚没有反义关系。", "修": "修是修理，与赚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赔", "is_correct": true, "explanation": "正确：赔与赚构成反义，指损失钱，与“赚钱”相对。"}, {"text": "煮", "is_correct": false, "explanation": "煮是烹调，与赚没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑是奔跑，与赚没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画是绘画，与赚没有反义关系。"}], "correct_answer": "赔", "explanations": {"赔": "正确：赔与赚构成反义，指损失钱，与“赚钱”相对。", "煮": "煮是烹调，与赚没有反义关系。", "跑": "跑是奔跑，与赚没有反义关系。", "画": "画是绘画，与赚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过劳动或交易得到钱。", "primary_collocate": null, "pronunciation": "zhuàn", "ipa": "ʈʂwan˥˩", "syllable_count": 1, "sentences": [{"text": "贵的房子，老板可以赚更多的钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他在公司一个月赚一万块钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店今天赚了不少钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想多赚一点钱给家里。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做生意赚过很多钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板卖水果赚了两千块。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月你赚了多少钱？", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们卖衣服，一件能赚十块。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想只赚钱，也想学东西。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会赚钱，也很会花钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赚了", "label": "体标"}, {"form": "赚过", "label": "体标"}, {"form": "赚钱", "label": "复合"}, {"form": "賺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通过劳动或交易得到钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚（zhuàn，第四声），意思是通过劳动或交易得到钱。"}, {"text": "专", "is_correct": false, "explanation": "专（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是专门、专业。"}, {"text": "砖", "is_correct": false, "explanation": "砖（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是砖头。"}, {"text": "撞", "is_correct": false, "explanation": "撞（zhuàng）与赚（zhuàn）韵尾不同，撞是碰撞，不是得到钱。"}, {"text": "壮", "is_correct": false, "explanation": "壮（zhuàng）与赚（zhuàn）韵尾不同，意思是强壮。"}], "explanations": {"赚": "正确：赚（zhuàn，第四声），意思是通过劳动或交易得到钱。", "专": "专（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是专门、专业。", "砖": "砖（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是砖头。", "撞": "撞（zhuàng）与赚（zhuàn）韵尾不同，撞是碰撞，不是得到钱。", "壮": "壮（zhuàng）与赚（zhuàn）韵尾不同，意思是强壮。"}, "sentence_index": null, "correct_answer": "赚"}, "level_3": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚，表示通过交易得到钱，与“老板可以”和“更多的钱”搭配，句子通顺。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”是用脚压，“踩钱”不成立，句子不通。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”只能接气味，不能接“钱”作宾语。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”表示失去钱，与“贵的房子”带来的收益相反。"}], "explanations": {"赚": "正确：赚，表示通过交易得到钱，与“老板可以”和“更多的钱”搭配，句子通顺。", "踩": "搭配：“踩”是用脚压，“踩钱”不成立，句子不通。", "闻": "搭配：“闻”只能接气味，不能接“钱”作宾语。", "丢": "语义：“丢”表示失去钱，与“贵的房子”带来的收益相反。"}, "sentence_index": 0, "correct_answer": "赚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛里赚到了冠军。", "explanation": "这里应该用〈赢〉。赚的对象是钱或利益，比赛名次要说赢。"}, {"text": "我们努力工作，终于赚到了成功。", "explanation": "这里应该用〈获得〉。赚只接钱或利益，成功这类抽象结果要说获得。"}, {"text": "他这次考试赚了九十分。", "explanation": "这里应该用〈得〉。赚的对象是钱或利益，考试分数要说得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚（zhuàn），意思是通过劳动或交易得到钱。"}, {"text": "串", "is_correct": false, "explanation": "串（chuàn）与赚（zhuàn）声母不同（ch 与 zh），意思是串起来。"}, {"text": "钻", "is_correct": false, "explanation": "钻（zuàn）与赚（zhuàn）声母不同（z 与 zh），意思是钻石或钻研。"}, {"text": "涮", "is_correct": false, "explanation": "涮（shuàn）与赚（zhuàn）声母不同（sh 与 zh），意思是在汤里来回烫。"}, {"text": "窜", "is_correct": false, "explanation": "窜（cuàn）与赚（zhuàn）声母不同（c 与 zh），意思是乱跑。"}], "explanations": {"赚": "正确：赚（zhuàn），意思是通过劳动或交易得到钱。", "串": "串（chuàn）与赚（zhuàn）声母不同（ch 与 zh），意思是串起来。", "钻": "钻（zuàn）与赚（zhuàn）声母不同（z 与 zh），意思是钻石或钻研。", "涮": "涮（shuàn）与赚（zhuàn）声母不同（sh 与 zh），意思是在汤里来回烫。", "窜": "窜（cuàn）与赚（zhuàn）声母不同（c 与 zh），意思是乱跑。"}, "sentence_index": null, "correct_answer": "赚"}, "level_3": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚，表示通过劳动得到钱，与“这个月你”和“多少钱”搭配，句子通顺。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，钱不能喝，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以“钱”作宾语，“唱了多少钱”不成立。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚触碰，与钱无关，句子不通。"}], "explanations": {"赚": "正确：赚，表示通过劳动得到钱，与“这个月你”和“多少钱”搭配，句子通顺。", "喝": "语义：“喝”指饮用，钱不能喝，句子不通。", "唱": "搭配：“唱”不能以“钱”作宾语，“唱了多少钱”不成立。", "踢": "语义：“踢”是用脚触碰，与钱无关，句子不通。"}, "sentence_index": 6, "correct_answer": "赚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是主动赚责任。", "explanation": "这里应该用〈承担〉。赚的对象是钱或利益，责任要说承担。"}, {"text": "他赚到了一场大雨。", "explanation": "这里应该用〈下〉。赚的对象是钱或利益，大雨要说下。"}, {"text": "他按时赚了作业。", "explanation": "这里应该用〈交〉。赚的对象是钱或利益，作业要说交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年在国外了赚两万块钱。", "corrected_sentence": "他去年在国外赚了两万块钱。", "error_description": "错误：“了”放在动词“赚”前面。正确：“赚了”，表示完成的“了”要放在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下班后再兼职，又赚了到一笔钱。", "corrected_sentence": "他下班后再兼职，又赚到了一笔钱。", "error_description": "补语位置错误：“到”是“赚”的结果补语，应为“赚到了”，不能说“赚了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
