INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种植蔬菜的土地，通常指菜园或菜田。", "primary_collocate": null, "pronunciation": "cài dì", "ipa": "tsʰaɪ̯˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "城市规划要让房子、花园和菜地在一起。", "target_word": "菜地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷在家后面有一块菜地。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜地里长着青菜和白菜。", "target_word": "菜地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，妈妈都去菜地浇水。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，菜地里的土很湿。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把花园的一半改成了菜地。", "target_word": "菜地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的菜地不大，但是种了很多菜。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜地旁边有一条小河，水很干净。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块菜地需要多浇水，菜才长得好。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我跟爸爸去菜地拔草。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块菜地", "label": "量词（块）"}, {"form": "一片菜地", "label": "量词（片）"}], "register": "中性", "sense_fingerprint": "种蔬菜的一块土地（菜园、菜田）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜地", "is_correct": true, "explanation": "正确答案：菜地，与“房子、花园”并列，都是城市规划中的用地。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是用地，不能与房子、花园一起纳入城市规划。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房屋内部的房间，不是可单独规划的用地，不能与房子、花园并列。"}, {"text": "矿山", "is_correct": false, "explanation": "搭配：“矿山”指开采矿产的场所，与“房子、花园”并列不成类，句子说不通。"}], "explanations": {"菜地": "正确答案：菜地，与“房子、花园”并列，都是城市规划中的用地。", "电脑": "语义：电脑不是用地，不能与房子、花园一起纳入城市规划。", "厨房": "语义：厨房是房屋内部的房间，不是可单独规划的用地，不能与房子、花园并列。", "矿山": "搭配：“矿山”指开采矿产的场所，与“房子、花园”并列不成类，句子说不通。"}, "sentence_index": 0, "correct_answer": "菜地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了两斤菜地。", "explanation": "这里应该用〈蔬菜〉。菜地是种菜的土地，不能按斤称重买卖，买的是蔬菜。"}, {"text": "我们晚饭炒了一盘菜地。", "explanation": "这里应该用〈萝卜〉。菜地是土地，不能炒着吃，炒的是萝卜。"}, {"text": "我家门口有一棵菜地。", "explanation": "这里应该用〈块〉。〈棵〉用于树和整株植物，菜地是一块土地，应说“一块菜地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜地", "is_correct": true, "explanation": "正确答案：菜地，是种菜的地方，与“种了很多菜”相符。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房是读书的房间，不用来种很多菜，句意冲突。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是睡觉的房间，不能用来种很多菜。"}, {"text": "衣柜", "is_correct": false, "explanation": "搭配：“种”的对象应是植物，“衣柜”不能与“种了很多菜”搭配。"}], "explanations": {"菜地": "正确答案：菜地，是种菜的地方，与“种了很多菜”相符。", "书房": "语义：书房是读书的房间，不用来种很多菜，句意冲突。", "卧室": "语义：卧室是睡觉的房间，不能用来种很多菜。", "衣柜": "搭配：“种”的对象应是植物，“衣柜”不能与“种了很多菜”搭配。"}, "sentence_index": 6, "correct_answer": "菜地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天早上去菜地看电视。", "explanation": "这里应该用〈客厅〉。菜地是种菜的土地，不能用来看电视，应说去客厅。"}, {"text": "这块菜地很辣，大家都不敢吃。", "explanation": "这里应该用〈辣椒〉。菜地是土地，不能用“辣”来形容，辣的是辣椒。"}, {"text": "爷爷按照菜地做了一道汤。", "explanation": "这里应该用〈菜谱〉。菜地是种菜的地，做汤要按菜谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一只菜地，就在房子后面。", "corrected_sentence": "我家有一块菜地，就在房子后面。", "error_description": "量词用错：“菜地”应说“一块菜地”，不能说“一只菜地”。“只”多用于动物和某些小件物品，不用于土地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一座菜地翻了一遍。", "corrected_sentence": "妈妈把一块菜地翻了一遍。", "error_description": "量词用错：“菜地”应用“块”，不能用“座”。“座”多用于山、房屋等大型固定物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
