INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "觉得；对事物产生某种感受或看法。", "primary_collocate": null, "pronunciation": "gǎn jué", "ipa": "kan˨˩˦ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "住在附近的人感觉更舒服。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我感觉他今天不太高兴。", "target_word": "感觉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我感觉这个办法不错。", "target_word": "感觉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你感觉这家饭馆怎么样？", "target_word": "感觉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他感觉老师今天说得很对。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚到这里，我感觉一切都很新鲜。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人感觉在这个城市生活压力很大。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我感觉他好像有什么话要对我说。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟感觉这次考试比上次难了。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一次见面，我感觉她很会照顾人。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "感觉到", "label": "结果补语形式"}], "register": "中性", "sense_fingerprint": "对事物的直接感受、印象或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感觉", "is_correct": true, "explanation": "正确。这里指住在附近的人对环境产生的直接感受。"}, {"text": "判断", "is_correct": false, "explanation": "配价：“判断”需要带宾语，不能直接接“更舒服”这样的形容词短语。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“更舒服”的感受正好相反。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能与“更舒服”搭配。"}], "explanations": {"感觉": "正确。这里指住在附近的人对环境产生的直接感受。", "判断": "配价：“判断”需要带宾语，不能直接接“更舒服”这样的形容词短语。", "讨厌": "语义：“讨厌”表示厌恶，与“更舒服”的感受正好相反。", "批评": "搭配：“批评”的对象是人或行为，不能与“更舒服”搭配。"}, "sentence_index": 0, "correct_answer": "感觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感觉了这道题的答案。", "explanation": "这里应该用〈想出〉。感觉指感受或想法，不能带“答案”这样的宾语。"}, {"text": "他感觉了一个苹果。", "explanation": "这里应该用〈吃〉。感觉不表示吃进或接触实物。"}, {"text": "我感觉了一条新闻。", "explanation": "这里应该用〈听说〉。感觉表示自己的感受，不能指获取新闻这类信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感觉", "is_correct": true, "explanation": "正确。这里指很多人对城市生活压力的主观感受。"}, {"text": "关上", "is_correct": false, "explanation": "语义：“关上”要接门、窗等物体，不能引出这样的句子。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是物品，不能引出这样的句子，句意不通。"}, {"text": "打开", "is_correct": false, "explanation": "语义：“打开”需要接具体的物体，不能引出这样的句子，句意不通。"}], "explanations": {"感觉": "正确。这里指很多人对城市生活压力的主观感受。", "关上": "语义：“关上”要接门、窗等物体，不能引出这样的句子。", "修理": "语义：“修理”的对象是物品，不能引出这样的句子，句意不通。", "打开": "语义：“打开”需要接具体的物体，不能引出这样的句子，句意不通。"}, "sentence_index": 6, "correct_answer": "感觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感觉了一封信。", "explanation": "这里应该用〈写〉。感觉表示感受或想法，不能表示写出信件。"}, {"text": "我感觉了一场电影。", "explanation": "这里应该用〈看〉。感觉不表示观看电影这类行为。"}, {"text": "妈妈感觉了一首歌。", "explanation": "这里应该用〈唱〉。感觉不表示唱出歌曲这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我感觉了这个菜有点咸。", "corrected_sentence": "我感觉这个菜有点咸。", "error_description": "“感觉”后面接一个句子表示看法时，不加“了”。正确的说法是“我感觉这个菜有点咸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他感觉得很累，不想说话。", "corrected_sentence": "他感觉很累，不想说话。", "error_description": "“感觉”后面不能加补语“得”。正确的说法是“感觉很累”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”指洁净，与身心感受无关。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线或颜色，与“舒服”不构成相对关系。"}, {"text": "迅速", "is_correct": false, "explanation": "无反义关系：“迅速”形容速度，与身心感受无关。"}], "correct_answer": "难受", "explanations": {"难受": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。", "干净": "无反义关系：“干净”指洁净，与身心感受无关。", "明亮": "无反义关系：“明亮”形容光线或颜色，与“舒服”不构成相对关系。", "迅速": "无反义关系：“迅速”形容速度，与身心感受无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。"}, {"text": "灵活", "is_correct": false, "explanation": "无反义关系：“灵活”形容动作或思路敏捷，与身心感受无关。"}, {"text": "简单", "is_correct": false, "explanation": "无反义关系：“简单”形容事情或结构不复杂，与“舒服”不构成相对关系。"}, {"text": "圆满", "is_correct": false, "explanation": "无反义关系：“圆满”形容事情完美结束，与身心感受无关。"}], "correct_answer": "难受", "explanations": {"难受": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。", "灵活": "无反义关系：“灵活”形容动作或思路敏捷，与身心感受无关。", "简单": "无反义关系：“简单”形容事情或结构不复杂，与“舒服”不构成相对关系。", "圆满": "无反义关系：“圆满”形容事情完美结束，与身心感受无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体或精神上感到轻松愉快，没有不适。", "primary_collocate": null, "pronunciation": "shū fu", "ipa": "ʂu˥˥ fu", "syllable_count": 2, "sentences": [{"text": "躺在床上听音乐，我感觉很舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饱饭以后，我觉得很舒服。", "target_word": "舒服", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张沙发又大又软，坐着很舒服。", "target_word": "舒服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天有点头疼，不太舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完热水澡，全身都很舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家酒店的床很大，睡起来特别舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天开着空调，房间里很舒服。", "target_word": "舒服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋穿起来很舒服，走路也不累。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末在家看书喝茶，我觉得很舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐了一整天车，腰不太舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "舒舒服服", "label": "重叠（AABB）"}, {"form": "不舒服", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "身体或精神轻松愉快、没有不适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舒服", "is_correct": true, "explanation": "正确：躺在床上听音乐，身心轻松愉快，用“感觉很舒服”符合语境。"}, {"text": "剧烈", "is_correct": false, "explanation": "搭配：“剧烈”多修饰运动、疼痛，不能说“感觉更剧烈”。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”指刀刃等尖锐，不能用来形容人的感觉。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”形容态度或行为生硬蛮横，不能用来说躺着听音乐时的感受。"}], "explanations": {"舒服": "正确：躺在床上听音乐，身心轻松愉快，用“感觉很舒服”符合语境。", "剧烈": "搭配：“剧烈”多修饰运动、疼痛，不能说“感觉更剧烈”。", "锋利": "语义：“锋利”指刀刃等尖锐，不能用来形容人的感觉。", "粗暴": "语义：“粗暴”形容态度或行为生硬蛮横，不能用来说躺着听音乐时的感受。"}, "sentence_index": 0, "correct_answer": "舒服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的价格很舒服，比我们想象的便宜。", "explanation": "这里应该用〈合理〉。“舒服”描述人的身心感受，不能用来形容价格高低。"}, {"text": "这个电影的故事很舒服，我看哭了。", "explanation": "这里应该用〈感人〉。“舒服”指身心没有不适，不能用来形容让人感动的故事。"}, {"text": "这次考试很舒服，题目都不难。", "explanation": "这里应该用〈轻松〉。“舒服”形容人的身心感受，不能用来形容考试的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舒服", "is_correct": true, "explanation": "正确：夏天开着空调，房间里让人感觉舒适，符合语境。"}, {"text": "凄凉", "is_correct": false, "explanation": "语义：“凄凉”形容冷清悲伤的景象，与“开着空调”的舒适情境相矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多修饰负担、心情，不能用来形容房间。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：“暴躁”形容人的脾气，不能用来形容房间。"}], "explanations": {"舒服": "正确：夏天开着空调，房间里让人感觉舒适，符合语境。", "凄凉": "语义：“凄凉”形容冷清悲伤的景象，与“开着空调”的舒适情境相矛盾。", "沉重": "搭配：“沉重”多修饰负担、心情，不能用来形容房间。", "暴躁": "语义：“暴躁”形容人的脾气，不能用来形容房间。"}, "sentence_index": 6, "correct_answer": "舒服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的会议很舒服，大家都提出了不少好建议。", "explanation": "这里应该用〈顺利〉。“舒服”形容人的身心感受，不能用来说会议进展得好不好。"}, {"text": "这次事故的伤势很舒服，医生说需要住院观察。", "explanation": "这里应该用〈严重〉。“舒服”表示身体没有不适，不能用来描述伤势的轻重。"}, {"text": "这个宾馆的位置很舒服，去地铁站只要五分钟。", "explanation": "这里应该用〈方便〉。“舒服”指人的感受，不能用来形容位置是否便利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨晚睡的很舒服。", "corrected_sentence": "他昨晚睡得很舒服。", "error_description": "“睡得很舒服”中的“得”是引出补语的结构助词，这里误用“的”。正确说法是“睡得很舒服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "午睡醒来，我觉得很舒舒服服。", "corrected_sentence": "午睡醒来，我觉得很舒服。", "error_description": "“舒舒服服”是“舒服”的重叠形式，不能直接受程度副词“很”修饰。正确的说法是“很舒服”，或者用“舒舒服服”而不加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
