INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指多层或高层的建筑物，通常用于居住或办公。", "primary_collocate": null, "pronunciation": "dà lóu", "ipa": "ta˥˩ lou̯˧˥", "syllable_count": 2, "sentences": [{"text": "城市规划者发现，有绿色植物的大楼更受人们欢迎。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "那座大楼有三十层，很高。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在这栋大楼里工作。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼前面有一个很大的停车场。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼是去年盖好的。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司搬进了新大楼。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去那座大楼怎么走？", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上大楼的灯都亮着。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼旁边有一家小咖啡店。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼太高了，我们坐电梯上去。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座大楼", "label": "量词"}, {"form": "一栋大楼", "label": "量词"}, {"form": "大樓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多层或高层的居住或办公建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大楼", "is_correct": true, "explanation": "大楼可以“有绿色植物”，并且“更受人们欢迎”，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不能“有绿色植物”，与“更受人们欢迎”也不搭。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以被“有绿色植物”修饰的建筑，句子不成立。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“有……的”后面不能接“数字”来描述受欢迎的对象。"}], "explanations": {"大楼": "大楼可以“有绿色植物”，并且“更受人们欢迎”，符合句意。", "考试": "语义：考试不能“有绿色植物”，与“更受人们欢迎”也不搭。", "雨": "语义：雨不是可以被“有绿色植物”修饰的建筑，句子不成立。", "数字": "搭配：“有……的”后面不能接“数字”来描述受欢迎的对象。"}, "sentence_index": 0, "correct_answer": "大楼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家对面有一条大楼。", "explanation": "这里应该用〈栋〉。“条”用于细长的东西，如路、河，大楼应用“栋”或“座”。"}, {"text": "他在一只大楼里工作。", "explanation": "这里应该用〈栋〉。“只”用于动物或成对物品中的一个，不用于大楼。"}, {"text": "公园旁边有一颗大楼。", "explanation": "这里应该用〈栋〉。“颗”用于圆形或粒状的小东西，不用于大楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大楼", "is_correct": true, "explanation": "“那座”可以修饰大楼，“去那座大楼怎么走”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“那座”用于大型建筑，不说“那座天气”。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“那座”不能修饰“问题”，“问题怎么走”也不成立。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不是可以去往的地点，“怎么走”不能用于歌。"}], "explanations": {"大楼": "“那座”可以修饰大楼，“去那座大楼怎么走”符合语境。", "天气": "搭配：“那座”用于大型建筑，不说“那座天气”。", "问题": "搭配：“那座”不能修饰“问题”，“问题怎么走”也不成立。", "歌": "语义：歌不是可以去往的地点，“怎么走”不能用于歌。"}, "sentence_index": 6, "correct_answer": "大楼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根大楼太高了，我们坐电梯上去。", "explanation": "这里应该用〈栋〉。“根”用于细长的东西，如绳子、棍子，不用于大楼。"}, {"text": "那块大楼很有名，大家都知道。", "explanation": "这里应该用〈座〉。“块”用于片状或块状的东西，不用于大型建筑。"}, {"text": "我们在那张大楼里开会。", "explanation": "这里应该用〈栋〉。“张”用于桌子、纸等平面的东西，不用于大楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的公司在一张大楼里。", "corrected_sentence": "妈妈的公司在一栋大楼里。", "error_description": "大楼是建筑，量词应用“栋”或“座”；“张”用于桌子、纸等平面的东西，不用于大楼，应说“一栋大楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座大楼有三十个层。", "corrected_sentence": "那座大楼有三十层。", "error_description": "“层”本身就是量词，前面不能再加“个”，应说“三十层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
