INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12611, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过支付货币或其他形式的交换，获得某件物品的所有权或使用权。", "primary_collocate": null, "pronunciation": "mǎi dào", "ipa": "mai̯˨˩˦ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "我在网上买到了便宜的机票。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我找了很久才买到。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午的电影票你买到了吗？", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买红色的包，可是没买到。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果在小城市不容易买到。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在哪儿买到这么好吃的蛋糕？", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我终于买到了新手机。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的火车票很难买到。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在市场买到了新鲜的鱼。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他排了两个小时队，买到了演唱会的票。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买到了", "label": "体标（完成）"}, {"form": "买到过", "label": "体标（经历）"}, {"form": "买得到", "label": "可能补语（肯定）"}, {"form": "买不到", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "买东西并成功得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买到", "is_correct": true, "explanation": "正确。“我在网上……了便宜的机票”，表示付钱得到。"}, {"text": "修好", "is_correct": false, "explanation": "搭配：“修好”的对象是能修的东西，机票不能修。"}, {"text": "喝掉", "is_correct": false, "explanation": "搭配：“喝掉”的对象是饮品，机票不能喝。"}, {"text": "说出", "is_correct": false, "explanation": "语义：“说出”的对象是话语，机票不能被说出来。"}], "explanations": {"买到": "正确。“我在网上……了便宜的机票”，表示付钱得到。", "修好": "搭配：“修好”的对象是能修的东西，机票不能修。", "喝掉": "搭配：“喝掉”的对象是饮品，机票不能喝。", "说出": "语义：“说出”的对象是话语，机票不能被说出来。"}, "sentence_index": 0, "correct_answer": "买到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买到了丢失的钱包。", "explanation": "这里应该用〈找到〉。买到指付钱得到东西，丢失的东西要找回来，不能买。"}, {"text": "我买到了妈妈寄来的信。", "explanation": "这里应该用〈收到〉。买到指付钱得到，寄来的信是收到的，不能买。"}, {"text": "我家的猫买到了一只鸟。", "explanation": "这里应该用〈抓到〉。买到指付钱得到东西，猫捉住的鸟不是买来的，要说抓到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "买到", "is_correct": true, "explanation": "正确。“我终于……了新手机”，表示花钱得到。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，手机不能吃。"}, {"text": "喂饱", "is_correct": false, "explanation": "配价：“喂饱”要求有生命的受事，手机不能被喂饱。"}, {"text": "唱完", "is_correct": false, "explanation": "搭配：“唱完”的对象是歌曲等，手机不能唱。"}], "explanations": {"买到": "正确。“我终于……了新手机”，表示花钱得到。", "吃掉": "搭配：“吃掉”的对象是食物，手机不能吃。", "喂饱": "配价：“喂饱”要求有生命的受事，手机不能被喂饱。", "唱完": "搭配：“唱完”的对象是歌曲等，手机不能唱。"}, "sentence_index": 6, "correct_answer": "买到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我花钱买到了妈妈的爱。", "explanation": "这里应该用〈感受到〉。买到指用钱换得可买卖的东西，妈妈的爱要靠相处感受到，不能用钱买到。"}, {"text": "我花钱买到了过去的一天。", "explanation": "这里应该用〈回到〉。买到指用钱换得可买卖的东西，过去的一天不能用钱买，只能回到。"}, {"text": "我花钱买到了一阵鸟叫。", "explanation": "这里应该用〈听到〉。买到指用钱换得可买卖的东西，鸟叫要用耳朵听到，不能用钱买到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天已经在超市买到一瓶牛奶。", "corrected_sentence": "我昨天已经在超市买到了一瓶牛奶。", "error_description": "错误：“买到一瓶”；正确：“买到了一瓶”。“已经”表示动作已经完成，完成的“买到”后要加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去晚了，没买到了最后一张票。", "corrected_sentence": "我去晚了，没买到最后一张票。", "error_description": "错误：“没买到了”；正确：“没买到”。否定句中“没”与“了”不能同用，否定的结果补语后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
