INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大片的原意指投资大、制作精良、明星多的电影。", "primary_collocate": null, "pronunciation": "dà piàn", "ipa": "ta˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们周末排了两个小时的队，才买到这部大片的票。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部大片的特效非常精彩。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间有很多大片上映。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部大片请了好几位大明星。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去电影院看了一部大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部大片的投资超过了十亿元。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢看好莱坞大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个导演拍过好几部科幻大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大片的画面很漂亮，声音也很震撼。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假上映的大片太多了，我不知道看哪一部。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "好莱坞大片", "label": "复合"}, {"form": "贺岁大片", "label": "复合"}], "register": "口语", "sense_fingerprint": "大片|投资大、制作精良、明星多的电影", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12624, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大片", "is_correct": true, "explanation": "“大片”（dà piàn）指投资大、制作精良的电影。"}, {"text": "大篇", "is_correct": false, "explanation": "“篇”（piān）与“片”（piàn）声调不同，意思是篇幅大的文章。"}, {"text": "大变", "is_correct": false, "explanation": "“变”（biàn）与“片”（piàn）声母不同（b 与 p），意思是很大的变化。"}, {"text": "大殿", "is_correct": false, "explanation": "“殿”（diàn）与“片”（piàn）声母不同（d 与 p），意思是高大的殿堂。"}], "explanations": {"大片": "“大片”（dà piàn）指投资大、制作精良的电影。", "大篇": "“篇”（piān）与“片”（piàn）声调不同，意思是篇幅大的文章。", "大变": "“变”（biàn）与“片”（piàn）声母不同（b 与 p），意思是很大的变化。", "大殿": "“殿”（diàn）与“片”（piàn）声母不同（d 与 p），意思是高大的殿堂。"}, "sentence_index": null, "correct_answer": "大片"}, "level_3": {"options": [{"text": "大地", "is_correct": false, "explanation": "语义：“大地”指大自然的陆地，不能说“这部大地的票”。"}, {"text": "大厦", "is_correct": false, "explanation": "搭配：“大厦”是建筑物，不能用“这部”修饰，也不能买它的票。"}, {"text": "大片", "is_correct": true, "explanation": "“大片”指投资大、制作精良的电影，“这部大片的票”即这部电影的票。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是水域，不能用“这部”修饰，也没有可买的票。"}], "explanations": {"大地": "语义：“大地”指大自然的陆地，不能说“这部大地的票”。", "大厦": "搭配：“大厦”是建筑物，不能用“这部”修饰，也不能买它的票。", "大片": "“大片”指投资大、制作精良的电影，“这部大片的票”即这部电影的票。", "大海": "语义：“大海”是水域，不能用“这部”修饰，也没有可买的票。"}, "sentence_index": 0, "correct_answer": "大片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部大片收录了一百多张照片，我昨天看完了。", "explanation": "这里应该用〈画册〉。大片是电影，不能说收录了一百多张照片，应说“画册”。"}, {"text": "这部大片每周播出一集。", "explanation": "这里应该用〈电视剧〉。大片是一次上映的完整电影，不会按周播出。"}, {"text": "这部大片只拍了十分钟，成本很低。", "explanation": "这里应该用〈短片〉。大片指投资大、制作精良的电影，不可能只拍十分钟、成本很低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱片", "is_correct": false, "explanation": "搭配：“看”不搭配“唱片”，唱片是要听的。"}, {"text": "相声", "is_correct": false, "explanation": "语义：“相声”是曲艺节目，与好莱坞电影无关，“好莱坞相声”句意不通。"}, {"text": "大片", "is_correct": true, "explanation": "“好莱坞大片”指好莱坞出品的大型电影，可以用“看”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本与好莱坞影视无关，不能说“看好莱坞课本”。"}], "explanations": {"唱片": "搭配：“看”不搭配“唱片”，唱片是要听的。", "相声": "语义：“相声”是曲艺节目，与好莱坞电影无关，“好莱坞相声”句意不通。", "大片": "“好莱坞大片”指好莱坞出品的大型电影，可以用“看”。", "课本": "语义：课本与好莱坞影视无关，不能说“看好莱坞课本”。"}, "sentence_index": 6, "correct_answer": "大片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大片在体育馆举行，有很多歌手上台唱歌。", "explanation": "这里应该用〈演唱会〉。大片是在电影院放映的电影，不能在体育馆“举行”，也没有歌手上台唱歌。"}, {"text": "这部大片去年才出版，很多人在读。", "explanation": "这里应该用〈小说〉。大片是电影，不能说“出版”。"}, {"text": "孩子们在电脑上玩大片。", "explanation": "这里应该用〈游戏〉。大片是用来看的电影，不能说“玩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一口气看完过一部大片。", "corrected_sentence": "他一口气看完了一部大片。", "error_description": "体标错误：“看完”表示动作已完成，要用“了”，不能用表示经历的“过”，应说“看完了一部大片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天在家看了一张大片。", "corrected_sentence": "他昨天在家看了一部大片。", "error_description": "量词错误：电影用“部”，“张”用于纸张、票据等扁平的东西，不能用来数大片，应说“一部大片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
