INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12625, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在原有的基础上添加缺少的部分，使其完整或充足。", "primary_collocate": null, "pronunciation": "bǔ chōng", "ipa": "pu˨˩ ʈʂʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他每天早上吃一个鸡蛋，补充身体需要的蛋白质。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动以后要多喝水，补充身体的水分。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚才的话不完整，老师又补充了几句。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得很好，我再补充一点。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每天都补充新的货物。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把缺少的材料补充完整。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答不完整，你可以补充一下。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要补充足够的营养。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章缺了一些内容，作者又补充了。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员会吃香蕉补充体力。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "补充了", "label": "体标"}, {"form": "补充过", "label": "体标"}, {"form": "補充", "label": "繁体"}, {"form": "补充说明", "label": "复合"}], "register": "通用", "sense_fingerprint": "补充|在原有基础上添加缺少的部分使完整充足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补充", "is_correct": true, "explanation": "动词用法，表示补上身体缺少的营养，与句意相符。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”是变少，与“身体需要的蛋白质”要补入的语境相反。"}, {"text": "补丁", "is_correct": false, "explanation": "搭配：“补丁”是名词，不能作动词，“补丁身体需要的蛋白质”不通。"}, {"text": "补品", "is_correct": false, "explanation": "语义：“补品”是滋补食品或药品，是名词，不能作动词，句意不通。"}], "explanations": {"补充": "动词用法，表示补上身体缺少的营养，与句意相符。", "减少": "语义：“减少”是变少，与“身体需要的蛋白质”要补入的语境相反。", "补丁": "搭配：“补丁”是名词，不能作动词，“补丁身体需要的蛋白质”不通。", "补品": "语义：“补品”是滋补食品或药品，是名词，不能作动词，句意不通。"}, "sentence_index": 0, "correct_answer": "补充"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司今年的销售额补充了百分之二十。", "explanation": "这里应该用〈增加〉。补充表示把缺少的部分加进去使之完整，销售额上升是数量增多，要用增加。"}, {"text": "这本书补充了我的生活。", "explanation": "这里应该用〈充实〉。补充是补上缺少的部分，不用来说生活内容变丰富。"}, {"text": "公司补充了他的经济损失。", "explanation": "这里应该用〈补偿〉。补偿指弥补损失，补充表示添加缺少的东西，不能用于损失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补充", "is_correct": true, "explanation": "动词用法，表示补上不够的部分，与“不完整”呼应，符合句意。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉内容，与“回答不完整”需要增加内容的语境相反。"}, {"text": "删减", "is_correct": false, "explanation": "语义：“删减”也是去掉部分，与句中“不完整”的需要相反。"}, {"text": "收回", "is_correct": false, "explanation": "搭配：“收回”多与“话”“承诺”搭配，不能说“收回回答”。"}], "explanations": {"补充": "动词用法，表示补上不够的部分，与“不完整”呼应，符合句意。", "删除": "语义：“删除”是去掉内容，与“回答不完整”需要增加内容的语境相反。", "删减": "语义：“删减”也是去掉部分，与句中“不完整”的需要相反。", "收回": "搭配：“收回”多与“话”“承诺”搭配，不能说“收回回答”。"}, "sentence_index": 6, "correct_answer": "补充"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人补充了全部的责任。", "explanation": "这里应该用〈承担〉。补充表示补上缺少的部分，责任要说承担，不能说补充责任。"}, {"text": "他当众补充了自己的错误。", "explanation": "这里应该用〈承认〉。补充表示补上缺少的部分，认错要说承认，不能说补充错误。"}, {"text": "这次考试他的成绩补充了十分。", "explanation": "这里应该用〈提高〉。补充表示补上缺少的部分，成绩上升要说提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生建议病人多给身体补充了营养。", "corrected_sentence": "医生建议病人多给身体补充营养。", "error_description": "错误：“补充了营养”；正确：“补充营养”。“建议”指应当去做的事，还没有发生，不能用“了”表示已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才补充着一个观点。", "corrected_sentence": "他刚才补充了一个观点。", "error_description": "错误：“补充着”；正确：“补充了”。“刚才”指已经完成的动作，要用“了”；“着”表示动作持续或状态，与“刚才”矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
