INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12627, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中用于种植植物、改善环境并提供休闲场所的区域，如公园、花园等。", "primary_collocate": null, "pronunciation": "chéng shì lǜ dì", "ipa": "ʈʂʰɤŋ˧˥ ʂɻ̩˥˩ ly˥˩ ti˥˩", "syllable_count": 4, "sentences": [{"text": "在当代大都市的发展图景中，城市绿地与垂直农场已超越其单纯的生态功能，演变为重塑经济地理格局的战略性要素。", "target_word": "城市绿地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "规划中的新区将建设大片城市绿地。", "target_word": "城市绿地", "complexity_tier": "T3", "furigana": "guīhuà zhōng de xīnqū jiāng jiànshè dàpiàn chéngshì lǜdì.", "sentence_source": "generated"}, {"text": "城市绿地可以让空气变得更好。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们常去城市绿地散步。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的城市绿地明年春天开放。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在城市绿地里做游戏。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府准备增加城市绿地的面积。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市绿地里种着很多树和花。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片城市绿地很受老人喜欢。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市绿地太少，夏天会很热。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片城市绿地", "label": "量词"}, {"form": "一块城市绿地", "label": "量词"}, {"form": "城市绿地面积", "label": "复合"}, {"form": "城市綠地", "label": "繁体"}], "register": "书面", "sense_fingerprint": "城市里种植物、供人休闲的公园、花园等区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12627, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市绿地", "is_correct": true, "explanation": "城市绿地：指城市中供种植和休闲的区域，与“生态功能”相符。"}, {"text": "交响乐", "is_correct": false, "explanation": "语义：交响乐是音乐作品，与生态功能和经济地理格局无关，句子不通。"}, {"text": "地下停车场", "is_correct": false, "explanation": "语义：停车场没有生态功能，与句中“生态功能”的语义冲突。"}, {"text": "城市人口", "is_correct": false, "explanation": "搭配：“生态功能”指自然环境的作用，不能用“城市人口”作主语。"}], "explanations": {"城市绿地": "城市绿地：指城市中供种植和休闲的区域，与“生态功能”相符。", "交响乐": "语义：交响乐是音乐作品，与生态功能和经济地理格局无关，句子不通。", "地下停车场": "语义：停车场没有生态功能，与句中“生态功能”的语义冲突。", "城市人口": "搭配：“生态功能”指自然环境的作用，不能用“城市人口”作主语。"}, "sentence_index": 0, "correct_answer": "城市绿地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的城市绿地里种满了玫瑰。", "explanation": "这里应该用〈花园〉。城市绿地是供公众使用的公共区域，说自家的庭院要用花园。"}, {"text": "我家附近有一只城市绿地。", "explanation": "这里应该用〈块〉或〈片〉。城市绿地是一片场地，量词不能用“只”（“只”多用于动物）。"}, {"text": "清明节，我们全家去城市绿地里给爷爷扫墓。", "explanation": "这里应该用〈墓地〉。城市绿地是供人休闲的绿化场所，扫墓要去墓地或陵园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市绿地", "is_correct": true, "explanation": "城市绿地：指可以增加面积的公共绿化区域，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“面积”用于可计量的平面或空间，不能与“空气”搭配。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资没有面积可言，“增加工资的面积”句意不通。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“面积”不能与抽象的“友谊”搭配。"}], "explanations": {"城市绿地": "城市绿地：指可以增加面积的公共绿化区域，符合句意。", "空气": "搭配：“面积”用于可计量的平面或空间，不能与“空气”搭配。", "工资": "语义：工资没有面积可言，“增加工资的面积”句意不通。", "友谊": "搭配：“面积”不能与抽象的“友谊”搭配。"}, "sentence_index": 6, "correct_answer": "城市绿地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在城市绿地里装配汽车。", "explanation": "这里应该用〈车间〉。城市绿地是供人休闲的绿化场所，装配汽车要在车间或工厂里进行。"}, {"text": "我家门前有一间城市绿地。", "explanation": "这里应该用〈块〉或〈片〉。城市绿地是露天场地，不能用“间”（“间”用于房屋）。"}, {"text": "操场中间铺着一大片城市绿地。", "explanation": "这里应该用〈草坪〉。草坪指铺设的草地，城市绿地是城市的公共绿化区域，不用来称学校操场的草地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决定在老城区建设一所城市绿地。", "corrected_sentence": "政府决定在老城区建设一片城市绿地。", "error_description": "量词用错：“城市绿地”应配“片”或“块”，“所”用于学校、医院等机构，不能用于绿地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些城市绿地们都由政府管理。", "corrected_sentence": "这些城市绿地都由政府管理。", "error_description": "词缀用错：“城市绿地”是无生命的事物，不能加“们”表示复数，“这些”已表示多数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
