INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12628, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指对整体或长远发展有重大意义和影响的安排或决策。", "primary_collocate": null, "pronunciation": "zhàn lüè xìng", "ipa": "ʈʂan˥˩ lɥe˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "在当代大都市的发展图景中，城市绿地与垂直农场已超越其单纯的生态功能，演变为重塑经济地理格局的战略性要素。", "target_word": "战略性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是公司最重要的战略性决定。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做了一个战略性投资。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市把新能源当作战略性产业。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视战略性资源的安全。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这是一个战略性项目，不能随便改。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次合作对公司的长远发展有战略性意义。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用战略性的眼光看未来十年。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口位置很重要，具有战略性价值。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，粮食是国家的战略性物资。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "战略性思维", "label": "复合"}, {"form": "战略性投资", "label": "复合"}], "register": "书面", "sense_fingerprint": "对整体和长远发展有重大意义的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战略性", "is_correct": true, "explanation": "正确：修饰“要素”，指对经济地理格局的重塑有全局性作用，与句意相合。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：“装饰性”只指外观点缀，与“重塑经济地理格局”的作用相反。"}, {"text": "临时性", "is_correct": false, "explanation": "语义：“临时性”指只在短时间内存在，与“重塑经济地理格局”这种长远作用矛盾。"}, {"text": "边缘性", "is_correct": false, "explanation": "语义：“边缘性”指处于次要位置或作用不大，与“重塑经济地理格局”的关键作用不合。"}], "explanations": {"战略性": "正确：修饰“要素”，指对经济地理格局的重塑有全局性作用，与句意相合。", "装饰性": "语义：“装饰性”只指外观点缀，与“重塑经济地理格局”的作用相反。", "临时性": "语义：“临时性”指只在短时间内存在，与“重塑经济地理格局”这种长远作用矛盾。", "边缘性": "语义：“边缘性”指处于次要位置或作用不大，与“重塑经济地理格局”的关键作用不合。"}, "sentence_index": 0, "correct_answer": "战略性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心碰倒了水杯，这是一个战略性的举动。", "explanation": "这里应该用〈无意〉。碰倒水杯是无意发生的，“战略性”指经过全局与长远考虑的安排，二者矛盾。"}, {"text": "为了应付眼前的小问题，他做了一个战略性的决定。", "explanation": "这里应该用〈短期〉。“战略性”指关乎整体与长远发展的安排，“应付眼前的小问题”只是短期应对，二者不符。"}, {"text": "他饿了就随便吃点东西，这是一个战略性的决定。", "explanation": "这里应该用〈草率〉。“随便吃点东西”说明没有经过筹划，“战略性”指经过全局与长远考虑，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战略性", "is_correct": true, "explanation": "正确：修饰“意义”，表示对公司长远发展有重大影响，与句意相合。"}, {"text": "短期性", "is_correct": false, "explanation": "语义：“短期性”与“长远发展”相反，不能修饰“意义”。"}, {"text": "随机性", "is_correct": false, "explanation": "搭配：“随机性”多修饰过程、结果，不说“有随机性意义”。"}, {"text": "形式性", "is_correct": false, "explanation": "语义：“形式性”指只有形式、缺少实际内容，与“长远发展”的实质作用不合。"}], "explanations": {"战略性": "正确：修饰“意义”，表示对公司长远发展有重大影响，与句意相合。", "短期性": "语义：“短期性”与“长远发展”相反，不能修饰“意义”。", "随机性": "搭配：“随机性”多修饰过程、结果，不说“有随机性意义”。", "形式性": "语义：“形式性”指只有形式、缺少实际内容，与“长远发展”的实质作用不合。"}, "sentence_index": 6, "correct_answer": "战略性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只是一项战略性的小事，不必放在心上。", "explanation": "这里应该用〈次要〉。“小事”“不必放在心上”指次要事务，“战略性”指关乎全局的重要安排。"}, {"text": "他每天早上都战略性地刷牙。", "explanation": "这里应该用〈例行〉。刷牙是例行的日常事务，“战略性”指关乎整体与长远发展的安排，不能用于此。"}, {"text": "这是一个战略性的决定，其实他只是随口一说。", "explanation": "这里应该用〈随意〉。“随口一说”说明没有经过筹划，“战略性”指经过全局与长远考虑，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一项战略性地工程。", "corrected_sentence": "这是一项战略性的工程。", "error_description": "错误：“战略性”后用了“地”，但“地”用于修饰动词、形容词；修饰名词“工程”应用“的”。正确：“战略性的工程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司战略性把这个项目交给了我们。", "corrected_sentence": "公司战略性地把这个项目交给了我们。", "error_description": "漏“地”：“战略性”修饰整个动词短语“把这个项目交给了我们”，作状语时要加“地”，应为“战略性地把……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
