INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12629, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "构成事物本质或必不可少的组成部分。", "primary_collocate": null, "pronunciation": "yào sù", "ipa": "jɑʊ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "时间、地点和人物是故事的三个要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水是生命不可少的要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做好这件事，有几个关键要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一篇好文章要有哪些要素？", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻有六个基本要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚信是做生意的基本要素之一。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光和水都是植物长大的要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，计划的要素要写清楚。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找出成功的几个要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好电影的要素，不只是故事。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个要素", "label": "量词"}, {"form": "一项要素", "label": "量词"}], "register": "中性", "sense_fingerprint": "构成事物必不可少的组成部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要素", "is_correct": true, "explanation": "要素：构成事物本质的组成部分，时间、地点和人物正是故事的这类内容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不是故事的构成部分，句意不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指一定地区的人数，只用于地区或国家，不能说“故事的人口”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，与故事的构成内容无关，句意不通。"}], "explanations": {"要素": "要素：构成事物本质的组成部分，时间、地点和人物正是故事的这类内容。", "颜色": "语义：“颜色”指色彩，不是故事的构成部分，句意不通。", "人口": "搭配：“人口”指一定地区的人数，只用于地区或国家，不能说“故事的人口”。", "价格": "语义：“价格”指钱数，与故事的构成内容无关，句意不通。"}, "sentence_index": 0, "correct_answer": "要素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的要素很幽默，读起来很轻松。", "explanation": "这里应该用〈风格〉。要素指构成事物的必要部分，不能用“幽默”形容；说文章的表达方式要用〈风格〉。"}, {"text": "老师发了几粒要素。", "explanation": "量词错误：〈粒〉用于米、沙等细小颗粒，要素是抽象的组成部分，应该用〈个〉或〈项〉。"}, {"text": "他的要素很开朗，大家都喜欢和他聊天。", "explanation": "这里应该用〈性格〉。要素指构成事物必不可少的部分，不能用“开朗”形容人；说人的为人和脾气要用〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要素", "is_correct": true, "explanation": "要素：构成植物长大必不可少的组成部分，阳光和水正属于这一类。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是供玩耍的物品，阳光和水不是玩具，句意不通。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“衣服”是穿在身上的东西，与植物长大无关，句意不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是付给人的报酬，不能说植物的工资，搭配不成立。"}], "explanations": {"要素": "要素：构成植物长大必不可少的组成部分，阳光和水正属于这一类。", "玩具": "语义：“玩具”是供玩耍的物品，阳光和水不是玩具，句意不通。", "衣服": "语义：“衣服”是穿在身上的东西，与植物长大无关，句意不通。", "工资": "搭配：“工资”是付给人的报酬，不能说植物的工资，搭配不成立。"}, "sentence_index": 6, "correct_answer": "要素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影有几颗要素。", "explanation": "量词错误：〈颗〉多用于珠子、星星等，要素应用〈个〉或〈项〉。"}, {"text": "这部电影的要素很深刻。", "explanation": "这里应该用〈思想〉。要素指构成事物的必要部分，不能用“深刻”来形容；说内容的深度要用〈思想〉。"}, {"text": "这部电影的要素很有名，大家都看过。", "explanation": "这里应该用〈演员〉。要素是抽象的组成部分，不能“有名”；说电影里的人很有名，要用〈演员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习一门外语，有三根基本要素。", "corrected_sentence": "学习一门外语，有三个基本要素。", "error_description": "量词错误：“要素”是抽象的组成部分，应用“个”，“根”用于细长的东西，应改为“三个基本要素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一部好作品有三只要素。", "corrected_sentence": "一部好作品有三个要素。", "error_description": "量词错误：“只”一般用于动物或成对的东西，抽象的“要素”应用“个”，应为“三个要素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
