INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12630, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指长期以来普遍认同或流传下来的含义。", "primary_collocate": null, "pronunciation": "chuán tǒng yì yì", "ipa": "ʈʂʰwan˧˥ tʰʊŋ˨˩˦ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "传统意义上被视为“非生产性空间”的公园、社区花园乃至建筑立面与屋顶的绿化系统，正通过多重价值链条深度嵌入城市资本循环。", "target_word": "传统意义", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在传统意义上，家就是一家人住的地方。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统意义的“成功”常常指有钱和有地位。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词在传统意义上只指男人。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统意义上，春节是全家人团圆的日子。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书重新解释了“孝”的传统意义。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从传统意义来说，教师就是传授知识的人。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的作品已经超出了传统意义上的绘画。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统意义上的邻居，是住在隔壁的人。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人说的“君子”，传统意义是指品德高尚的人。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传统意义上", "label": "复合"}], "register": "书面", "sense_fingerprint": "长期流传下来、普遍认同的含义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传统意义", "is_correct": true, "explanation": "正确：指长期以来被认同的看法，与句中“正通过……嵌入”的今昔对比相合。"}, {"text": "价格意义", "is_correct": false, "explanation": "搭配：“价格意义上”不是常用说法，不能引出长期流传的看法。"}, {"text": "数量意义", "is_correct": false, "explanation": "搭配：“数量意义”不是常用说法，与“被视为非生产性空间”的语境无关。"}, {"text": "体积意义", "is_correct": false, "explanation": "搭配：“体积意义”不是常用说法，与“被视为非生产性空间”的语境无关。"}], "explanations": {"传统意义": "正确：指长期以来被认同的看法，与句中“正通过……嵌入”的今昔对比相合。", "价格意义": "搭配：“价格意义上”不是常用说法，不能引出长期流传的看法。", "数量意义": "搭配：“数量意义”不是常用说法，与“被视为非生产性空间”的语境无关。", "体积意义": "搭配：“体积意义”不是常用说法，与“被视为非生产性空间”的语境无关。"}, "sentence_index": 0, "correct_answer": "传统意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的传统意义很大。", "explanation": "这里应该用〈规模〉。“传统意义”指长期流传的含义，不指企业的大小，说企业大小要用“规模”。"}, {"text": "他的传统意义很高。", "explanation": "这里应该用〈水平〉。“传统意义”不指能力高低，说水平高要用“水平”。"}, {"text": "这辆车的传统意义很快。", "explanation": "这里应该用〈速度〉。“传统意义”指长期流传的含义，不指车的快慢，形容车速快要说“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传统意义", "is_correct": true, "explanation": "正确：“从传统意义来说”引出长期流传的定义，与“教师就是传授知识的人”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与教师的职责无关，句子无法成立。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”多用于土地、房屋，不用来说明人的职责。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不能用来界定教师的职责。"}], "explanations": {"传统意义": "正确：“从传统意义来说”引出长期流传的定义，与“教师就是传授知识的人”相合。", "颜色": "语义：“颜色”与教师的职责无关，句子无法成立。", "面积": "搭配：“面积”多用于土地、房屋，不用来说明人的职责。", "价格": "语义：“价格”不能用来界定教师的职责。"}, "sentence_index": 6, "correct_answer": "传统意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的传统意义比我大。", "explanation": "这里应该用〈年纪〉。“传统意义”指长期流传的含义，不指人的年龄，说年龄大小要用“年纪”。"}, {"text": "这道菜的传统意义很好。", "explanation": "这里应该用〈味道〉。“传统意义”不指食物的口感，说味道好要用“味道”。"}, {"text": "他的传统意义很好。", "explanation": "这里应该用〈成绩〉。“传统意义”不指学业表现，说成绩好要用“成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在传统意义，这个字指的是祭祀。", "corrected_sentence": "在传统意义上，这个字指的是祭祀。", "error_description": "漏“上”：“在……意义”之后要加“上”，应为“在传统意义上”；漏掉“上”，结构不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个解释符合很传统意义。", "corrected_sentence": "这个解释符合传统意义。", "error_description": "错误：“很”不能修饰名词性的“传统意义”，应删去“很”，说“符合传统意义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生产性", "is_correct": true, "explanation": "反义：“生产性”与“非生产性”构成对立，指能直接产生经济效益。"}, {"text": "活泼的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，只是形容性格或状态的形容词。"}, {"text": "精确的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是准确程度。"}, {"text": "潮湿的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是环境状态。"}], "correct_answer": "生产性", "explanations": {"生产性": "反义：“生产性”与“非生产性”构成对立，指能直接产生经济效益。", "活泼的": "与“非生产性”的意义没有反义关系，只是形容性格或状态的形容词。", "精确的": "与“非生产性”的意义没有反义关系，描述的是准确程度。", "潮湿的": "与“非生产性”的意义没有反义关系，描述的是环境状态。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生产性", "is_correct": true, "explanation": "反义：“生产性”与“非生产性”构成对立，指能直接产生经济效益。"}, {"text": "紧凑的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是结构或布局。"}, {"text": "清晰的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是清楚程度。"}, {"text": "宽敞的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是空间大小。"}], "correct_answer": "生产性", "explanations": {"生产性": "反义：“生产性”与“非生产性”构成对立，指能直接产生经济效益。", "紧凑的": "与“非生产性”的意义没有反义关系，描述的是结构或布局。", "清晰的": "与“非生产性”的意义没有反义关系，描述的是清楚程度。", "宽敞的": "与“非生产性”的意义没有反义关系，描述的是空间大小。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指不能直接产生经济效益或实际成果的，比如不创造产品的活动。", "primary_collocate": null, "pronunciation": "fēi shēng chǎn xìng", "ipa": "fei˥ ʂɤŋ˥ ʈʂʰan˨˩˦ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "传统意义上被视为“非生产性空间”的公园、社区花园乃至建筑立面与屋顶的绿化系统，正通过多重价值链条深度嵌入城市资本循环。", "target_word": "非生产性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这笔钱是非生产性支出，不能带来收入。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要减少非生产性开支。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会太多，会增加非生产性工作时间。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园被看作非生产性空间，但对城市很重要。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂有很多非生产性人员，比如保安和司机。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买办公室的新沙发属于非生产性投资。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想把非生产性成本降到最低。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非生产性活动也可能对社会有好处。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地长期闲着，是非生产性资产。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非生产性支出", "label": "复合"}, {"form": "非生产性活动", "label": "复合"}], "register": "书面", "sense_fingerprint": "不能直接产生经济效益的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非生产性", "is_correct": true, "explanation": "句中“非生产性空间”指传统上不能直接产生经济效益的空间，与“绿化系统”嵌入城市循环的语境相符。"}, {"text": "工业性", "is_correct": false, "explanation": "语义：公园、社区花园不属于工业空间，“被视为工业空间”与绿化系统的语境矛盾。"}, {"text": "慈善性", "is_correct": false, "explanation": "语义：公园的性质不是慈善，“慈善性空间”与句中描述的城市空间功能不符。"}, {"text": "盈利性", "is_correct": false, "explanation": "语义：公园、社区花园在传统上并不被视为赚钱的空间，“盈利性空间”与句中“传统上不产生效益、如今才嵌入资本循环”的对比相反。"}], "explanations": {"非生产性": "句中“非生产性空间”指传统上不能直接产生经济效益的空间，与“绿化系统”嵌入城市循环的语境相符。", "工业性": "语义：公园、社区花园不属于工业空间，“被视为工业空间”与绿化系统的语境矛盾。", "慈善性": "语义：公园的性质不是慈善，“慈善性空间”与句中描述的城市空间功能不符。", "盈利性": "语义：公园、社区花园在传统上并不被视为赚钱的空间，“盈利性空间”与句中“传统上不产生效益、如今才嵌入资本循环”的对比相反。"}, "sentence_index": 0, "correct_answer": "非生产性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每年的非生产性利润很高。", "explanation": "这里与“利润很高”矛盾。“非生产性”指不能直接产生经济效益，不能用来描述利润高，这里应说〈盈利〉或〈收益〉相关的说法。"}, {"text": "这位工人非生产性地完成了今天的全部订单。", "explanation": "“非生产性”形容的是本身不产出的活动或事情，不能用来形容完成任务的方式，这里应说〈高效〉。"}, {"text": "这台机器每天都在生产零件，是非生产性设备。", "explanation": "“非生产性”不能用来形容明明在生产零件的设备，这里应说〈生产性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非生产性", "is_correct": true, "explanation": "“非生产性投资”指不能带来经济回报的投资，与买办公室沙发的语境相符。"}, {"text": "投机性", "is_correct": false, "explanation": "语义：办公室的新沙发不是投机性投资，“投机性”与办公用品的用途不符。"}, {"text": "收藏性", "is_correct": false, "explanation": "语义：办公室的沙发通常用于办公使用，不作收藏，“收藏性投资”与句中语境矛盾。"}, {"text": "盈利性", "is_correct": false, "explanation": "语义：办公室的新沙发不带来收益，“盈利性投资”与句中的用途相反。"}], "explanations": {"非生产性": "“非生产性投资”指不能带来经济回报的投资，与买办公室沙发的语境相符。", "投机性": "语义：办公室的新沙发不是投机性投资，“投机性”与办公用品的用途不符。", "收藏性": "语义：办公室的沙发通常用于办公使用，不作收藏，“收藏性投资”与句中语境矛盾。", "盈利性": "语义：办公室的新沙发不带来收益，“盈利性投资”与句中的用途相反。"}, "sentence_index": 6, "correct_answer": "非生产性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地每年种菜，收成很好，是非生产性资产。", "explanation": "这里与“收成很好”矛盾。“非生产性”指不能直接产生经济效益，种菜有产出，应说〈生产性〉。"}, {"text": "这家公司的新产品卖得很好，是非生产性项目。", "explanation": "“非生产性”不能用来形容能带来销售收入的项目，这里应说〈盈利性〉或〈生产性〉。"}, {"text": "这家面包店每天烤出几百个面包，是非生产性的场所。", "explanation": "“非生产性”指不能直接产生经济效益，这里“烤出几百个面包”说明在直接生产，应说〈生产性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔钱是很非生产性支出。", "corrected_sentence": "这笔钱是非生产性支出。", "error_description": "错误形式：“很非生产性”。正确形式：“非生产性”。“非生产性”是固定的书面形容词，不能用“很”修饰，直接放在名词前即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的旧机器一直闲着，是一块非生产性资产。", "corrected_sentence": "这家公司的旧机器一直闲着，是一项非生产性资产。", "error_description": "量词错误：“资产”应用量词“项”，不用“块”（“块”多用于地块、块状物）。正确：“一项非生产性资产”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
