INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人居住的房屋或建筑。", "primary_collocate": null, "pronunciation": "zhù zhái", "ipa": "ʈʂu˥˩ ʈʂai˧˥", "syllable_count": 2, "sentences": [{"text": "离地铁站近的住宅更好卖。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府计划在这里建很多住宅。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋住宅有三十层。", "target_word": "住宅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在城东买了一处新住宅。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里不是商店，而是普通住宅。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住宅附近最好有学校和医院。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住宅附近有一个大公园。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些住宅都是二十年前建的。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了安全，住宅的门要装好锁。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老城区的住宅大多比较旧。", "target_word": "住宅", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "住宅楼", "label": "复合"}, {"form": "住宅区", "label": "复合"}], "register": "书面", "sense_fingerprint": "供人居住的房屋或建筑，与商业、办公建筑相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e86e3800-c774-4bb9-819f-808d2bbca123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住宅", "is_correct": true, "explanation": "正确。句子说的是可以出售的房屋，「离地铁站近的住宅更好卖」语义通顺。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是公共场所，不用于出售，「更好卖」的说法不成立。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林不是可以出售的房产或商品，句子说的卖的对象，语义不通。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：「离……近」要求地点或建筑作主语，「房价」不能与「离地铁站近」搭配。"}], "explanations": {"住宅": "正确。句子说的是可以出售的房屋，「离地铁站近的住宅更好卖」语义通顺。", "公园": "语义：公园是公共场所，不用于出售，「更好卖」的说法不成立。", "树林": "语义：树林不是可以出售的房产或商品，句子说的卖的对象，语义不通。", "房价": "搭配：「离……近」要求地点或建筑作主语，「房价」不能与「离地铁站近」搭配。"}, "sentence_index": 0, "correct_answer": "住宅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在城东买了一张新住宅。", "explanation": "这里应该用〈套〉或〈栋〉。张多用于桌、床、纸等扁平或平面的东西，住宅不用「张」。"}, {"text": "这条街上新盖了一只住宅。", "explanation": "这里应该用〈栋〉。只多用于动物或成对器物中的一个，住宅不用「只」。"}, {"text": "她在城东看中了一本新住宅。", "explanation": "这里应该用〈套〉。本用于书、册子等，住宅不用「本」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住宅", "is_correct": true, "explanation": "正确。「……附近有一个大公园」说的是居住的地方，只有住宅符合。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不能作为公园的位置参照，句意不通。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓是水果，不是可以作为地点参照的场所。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：「附近」要求具体地点，抽象名词「友谊」不能用来定位公园。"}], "explanations": {"住宅": "正确。「……附近有一个大公园」说的是居住的地方，只有住宅符合。", "牛奶": "语义：牛奶是饮品，不能作为公园的位置参照，句意不通。", "草莓": "语义：草莓是水果，不是可以作为地点参照的场所。", "友谊": "搭配：「附近」要求具体地点，抽象名词「友谊」不能用来定位公园。"}, "sentence_index": 6, "correct_answer": "住宅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动员在住宅里比赛。", "explanation": "这里应该用〈体育场〉。比赛要在体育场或赛场进行，住宅不是比赛场所。"}, {"text": "孩子们每天放学后在住宅里上体育课。", "explanation": "这里应该用〈体育馆〉。体育课要在体育馆或操场上进行，住宅只供居住，不能用来上体育课。"}, {"text": "飞机都停在住宅里。", "explanation": "这里应该用〈机场〉。飞机停在机场，住宅是供人居住的房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家门口有一本新住宅。", "corrected_sentence": "他家门口有一栋新住宅。", "error_description": "「住宅」的量词应为「栋」（或「套」），不应用「本」。「本」用于书册，这种量词误用是学习者常见的错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些住宅们都在河边。", "corrected_sentence": "那些住宅都在河边。", "error_description": "「们」只用于指人或有生命的群体，住宅是无生命的建筑，名词后不能加「们」，应直接说「那些住宅」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
