INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12649, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指投入资金以获取利润的个人或机构。", "primary_collocate": null, "pronunciation": "tóu zī zhě", "ipa": "tʰoʊ˧˥ tsɹ̩˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "投资者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位投资者买了一家小公司。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者希望公司每年都能赚钱。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多投资者在买股票以前会看报告。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家银行的主要投资者是两家大公司。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者把钱放进了新能源项目。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司发布了年报，投资者很关心利润。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者要先了解风险，再做决定。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国投资者对这个城市很有兴趣。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理向投资者介绍了新的计划。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位投资者", "label": "量词"}, {"form": "个人投资者", "label": "复合"}, {"form": "机构投资者", "label": "复合"}], "register": "正式", "sense_fingerprint": "投入资金以获取利润的个人或机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12649, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投资者", "is_correct": true, "explanation": "正确。句中说“不再仅评估建筑面积与区位”并“推动开发商”，主语只能是评估风险的资本方，即投资者。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁不评估建筑面积与风险模型，与句子的金融评估语境矛盾。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与“评估风险模型”“资产流动性”毫不相干，句子的主语无法成立。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“小孩”不能作为“评估核心风险模型”的主语，这类主语要求专业的资本方。"}], "explanations": {"投资者": "正确。句中说“不再仅评估建筑面积与区位”并“推动开发商”，主语只能是评估风险的资本方，即投资者。", "园丁": "语义：园丁不评估建筑面积与风险模型，与句子的金融评估语境矛盾。", "厨师": "语义：厨师与“评估风险模型”“资产流动性”毫不相干，句子的主语无法成立。", "小孩": "搭配：“小孩”不能作为“评估核心风险模型”的主语，这类主语要求专业的资本方。"}, "sentence_index": 0, "correct_answer": "投资者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目的投资者是三百万元。", "explanation": "这里应该用〈投资额〉。投资者指投钱的人，不指投入的金额；金额要用“投资额”。"}, {"text": "这次会议的投资者是下午三点。", "explanation": "这里应该用〈时间〉。投资者指投钱的人，不指时间；会议开始的时间要用“时间”。"}, {"text": "那把投资者很有钱。", "explanation": "量词应用“位”或“个”；“把”用于有柄的器具，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投资者", "is_correct": true, "explanation": "正确。前半句说“公司发布了年报”，后半句“很关心利润”，关心利润的应是有利益诉求的资本方，即投资者。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意识，不能“关心利润”，与句子语境矛盾。"}, {"text": "窗帘", "is_correct": false, "explanation": "配价：“关心”需要有意识的主体作主语，窗帘不能充当这一角色。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会关心利润，句子的主语必须是能关心经营成果的人。"}], "explanations": {"投资者": "正确。前半句说“公司发布了年报”，后半句“很关心利润”，关心利润的应是有利益诉求的资本方，即投资者。", "石头": "语义：石头没有意识，不能“关心利润”，与句子语境矛盾。", "窗帘": "配价：“关心”需要有意识的主体作主语，窗帘不能充当这一角色。", "房子": "语义：房子不会关心利润，句子的主语必须是能关心经营成果的人。"}, "sentence_index": 6, "correct_answer": "投资者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们买了很多投资者。", "explanation": "这里应该用〈股票〉。投资者指投钱获利的人，不能被买；买的是“股票”。"}, {"text": "这杯投资者很好喝，我们都爱喝。", "explanation": "这里应该用〈咖啡〉。投资者指投钱获利的人或机构，不能用来喝；饮品要用“咖啡”。"}, {"text": "那条投资者很有钱。", "explanation": "量词应用“位”或“个”；“条”用于细长的东西，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只投资者在考虑收购那家工厂。", "corrected_sentence": "一位投资者在考虑收购那家工厂。", "error_description": "错误：“一只投资者”，正确：“一位投资者”。“只”多用于动物，投资者指人，量词要用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司吸引了很多投资者们。", "corrected_sentence": "这家公司吸引了很多投资者。", "error_description": "错误：“很多投资者们”，正确：“很多投资者”。“投资者”前已有“很多”表示多数，后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
