INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "建筑物各层水平投影面积的总和，包括使用面积、辅助面积和结构面积。", "primary_collocate": null, "pronunciation": "jiàn zhù miàn jī", "ipa": "tɕjɛn˥˩ ʈʂu˥˩ mjɛn˥˩ tɕi˥", "syllable_count": 4, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "建筑面积", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个小区的建筑面积是十万平方米。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套房子的建筑面积有九十平方米。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房以前，要先看建筑面积。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼的建筑面积比那栋大。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "建筑面积包括每一层的面积。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校新楼的建筑面积超过了两万平方米。", "target_word": "建筑面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建筑面积越大，房子的价格越高。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把新办公楼的建筑面积写在了合同上。", "target_word": "建筑面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商场的建筑面积很大，有五层。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "总建筑面积", "label": "复合"}], "register": "正式", "sense_fingerprint": "建筑物各层水平投影面积的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建筑面积", "is_correct": true, "explanation": "语义正确：此处指房产的建筑面积，与“区位”并列，是评估房产时的指标。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的身体指标，不是房产评估的对象，与“区位”并列毫无道理。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历用于评估人，不能用来评估房产，句中“评估”的对象应是房产。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：“评估”后接的是房产的价值或指标，“饮食”不能作为评估对象。"}], "explanations": {"建筑面积": "语义正确：此处指房产的建筑面积，与“区位”并列，是评估房产时的指标。", "体重": "语义：体重是人的身体指标，不是房产评估的对象，与“区位”并列毫无道理。", "学历": "语义：学历用于评估人，不能用来评估房产，句中“评估”的对象应是房产。", "饮食": "搭配：“评估”后接的是房产的价值或指标，“饮食”不能作为评估对象。"}, "sentence_index": 0, "correct_answer": "建筑面积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公园的建筑面积有三百亩。", "explanation": "这里应该用〈占地面积〉。建筑面积只计算建筑物各层的水平投影面积，公园是露天场地，计量土地要用占地面积，且“亩”是土地单位。"}, {"text": "这栋楼的建筑面积是一百米。", "explanation": "这里应该用〈建筑高度〉。建筑面积是面积，要用平方米计量；“一百米”说的是高度，不是面积。"}, {"text": "这栋楼的建筑面积有三个。", "explanation": "量词错误：建筑面积是面积，应用“平方米”计量，不能用“个”来计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑面积", "is_correct": true, "explanation": "语义正确：“超过了两万平方米”说的是学校新楼的面积，只有“建筑面积”符合。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数是人的数量，不能用“超过了两万平方米”来描述。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”以元计，不能用“平方米”计量，与“超过了两万平方米”不搭。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是年数，不是面积，句子说的是楼的面积超过了多少平方米。"}], "explanations": {"建筑面积": "语义正确：“超过了两万平方米”说的是学校新楼的面积，只有“建筑面积”符合。", "人数": "语义：人数是人的数量，不能用“超过了两万平方米”来描述。", "工资": "搭配：“工资”以元计，不能用“平方米”计量，与“超过了两万平方米”不搭。", "年龄": "语义：年龄是年数，不是面积，句子说的是楼的面积超过了多少平方米。"}, "sentence_index": 6, "correct_answer": "建筑面积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目的建筑面积是五百万元。", "explanation": "这里应该用〈建筑成本〉。建筑面积是面积，要用平方米计量；花费的金额属于建筑成本。"}, {"text": "我的手机建筑面积很大。", "explanation": "这里应该用〈屏幕面积〉。建筑面积只指建筑物各层面积的总和，手机不是建筑物，应说“屏幕面积”。"}, {"text": "这个水箱的建筑面积是一千升。", "explanation": "这里应该用〈容积〉。建筑面积是面积，要用平方米；“一千升”是容量单位，应当说容积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋写字楼的建筑面积有三千个。", "corrected_sentence": "这栋写字楼的建筑面积有三千平方米。", "error_description": "量词错误：建筑面积是面积，应用“平方米”计量，不能用“个”。应说“这栋写字楼的建筑面积有三千平方米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座塔的建筑面积有两千升。", "corrected_sentence": "这座塔的建筑面积有两千平方米。", "error_description": "单位错误：建筑面积是面积，应用“平方米”计量；“升”是容积单位。应说“这座塔的建筑面积有两千平方米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
