INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12653, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开发商指从事房地产开发、建设、销售等经营活动的企业或个人。", "primary_collocate": null, "pronunciation": "kāi fā shāng", "ipa": "kʰai˥ fa˥ ʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "开发商", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家开发商在城东盖了三栋楼。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商说房子年底就能交给业主。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房以前，我先查了这个开发商的名声。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商在小区里种了很多树。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个开发商卖的房子，价格比别家便宜。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商没有按时交房，业主们很生气。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位开发商打算在海边建一个新小区。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商请了有名的设计师来画图纸。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新楼盘的开发商今天开了发布会。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "房地产开发商", "label": "复合"}, {"form": "開發商", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开发商：从事房地产开发、建设、销售的企业或个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开发商", "is_correct": true, "explanation": "正确。“开发商”指从事房地产开发、建设、销售的企业或个人，是这里推动生态设施决策的主体。"}, {"text": "房价", "is_correct": false, "explanation": "配价：“推动”后面要有能动的施事，“房价”是数值，不能“推动……将……视为”。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不做房地产投资决策，与前文“投资者评估风险模型”的语境不符。"}, {"text": "地段", "is_correct": false, "explanation": "配价：“地段”指位置，不能作“推动”的施事，也不能“将设施视为杠杆”。"}], "explanations": {"开发商": "正确。“开发商”指从事房地产开发、建设、销售的企业或个人，是这里推动生态设施决策的主体。", "房价": "配价：“推动”后面要有能动的施事，“房价”是数值，不能“推动……将……视为”。", "小学生": "语义：小学生不做房地产投资决策，与前文“投资者评估风险模型”的语境不符。", "地段": "配价：“地段”指位置，不能作“推动”的施事，也不能“将设施视为杠杆”。"}, "sentence_index": 0, "correct_answer": "开发商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小区的开发商每天都来打扫卫生。", "explanation": "这里应该用〈物业〉。开发商负责建房、卖房，日常保洁和维护由物业公司负责，不用“开发商”。"}, {"text": "开发商每天晚上给孩子讲故事。", "explanation": "这里应该用〈家长〉。给孩子讲故事是家长的事，开发商是盖房、卖房的企业或个人。"}, {"text": "开发商把我的西装改小了一寸。", "explanation": "这里应该用〈裁缝〉。改小西装是裁缝的工作，开发商是盖房、卖房的企业或个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发商", "is_correct": true, "explanation": "正确。“开发商”是建房、卖房的一方，负责按时交房，与“业主们很生气”前后呼应。"}, {"text": "设计院", "is_correct": false, "explanation": "搭配：“交房”由建房、卖房的一方负责，设计院只负责图纸，不说“设计院没有按时交房”。"}, {"text": "业主", "is_correct": false, "explanation": "语义：“业主”是收房的一方，不会“没有按时交房”，且与后半句的“业主们”重复指代。"}, {"text": "银行", "is_correct": false, "explanation": "配价：“交房”需要能交付房屋的主体，“银行”不能作这里的施事。"}], "explanations": {"开发商": "正确。“开发商”是建房、卖房的一方，负责按时交房，与“业主们很生气”前后呼应。", "设计院": "搭配：“交房”由建房、卖房的一方负责，设计院只负责图纸，不说“设计院没有按时交房”。", "业主": "语义：“业主”是收房的一方，不会“没有按时交房”，且与后半句的“业主们”重复指代。", "银行": "配价：“交房”需要能交付房屋的主体，“银行”不能作这里的施事。"}, "sentence_index": 6, "correct_answer": "开发商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开发商每天晚上在小区里巡逻。", "explanation": "这里应该用〈保安〉。巡逻守夜是保安的工作，开发商是盖房、卖房的企业或个人。"}, {"text": "开发商在饭店后厨炒了一盘菜。", "explanation": "这里应该用〈厨师〉。炒菜是厨师的工作，开发商是盖房、卖房的企业或个人。"}, {"text": "开发商给病人做了手术。", "explanation": "这里应该用〈医生〉。给病人做手术是医生的工作，开发商是盖房、卖房的企业或个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只开发商把小区的绿化做得很好。", "corrected_sentence": "这家开发商把小区的绿化做得很好。", "error_description": "量词错误。“开发商”指企业或个人，量词应用“家”，“只”多用于动物等，不能用于企业。正确形式为“这家开发商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两只开发商把合同签给了我们。", "corrected_sentence": "这两家开发商把合同签给了我们。", "error_description": "量词错误。“开发商”是企业，量词用“家”，“只”不能用于企业。正确形式为“这两家开发商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负债", "is_correct": true, "explanation": "反义：“资产”指拥有的资源，“负债”指应还的债务，二者是一对相对的会计概念。"}, {"text": "收入", "is_correct": false, "explanation": "无关：“收入”指一段时间内得到的钱，不是与“资产”相对的词。"}, {"text": "利润", "is_correct": false, "explanation": "无关：“利润”是收入减去成本后的余额，与“资产”不构成反义关系。"}, {"text": "成本", "is_correct": false, "explanation": "无关：“成本”指花费的钱，与“资产”不是反义关系。"}], "correct_answer": "负债", "explanations": {"负债": "反义：“资产”指拥有的资源，“负债”指应还的债务，二者是一对相对的会计概念。", "收入": "无关：“收入”指一段时间内得到的钱，不是与“资产”相对的词。", "利润": "无关：“利润”是收入减去成本后的余额，与“资产”不构成反义关系。", "成本": "无关：“成本”指花费的钱，与“资产”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负债", "is_correct": true, "explanation": "反义：“资产”指拥有的资源，“负债”指应还的债务，二者是一对相对的会计概念。"}, {"text": "利息", "is_correct": false, "explanation": "无关：“利息”是借贷的报酬，与“资产”不构成反义关系。"}, {"text": "薪水", "is_correct": false, "explanation": "无关：“薪水”是劳动所得，不是“资产”的反义词。"}, {"text": "费用", "is_correct": false, "explanation": "无关：“费用”指开支，与“资产”不构成反义关系。"}], "correct_answer": "负债", "explanations": {"负债": "反义：“资产”指拥有的资源，“负债”指应还的债务，二者是一对相对的会计概念。", "利息": "无关：“利息”是借贷的报酬，与“资产”不构成反义关系。", "薪水": "无关：“薪水”是劳动所得，不是“资产”的反义词。", "费用": "无关：“费用”指开支，与“资产”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指企业或个人拥有的具有经济价值的资源，如资金、设备、知识产权等。", "primary_collocate": null, "pronunciation": "zī chǎn", "ipa": "tsɹ̩˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "资产", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的资产超过十亿元。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大部分资产都投到了房地产上。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行要先看企业有多少资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司破产后，银行卖掉了剩下的资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子和汽车都是他个人的资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计每年都要算一次公司的资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人留下了不少资产给孩子们。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔资产是公司多年积累下来的。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的资产都写在年度报告里。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "固定资产", "label": "复合"}, {"form": "資產", "label": "繁体"}], "register": "正式", "sense_fingerprint": "资产：企业或个人拥有的具有经济价值的资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资产", "is_correct": true, "explanation": "正确。这里指可变现的资产，“提升资产流动性”说的是让拥有的资源更容易变现。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“流动性”用于资金、资产一类，不说“价格流动性”。"}, {"text": "效率", "is_correct": false, "explanation": "搭配：“提升……流动性”的宾语须是资金或资产，不说“效率流动性”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是经济资源，无法被“提升流动性”。"}], "explanations": {"资产": "正确。这里指可变现的资产，“提升资产流动性”说的是让拥有的资源更容易变现。", "价格": "搭配：“流动性”用于资金、资产一类，不说“价格流动性”。", "效率": "搭配：“提升……流动性”的宾语须是资金或资产，不说“效率流动性”。", "天气": "语义：天气不是经济资源，无法被“提升流动性”。"}, "sentence_index": 0, "correct_answer": "资产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的资产很高。", "explanation": "这里应该用〈收入〉。资产是某一时点拥有的财物总额，按月计算的数额要用“收入”。"}, {"text": "这次活动的资产是五千元。", "explanation": "这里应该用〈成本〉。资产指拥有的资源，活动花掉的钱要说“成本”。"}, {"text": "这笔贷款的资产是每年百分之五。", "explanation": "这里应该用〈利息〉。资产是财物的总额，按年率计算的数额要说“利息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资产", "is_correct": true, "explanation": "正确。会计要计算的是公司拥有的资产总额，“资产”与“算一次”搭配自然。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：会计计算的是数额，“公司的年龄”不是会计计算的对象，搭配不自然。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”指外观特征，会计不会去计算公司的颜色。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是会计计算的项目，“算一次公司的温度”无法成立。"}], "explanations": {"资产": "正确。会计要计算的是公司拥有的资产总额，“资产”与“算一次”搭配自然。", "年龄": "搭配：会计计算的是数额，“公司的年龄”不是会计计算的对象，搭配不自然。", "颜色": "体貌：“颜色”指外观特征，会计不会去计算公司的颜色。", "温度": "语义：温度不是会计计算的项目，“算一次公司的温度”无法成立。"}, "sentence_index": 6, "correct_answer": "资产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司欠银行的钱是资产。", "explanation": "这里应该用〈负债〉。欠别人的钱是负债，资产指拥有的财物，二者意思相反。"}, {"text": "我们要节约资产，保护环境。", "explanation": "这里应该用〈资源〉。保护环境要说“节约资源”，资产指拥有的财物，不能这样说。"}, {"text": "我们需要筹集资产来扩大生产。", "explanation": "这里应该用〈资金〉。扩大生产要筹集的是钱款，说“筹集资金”，资产指拥有的财物总额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有一只很大的资产。", "corrected_sentence": "这家公司有一笔很大的资产。", "error_description": "量词错误。“资产”的量词是“笔”，“只”不能用于资产。正确形式为“一笔很大的资产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几只资产都在银行里。", "corrected_sentence": "这几笔资产都在银行里。", "error_description": "量词错误。“资产”用“笔”计量，“只”不能用于资产。正确形式为“这几笔资产”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "资产能多快卖出并变成现金的程度", "primary_collocate": null, "pronunciation": "liú dòng xìng", "ipa": "ljou̯˧˥ tʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "投资者不再仅评估建筑面积与区位，而是将“绿色资本”的可及性纳入核心风险评估模型，推动开发商将生态基础设施视为提升资产流动性的关键杠杆。", "target_word": "流动性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "房子的流动性不如股票。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现金的流动性最高，随时可以使用。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行要保持足够的流动性，应对客户取款。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子地段偏，流动性很差，不容易卖出。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买基金前，要先看它的流动性好不好。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术品的流动性低，想卖掉往往要等很久。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股票随时能卖，所以流动性比较好。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者喜欢流动性高的资产，因为变现快。", "target_word": "流动性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只债券交易少，流动性不高。", "target_word": "流动性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "流動性", "label": "繁体"}, {"form": "流动性风险", "label": "复合"}], "register": "书面", "sense_fingerprint": "资产变现的快慢程度（金融术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c34999df-c2a8-41e6-84de-552383229488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”用于事物的外观，资产不能说颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与资产能否快速变现无关。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”指资产变现的快慢，提升它是关键杠杆，语境相合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能说资产的体重。"}], "explanations": {"颜色": "搭配：“颜色”用于事物的外观，资产不能说颜色。", "味道": "语义：“味道”指气味或滋味，与资产能否快速变现无关。", "流动性": "“流动性”指资产变现的快慢，提升它是关键杠杆，语境相合。", "体重": "搭配：“体重”只用于人或动物，不能说资产的体重。"}, "sentence_index": 0, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的流动性很重，两个人才搬得动。", "explanation": "这里应该用〈重量〉。流动性指资产变现的快慢，不能说“很重”；说画的轻重要用“重量”。"}, {"text": "这只基金的流动性很开心，去年赚了不少。", "explanation": "这里应该用〈业绩〉。流动性指资产变现的快慢，不能用“开心”来形容；说基金的表现要用“业绩”。"}, {"text": "这笔贷款的流动性很长，要三十年才能还清。", "explanation": "这里应该用〈期限〉。流动性指资产变现的快慢，说贷款的还款时间要用“期限”，不能用流动性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬度", "is_correct": false, "explanation": "语义：“硬度”指物体抵抗压力的程度，与能否快速卖出无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不能说艺术品的身高。"}, {"text": "流动性", "is_correct": true, "explanation": "“流动性”低指资产难以快速变现，所以想卖掉往往要等很久，语境相合。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只用于人或动物，艺术品没有体温。"}], "explanations": {"硬度": "语义：“硬度”指物体抵抗压力的程度，与能否快速卖出无关。", "身高": "搭配：“身高”只用于人，不能说艺术品的身高。", "流动性": "“流动性”低指资产难以快速变现，所以想卖掉往往要等很久，语境相合。", "体温": "搭配：“体温”只用于人或动物，艺术品没有体温。"}, "sentence_index": 6, "correct_answer": "流动性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只债券交易少，它的一块流动性不高。", "explanation": "这里不用“块”。“块”计量成块的物体，流动性是抽象名词，不能用“块”计量。"}, {"text": "这只债券交易少，它的一片流动性不高。", "explanation": "这里不用“片”。“片”计量扁平的东西，流动性是抽象名词，不能用“片”计量。"}, {"text": "这只债券交易少，它的一条流动性不高。", "explanation": "这里不用“条”。“条”计量细长的东西，流动性是抽象名词，不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只基金的流动性差很，想赎回要等很久。", "corrected_sentence": "这只基金的流动性很差，想赎回要等很久。", "error_description": "语序错误：程度副词“很”应放在形容词“差”前面，应说“流动性很差”，不能说“流动性差很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种资产流动性很高，所以很难卖出。", "corrected_sentence": "这种资产流动性很高，所以很容易卖出。", "error_description": "语义矛盾：流动性高指资产能很快变现，应说“很容易卖出”，不能说“很难卖出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
