INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12656, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种简单机械，在力的作用下能绕着固定点转动，用来撬动重物或传递力量。", "primary_collocate": null, "pronunciation": "gàng gǎn", "ipa": "kɑŋ˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "要撬动这块大石头，可以找一根结实的硬棒，把支点垫在石下，把它当作杠杆，只需很小的力就能把石头翘起来。", "target_word": "杠杆", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他用一根杠杆撬起了大石头。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杠杆能让人用小力气搬动重物。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了杠杆的原理。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用杠杆把重箱子抬了起来。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杠杆有一个固定点，叫支点。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根杠杆太短，撬不动大机器。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跷跷板就是一种简单的杠杆。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿基米德说，给我一根够长的杠杆和一个支点，我就能撬起地球。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想省力，就得把杠杆的一头做长。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "杠杆原理", "label": "复合"}, {"form": "槓桿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "杠杆：绕固定点转动、用来撬动重物的简单机械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杠杆", "is_correct": true, "explanation": "正确：“杠杆”指撬动重物的简单机械，把硬棒当杠杆、借支点用很小的力翘起石头，正是它的用法。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不能当作撬动大石头的硬棒。"}, {"text": "海绵", "is_correct": false, "explanation": "语义：海绵松软，不能当硬棒撬动大石头。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料用于上色，与撬动石头毫无关系。"}], "explanations": {"杠杆": "正确：“杠杆”指撬动重物的简单机械，把硬棒当杠杆、借支点用很小的力翘起石头，正是它的用法。", "水泥": "语义：水泥是建筑材料，不能当作撬动大石头的硬棒。", "海绵": "语义：海绵松软，不能当硬棒撬动大石头。", "颜料": "语义：颜料用于上色，与撬动石头毫无关系。"}, "sentence_index": 0, "correct_answer": "杠杆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他双手握住杠杆，做了十个引体向上。", "explanation": "这里应该用〈单杠〉。做引体向上的横杠叫单杠；杠杆是可以撬起重物的简单机械，不是健身器械。"}, {"text": "他把杠杆扛在肩上，挑起了两桶水。", "explanation": "这里应该用〈扁担〉。挑水要用扁担；杠杆是翘起重物的简单机械，不能拿来挑水。"}, {"text": "老爷爷拄着杠杆，慢慢地走出了院子。", "explanation": "这里应该用〈拐杖〉。拄着走路要用拐杖；杠杆是翘起重物的简单机械，不能用来拄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杠杆", "is_correct": true, "explanation": "正确：这里指撬动重物的硬棍，“太短、撬不动大机器”都与杠杆相符。"}, {"text": "香肠", "is_correct": false, "explanation": "搭配：“撬”的对象是石头、门这类物件，香肠不能用来撬大机器。"}, {"text": "葱", "is_correct": false, "explanation": "语义：葱是蔬菜，不是能撬动重物的硬棍，“太短、撬不动大机器”说不通。"}, {"text": "电线", "is_correct": false, "explanation": "体貌：电线柔软，不是硬棍，说不上“太短、撬不动”。"}], "explanations": {"杠杆": "正确：这里指撬动重物的硬棍，“太短、撬不动大机器”都与杠杆相符。", "香肠": "搭配：“撬”的对象是石头、门这类物件，香肠不能用来撬大机器。", "葱": "语义：葱是蔬菜，不是能撬动重物的硬棍，“太短、撬不动大机器”说不通。", "电线": "体貌：电线柔软，不是硬棍，说不上“太短、撬不动”。"}, "sentence_index": 6, "correct_answer": "杠杆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板绕着杠杆转动。", "explanation": "这里应该用〈支点〉。绕着转动的固定点叫支点；杠杆指整根硬棍，不能说木板绕着杠杆转。"}, {"text": "他把杠杆横在阳台上，用来晾衣服。", "explanation": "这里应该用〈晾衣杆〉。晾衣服要用晾衣杆；杠杆是翘起重物的简单机械，不能用来晾衣服。"}, {"text": "他扶着杠杆，慢慢走下楼梯。", "explanation": "这里应该用〈扶手〉。扶着楼梯走要用扶手；杠杆是翘起重物的硬棍，不是扶手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明用一只长杠杆把石头撬动了。", "corrected_sentence": "小明用一根长杠杆把石头撬动了。", "error_description": "量词错误：杠杆是长条形硬棍，应该用量词“根”，说“一根长杠杆”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人拿来一张杠杆，撬开了木箱。", "corrected_sentence": "工人拿来一根杠杆，撬开了木箱。", "error_description": "量词错误：杠杆是长条形的硬棍，量词用“根”，“张”用于纸、桌子等平面的东西。正确形式为“一根杠杆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指等级、水平等超过一般标准。", "primary_collocate": null, "pronunciation": "gāo jiē", "ipa": "kɑʊ̯˥ tɕje˥", "syllable_count": 2, "sentences": [{"text": "与此同时，垂直农场作为城市农业的高阶形态，正在重构粮食安全的时空逻辑。", "target_word": "高阶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "未来的发展或将超越“降解”范式，迈向“闭环循环”的高阶目标：即聚合物在完成使用使命后，不仅能被微生物完全矿化，其降解产物还可作为新聚合反应的绿色原料，实现碳元素的无限循环。", "target_word": "高阶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这门高阶课程适合有基础的学生。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的高阶技能让老师很满意。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言需要高阶思维。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完成基础练习后，可以学高阶内容。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有很多高阶玩法。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经是高阶玩家了。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为员工开设了高阶培训。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高阶班的作业比基础班难。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高階", "label": "繁体"}, {"form": "高阶思维", "label": "复合"}], "register": "书面", "sense_fingerprint": "等级或水平高于一般标准的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高阶", "is_correct": true, "explanation": "填入“高阶”：垂直农场是城市农业中等级更高的形态，与“高阶”的水平含义一致。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”描述物体能否透光，与农场形态的等级无关，句意不通。"}, {"text": "圆形", "is_correct": false, "explanation": "体貌：“圆形”描述外形，不能说明农业形态的等级水平。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：“湿润”形容水分状态，不能用来说明形态的高低档次。"}], "explanations": {"高阶": "填入“高阶”：垂直农场是城市农业中等级更高的形态，与“高阶”的水平含义一致。", "透明": "语义：“透明”描述物体能否透光，与农场形态的等级无关，句意不通。", "圆形": "体貌：“圆形”描述外形，不能说明农业形态的等级水平。", "湿润": "语义：“湿润”形容水分状态，不能用来说明形态的高低档次。"}, "sentence_index": 0, "correct_answer": "高阶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很高阶，动不动就发火。", "explanation": "这里应该用〈大〉。“高阶”指等级、水平超过一般标准，不用来形容脾气。"}, {"text": "这座山很高阶。", "explanation": "“高阶”指等级或水平，不用来描写山的高矮。"}, {"text": "这条裤子太高阶了，裤腿都拖到地上了。", "explanation": "这里应该用〈长〉。“高阶”指等级或水平，不能用来描述裤子的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高阶", "is_correct": true, "explanation": "填入“高阶”：游戏中的高阶玩法指难度与水平更高的玩法，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来说明玩法的水平。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能修饰“玩法”。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人的状态，与玩法的水平无关。"}], "explanations": {"高阶": "填入“高阶”：游戏中的高阶玩法指难度与水平更高的玩法，符合句意。", "寒冷": "语义：“寒冷”形容温度，不能用来说明玩法的水平。", "咸": "搭配：“咸”形容味道，不能修饰“玩法”。", "沉默": "语义：“沉默”形容人的状态，与玩法的水平无关。"}, "sentence_index": 6, "correct_answer": "高阶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他长得很高阶。", "explanation": "“高阶”指等级或水平，不用于形容人的身高。"}, {"text": "他说话的声音很高阶，隔壁都能听见。", "explanation": "这里应该用〈高〉。“高阶”指等级或水平，不用来描述声音的高低。"}, {"text": "这座楼的天花板很高阶。", "explanation": "“高阶”不用于描写物体的高矮，天花板的高低不能用它来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课程很高阶地。", "corrected_sentence": "这门课程很高阶。", "error_description": "错误：“很高阶地”；正确：“很高阶”。“高阶”作谓语描述状态时后面不加“地”，“地”只用于修饰后面的动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有几个很高阶玩家。", "corrected_sentence": "我们班有几个高阶玩家。", "error_description": "错误：“很高阶玩家”；正确：“高阶玩家”。“高阶”直接修饰名词时不加“很”；如果要加“很”，必须说“很高阶的玩家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
