INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间和空间的结合，指事物存在和变化的维度框架", "primary_collocate": null, "pronunciation": "shí kōng", "ipa": "ʂɨ˧˥ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "与此同时，垂直农场作为城市农业的高阶形态，正在重构粮食安全的时空逻辑。", "target_word": "时空", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "物理学家用四维时空来描述宇宙。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个时空里，事件有先后和位置。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究黑洞，需要理解时空的结构。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的观察者，看到的时空并不一样。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图和时钟帮我们在时空中找到位置。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型把时间和地点放进同一个时空。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科幻小说常常设想时空可以弯曲。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时空的变化会影响光的走向。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师画了一张时空坐标图。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "时空观", "label": "复合"}], "register": "书面", "sense_fingerprint": "时间与空间合成的框架，事物在其中存在和变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12658, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：时空 shí kōng，指时间和空间的结合。"}, {"text": "失控", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，kòng（第四声）与 kōng（第一声）声调不同，意思是失去控制。"}, {"text": "时钟", "is_correct": false, "explanation": "zhōng 与 kōng 只有声母不同（zh 与 k），意思是计时的钟表。"}, {"text": "石工", "is_correct": false, "explanation": "gōng 与 kōng 只有声母不同（g 与 k），意思是石匠。"}, {"text": "实控", "is_correct": false, "explanation": "kòng（第四声）与 kōng（第一声）声调不同，意思是实际控制。"}], "explanations": {"时空": "正确：时空 shí kōng，指时间和空间的结合。", "失控": "shī（第一声）与 shí（第二声）声调不同，kòng（第四声）与 kōng（第一声）声调不同，意思是失去控制。", "时钟": "zhōng 与 kōng 只有声母不同（zh 与 k），意思是计时的钟表。", "石工": "gōng 与 kōng 只有声母不同（g 与 k），意思是石匠。", "实控": "kòng（第四声）与 kōng（第一声）声调不同，意思是实际控制。"}, "sentence_index": null, "correct_answer": "时空"}, "level_3": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：“时空逻辑”指粮食安全所处的时间与空间框架，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与粮食安全的推理无关，“颜色逻辑”说不通。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压属于电学概念，与农业中的粮食安全无关。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“逻辑”指推理或系统，不能与“音量”组合。"}], "explanations": {"时空": "正确：“时空逻辑”指粮食安全所处的时间与空间框架，符合语境。", "颜色": "语义：颜色与粮食安全的推理无关，“颜色逻辑”说不通。", "电压": "语义：电压属于电学概念，与农业中的粮食安全无关。", "音量": "搭配：“逻辑”指推理或系统，不能与“音量”组合。"}, "sentence_index": 0, "correct_answer": "时空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的时空很大，放得下很多家具。", "explanation": "这里应该用〈空间〉。时空指时间与空间结合的框架，不用来说房间的大小。"}, {"text": "这个电池的时空很长，能用一整天。", "explanation": "这里应该用〈时长〉。时空指时间与空间结合的框架，不能用来表示持续多久。"}, {"text": "我每天花两个小时的时空做作业。", "explanation": "这里应该用〈时间〉。时空指时间与空间结合的框架，不能表示做事用了多久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：“同一个时空”指时间和地点共同所在的框架，符合语境。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不能装下时间和地点，“放进同一个数字”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉对象，不能作为容器接受时间和地点。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“同一个食物”无法与“放进时间和地点”搭配。"}], "explanations": {"时空": "正确：“同一个时空”指时间和地点共同所在的框架，符合语境。", "数字": "语义：数字不能装下时间和地点，“放进同一个数字”说不通。", "声音": "语义：声音是听觉对象，不能作为容器接受时间和地点。", "食物": "搭配：“同一个食物”无法与“放进时间和地点”搭配。"}, "sentence_index": 6, "correct_answer": "时空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一天的时空过得很快，我们都很开心。", "explanation": "这里应该用〈时间〉。时空是时间与空间结合的框架，“过得快”只用于时间。"}, {"text": "他选的时空很安静，适合学习。", "explanation": "这里应该用〈地点〉。时空指时间与空间的框架，不能用来指具体的位置。"}, {"text": "妈妈给我留了一点时空吃早饭。", "explanation": "这里应该用〈时间〉。时空是时间与空间的框架，不能指一段可用的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间的时空很大，可以放三张床。", "corrected_sentence": "这个房间的空间很大，可以放三张床。", "error_description": "用词错误：说房间大小应用“空间”，“时空”指时间与空间结合的框架。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个理论描述了一张弯曲的时空。", "corrected_sentence": "这个理论描述了一个弯曲的时空。", "error_description": "量词错误：“时空”是抽象概念，应用量词“个”，不能说“一张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
