INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示事物数量的概念。", "primary_collocate": null, "pronunciation": "shù", "ipa": "ʂu⁵¹", "syllable_count": 1, "sentences": [{"text": "数可以告诉我们东西有多少。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子先学会认数，再学加法。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数是用来表示多少的。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一、二、三都是数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数比十大，比二十小。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写一个比五大的数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有数的概念，我们就没法算钱。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数太大了，我读不出来。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数越大，表示的东西就越多。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数", "label": "量词"}, {"form": "數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示事物数量的概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数", "is_correct": true, "explanation": "表示事物数量的概念。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书。"}, {"text": "素", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是素、朴素。"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是暑热。"}], "explanations": {"数": "表示事物数量的概念。", "书": "shū（第一声）与 shù（第四声）声调不同，意思是书。", "素": "sù 与 shù 声母不同（s 与 sh），意思是素、朴素。", "暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是暑热。"}, "sentence_index": null, "correct_answer": "数"}, "level_3": {"options": [{"text": "数", "is_correct": true, "explanation": "数：表示事物数量的概念，可以告诉我们有多少。"}, {"text": "字", "is_correct": false, "explanation": "语义：字不是表示数量的概念，不能告诉我们东西有多少。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有多少”说的是可以计数的东西，颜色不能这样计数。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言不表示多少，不能告诉我们东西的数量。"}], "explanations": {"数": "数：表示事物数量的概念，可以告诉我们有多少。", "字": "语义：字不是表示数量的概念，不能告诉我们东西有多少。", "颜色": "搭配：“有多少”说的是可以计数的东西，颜色不能这样计数。", "语言": "语义：语言不表示多少，不能告诉我们东西的数量。"}, "sentence_index": 0, "correct_answer": "数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的数很开朗。", "explanation": "这里应该用〈同学〉。“开朗”形容人的性格，“数”指抽象的数量概念，不能用来形容班里的人。"}, {"text": "他这次考试的数很高。", "explanation": "这里应该用〈分数〉。“高”形容分数，“数”指抽象的数量概念，不能说考试的数高。"}, {"text": "他跑步的数很多。", "explanation": "这里应该用〈次数〉。“很多”形容次数，“数”指抽象的数量概念，不能用来说跑了多少次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "数", "is_correct": true, "explanation": "表示事物数量的概念。"}, {"text": "诉", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是告诉、诉说。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是薯类。"}], "explanations": {"数": "表示事物数量的概念。", "诉": "sù 与 shù 声母不同（s 与 sh），意思是告诉、诉说。", "叔": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。", "薯": "shǔ（第三声）与 shù（第四声）声调不同，意思是薯类。"}, "sentence_index": null, "correct_answer": "数"}, "level_3": {"options": [{"text": "数", "is_correct": true, "explanation": "数：表示事物数量的概念，没有它就没法计算钱。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐与计算钱没有关系，“没有音乐的概念”无法支撑后面的算钱。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“概念”一般不跟“影子”搭配，句中也不表示数量。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离是长短的概念，不能用来计算钱。"}], "explanations": {"数": "数：表示事物数量的概念，没有它就没法计算钱。", "音乐": "语义：音乐与计算钱没有关系，“没有音乐的概念”无法支撑后面的算钱。", "影子": "搭配：“概念”一般不跟“影子”搭配，句中也不表示数量。", "距离": "语义：距离是长短的概念，不能用来计算钱。"}, "sentence_index": 6, "correct_answer": "数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的数很合适。", "explanation": "这里应该用〈尺寸〉。“合适”说衣服的大小，“数”是抽象的数量概念，不能指尺寸。"}, {"text": "他忘记了手机的数。", "explanation": "这里应该用〈号码〉。手机号码是用来拨打的编号，“数”表示数量的概念，不能指号码。"}, {"text": "这个仓库的货物数很重。", "explanation": "这里应该用〈重量〉。说货物有多重要用重量，“数”是抽象的数量概念，不能指重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只数相加得到的是和。", "corrected_sentence": "两个数相加，得到的是和。", "error_description": "量词错误：“数”应该用“个”计数，“只”用于动物等，不能用来数数字。正确说法是“两个数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在黑板上写了三只数，让我们加起来。", "corrected_sentence": "老师在黑板上写了三个数，让我们加起来。", "error_description": "量词错误：“数”用“个”计数，“只”多用于动物，不能用来数数。正确说法是“三个数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
