INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体具有长、宽、高三个维度，不是平面的。", "primary_collocate": null, "pronunciation": "lì tǐ", "ipa": "li⁵¹ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这张立体地图很清楚。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢看立体书。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个立体停车场能停五百辆车。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸做了一个立体的房子。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是立体的，可以拿在手上转。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块积木是立体的，不是平的。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球是立体的，圆是平面的。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "立体的图形有长、宽、高。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里有立体交通，比如高架桥。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "立体图形", "label": "复合"}, {"form": "立體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有长宽高三个维度，不是平面的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。立体（lì tǐ）指物体有长、宽、高三个维度，不是平面的。"}, {"text": "例题", "is_correct": false, "explanation": "例题（lì tí）与立体（lì tǐ）第二个音节声调不同（tí 与 tǐ），意思是例子或习题。"}, {"text": "离题", "is_correct": false, "explanation": "离题（lí tí）与立体（lì tǐ）两个音节声调都不同，意思是偏离主题。"}, {"text": "离体", "is_correct": false, "explanation": "离体（lí tǐ）与立体（lì tǐ）第一个音节声调不同（lí 与 lì），意思是离开身体。"}], "explanations": {"立体": "正确。立体（lì tǐ）指物体有长、宽、高三个维度，不是平面的。", "例题": "例题（lì tí）与立体（lì tǐ）第二个音节声调不同（tí 与 tǐ），意思是例子或习题。", "离题": "离题（lí tí）与立体（lì tǐ）两个音节声调都不同，意思是偏离主题。", "离体": "离体（lí tǐ）与立体（lì tǐ）第一个音节声调不同（lí 与 lì），意思是离开身体。"}, "sentence_index": null, "correct_answer": "立体"}, "level_3": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。“立体空间”指有长、宽、高的三维空间，与“多层水培”相合。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”指地面平整没有起伏，与“多层”栽培相矛盾。"}, {"text": "单薄", "is_correct": false, "explanation": "搭配：“单薄”多形容纸张、身体等薄弱，不用来修饰“空间”。"}, {"text": "狭小", "is_correct": false, "explanation": "语义：“狭小”与“数万平方米”的规模相矛盾。"}], "explanations": {"立体": "正确。“立体空间”指有长、宽、高的三维空间，与“多层水培”相合。", "平坦": "语义：“平坦”指地面平整没有起伏，与“多层”栽培相矛盾。", "单薄": "搭配：“单薄”多形容纸张、身体等薄弱，不用来修饰“空间”。", "狭小": "语义：“狭小”与“数万平方米”的规模相矛盾。"}, "sentence_index": 0, "correct_answer": "立体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的立体很大。", "explanation": "这里应该用〈空间〉。房间的大小要说空间，立体指有长、宽、高的形状，不指房间的容积。"}, {"text": "这张桌面的立体很平。", "explanation": "这里应该用〈平整〉。桌面平不平要用平整来说；立体指有长、宽、高的三维形状。"}, {"text": "这栋楼的立体有三十米。", "explanation": "这里应该用〈高度〉。楼有多高要说高度，立体指有长、宽、高的形状，不指高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。立体的积木有长、宽、高，与“不是平的”前后呼应。"}, {"text": "平整", "is_correct": false, "explanation": "语义：“平整”与“不是平的”直接矛盾。"}, {"text": "扁平", "is_correct": false, "explanation": "语义：“扁平”描述外形薄而平，与“不是平的”相矛盾。"}, {"text": "平面", "is_correct": false, "explanation": "语义：“平面”与“不是平的”直接矛盾，句子无法成立。"}], "explanations": {"立体": "正确。立体的积木有长、宽、高，与“不是平的”前后呼应。", "平整": "语义：“平整”与“不是平的”直接矛盾。", "扁平": "语义：“扁平”描述外形薄而平，与“不是平的”相矛盾。", "平面": "语义：“平面”与“不是平的”直接矛盾，句子无法成立。"}, "sentence_index": 6, "correct_answer": "立体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面镜子的立体很光滑。", "explanation": "这里应该用〈表面〉。说镜子光不光滑要说表面；立体指有长、宽、高的形状。"}, {"text": "这片草原的立体很平坦。", "explanation": "这里应该用〈地势〉。草原平不平坦要说地势；立体用于有长、宽、高的物体。"}, {"text": "这个房间打扫得很立体。", "explanation": "这里应该用〈干净〉。房间干不干净要说干净，立体指有长、宽、高的物体，不指清洁程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的插图是立体地，翻开会跳出来。", "corrected_sentence": "这本书的插图是立体的，翻开会跳出来。", "error_description": "错误：“立体”作谓语时后面要用“的”，不能用“地”。正确形式：是立体的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画的人物画的很立体。", "corrected_sentence": "这幅画的人物画得很立体。", "error_description": "错误：表示程度补语要用结构助词“得”，不用“的”。正确形式：画得很立体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
