INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以种植农作物的土地，如农田。", "primary_collocate": null, "pronunciation": "gēng dì", "ipa": "kɤŋ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "耕地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个村子的耕地越来越少了。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村有一百亩耕地。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每年春天都在耕地里种玉米。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片耕地的土很黑，很适合种小麦。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要保护好每一块耕地。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的耕地离河不远。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子占了不少耕地。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了大雨，耕地里都是水。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的耕地面积很大。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "耕地面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "可种庄稼的土地，农田", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "耕地", "is_correct": true, "explanation": "正确。耕地（gēng dì）指可以种庄稼的土地。"}, {"text": "更替", "is_correct": false, "explanation": "更替（gēng tì）与耕地（gēng dì）第二个音节声母不同（t 与 d），意思是新旧交替。"}, {"text": "工地", "is_correct": false, "explanation": "工地（gōng dì）与耕地（gēng dì）第一个音节韵母不同（ong 与 eng），意思是施工的场地。"}, {"text": "更低", "is_correct": false, "explanation": "更低（gèng dī）与耕地（gēng dì）两个音节声调都不同，意思是比较低。"}], "explanations": {"耕地": "正确。耕地（gēng dì）指可以种庄稼的土地。", "更替": "更替（gēng tì）与耕地（gēng dì）第二个音节声母不同（t 与 d），意思是新旧交替。", "工地": "工地（gōng dì）与耕地（gēng dì）第一个音节韵母不同（ong 与 eng），意思是施工的场地。", "更低": "更低（gèng dī）与耕地（gēng dì）两个音节声调都不同，意思是比较低。"}, "sentence_index": null, "correct_answer": "耕地"}, "level_3": {"options": [{"text": "耕地", "is_correct": true, "explanation": "正确。“传统耕地”指用来种庄稼的土地，与“产出效率”相合。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“河流”不能与“数百公顷的产出效率”搭配，说不通。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场不种庄稼，不能产出农作物。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库用来存放粮食，本身不产出作物，与“产出效率”的意思不符。"}], "explanations": {"耕地": "正确。“传统耕地”指用来种庄稼的土地，与“产出效率”相合。", "河流": "搭配：“河流”不能与“数百公顷的产出效率”搭配，说不通。", "停车场": "语义：停车场不种庄稼，不能产出农作物。", "仓库": "语义：仓库用来存放粮食，本身不产出作物，与“产出效率”的意思不符。"}, "sentence_index": 0, "correct_answer": "耕地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的耕地都是树。", "explanation": "这里应该用〈林地〉。山上种满树的地要说林地，耕地是用来种庄稼的土地。"}, {"text": "村口的耕地很安静，埋着很多人。", "explanation": "这里应该用〈墓地〉。埋葬死者的地方要说墓地，耕地是用来种农作物的土地。"}, {"text": "这片耕地是学校的操场，孩子们在上面跑步。", "explanation": "这里应该用〈操场〉。学校里跑步的场地要说操场，耕地是用来种农作物的，不能当操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耕地", "is_correct": true, "explanation": "正确。“他家的耕地”是可种庄稼的土地，能够“离河不远”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“离河不远”，搭配不当。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，没有远近之分，不能与河的距离相合。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”不用来说离河远近，搭配不当。"}], "explanations": {"耕地": "正确。“他家的耕地”是可种庄稼的土地，能够“离河不远”。", "天气": "搭配：“天气”不能说“离河不远”，搭配不当。", "时间": "语义：时间是抽象概念，没有远近之分，不能与河的距离相合。", "人口": "搭配：“人口”不用来说离河远近，搭配不当。"}, "sentence_index": 6, "correct_answer": "耕地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在耕地上踢足球，一下课就去。", "explanation": "这里应该用〈操场〉。踢球的场地是操场，耕地是种庄稼的土地。"}, {"text": "工人们在耕地上盖大楼，每天都很忙。", "explanation": "这里应该用〈工地〉。正在盖楼的地方是工地，耕地是用来种农作物的。"}, {"text": "牛羊在耕地上吃草，一片绿油油的。", "explanation": "这里应该用〈草地〉。放牛羊吃草的地方是草地或牧场，耕地是种庄稼的土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只耕地今年种了小麦。", "corrected_sentence": "这块耕地今年种了小麦。", "error_description": "错误：耕地（土地）的量词用“块”，不用“只”（“只”多用于动物）。正确形式：这块耕地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们家今年多了三十只耕地。", "corrected_sentence": "他们家今年多了三十亩耕地。", "error_description": "量词错误：耕地用“亩”“块”“片”计量，不用“只”（“只”多用于动物）。正确形式：三十亩耕地。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
