INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12667, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12667, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "指连续不断，中间没有停顿或间隔。", "primary_collocate": null, "pronunciation": "wú jiàn duàn", "ipa": "u˧˥ tɕjɛn˥˩ tuan˥˩", "syllable_count": 3, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "无间断", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂的机器无间断地运转了三天。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生无间断地工作了二十个小时。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店全年无间断营业。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水无间断地流向大海。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨无间断地下了一整天。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无间断地练习了一个月钢琴，一天也没停过。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的灯无间断亮着。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区无间断供应热水。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小时里，她无间断地跟我说话。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无间断地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "连续不断，中间无停顿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无间断", "is_correct": true, "explanation": "正确：“无间断”表示连续不断，与“全年供应”的意思一致。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指间或出现，与“全年供应”的持续性相矛盾。"}, {"text": "一度", "is_correct": false, "explanation": "体貌：“一度”指曾经发生过一次，不能表示全年持续供应。"}, {"text": "时而", "is_correct": false, "explanation": "搭配：“时而”要求动作交替出现，不能修饰“供应”这种持续性的行为。"}], "explanations": {"无间断": "正确：“无间断”表示连续不断，与“全年供应”的意思一致。", "偶尔": "语义：“偶尔”指间或出现，与“全年供应”的持续性相矛盾。", "一度": "体貌：“一度”指曾经发生过一次，不能表示全年持续供应。", "时而": "搭配：“时而”要求动作交替出现，不能修饰“供应”这种持续性的行为。"}, "sentence_index": 0, "correct_answer": "无间断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无间断地同意了我的建议。", "explanation": "这里误把〈无间断〉当成〈不拖延〉来用。“无间断”只说时间上不停顿，并不表示马上、不拖延；“同意”是一次完成的动作，不能持续进行。"}, {"text": "这颗鸡蛋无间断地碎了。", "explanation": "这里误把〈无间断〉当成〈完全〉来用。“无间断”说的是时间上不停顿，并不表示彻底；“碎”是瞬间完成的变化，不能持续进行。"}, {"text": "他无间断地结了婚。", "explanation": "这里误把〈无间断〉当成〈长久〉来用。“无间断”强调中间没有停顿，并不表示长期存在；“结婚”是一次完成的事件，不存在持续过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无间断", "is_correct": true, "explanation": "正确：“无间断”表示练习中间没有停顿，与“练习了一个月”的持续意思相符。"}, {"text": "间或", "is_correct": false, "explanation": "语义：“间或”指偶尔出现，与“练习了一个月”的连续进行相矛盾。"}, {"text": "不时", "is_correct": false, "explanation": "语义：“不时”指隔一段时间就发生一次，与持续练习的意思不符。"}, {"text": "时常", "is_correct": false, "explanation": "体貌：“时常”表示经常性、习惯性的重复，与“练习了一个月”的一个完整时段不合。"}], "explanations": {"无间断": "正确：“无间断”表示练习中间没有停顿，与“练习了一个月”的持续意思相符。", "间或": "语义：“间或”指偶尔出现，与“练习了一个月”的连续进行相矛盾。", "不时": "语义：“不时”指隔一段时间就发生一次，与持续练习的意思不符。", "时常": "体貌：“时常”表示经常性、习惯性的重复，与“练习了一个月”的一个完整时段不合。"}, "sentence_index": 6, "correct_answer": "无间断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两块木板无间断地拼在一起。", "explanation": "这里应该用〈无间隙〉。“无间断”只说时间上的连续，描写木板之间没有缝隙要用“无间隙”，二者不能互换。"}, {"text": "这个班无间断地有三十个学生。", "explanation": "这里误把〈无间断〉当成〈总数〉来用。“无间断”只表示时间上的连续，不能用来说明人数。"}, {"text": "他每隔一小时无间断地吃一次药。", "explanation": "这里误把〈无间断〉当成〈定时〉来用。“定时”指按固定间隔进行，恰恰有间隔；“无间断”不允许中间有间隔，二者互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈无间断了地说着话。", "corrected_sentence": "妈妈无间断地说着话。", "error_description": "“无间断”是状态副词，后面不能直接加“了”。应说“无间断地说着话”，“地”要保留，“了”不能加在它后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器无间断得运转了一周。", "corrected_sentence": "这台机器无间断地运转了一周。", "error_description": "错误：“无间断”修饰动词作状语，后面应接“地”，不能用“得”（“得”用于动词或形容词后引出补语）。正确形式：这台机器无间断地运转了一周。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
