INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在医学上用于预防、治疗疾病或具有保健作用的植物。", "primary_collocate": null, "pronunciation": "yào yòng zhí wù", "ipa": "jɑʊ˥˩ jʊŋ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "通过多层水培、气雾栽培与人工智能环境调控技术，这类设施可在数万平方米的立体空间内实现相当于传统耕地数百公顷的产出效率，且全年无间断供应新鲜叶菜与药用植物。", "target_word": "药用植物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座山上有很多药用植物，比如人参和金银花。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种药用植物可以治咳嗽。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里种了一些药用植物。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药用植物能帮助人们预防和治疗疾病。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们跟着老师去山里认识药用植物。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家药店卖的不是药，而是新鲜的药用植物。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有几千年使用药用植物的历史。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林里的药用植物受到了保护。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常把药用植物的根做成茶。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种药用植物", "label": "量词"}, {"form": "藥用植物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用于预防、治疗疾病或保健的植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "药用植物", "is_correct": true, "explanation": "正确。“供应”的对象是植物类产品，与“新鲜叶菜”并列，符合设施栽培的语境。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油不是植物，也不是能保持新鲜的农产品，与“新鲜叶菜”并列不合理。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石是无机矿物，与前文的叶菜和设施栽培毫无关联。"}, {"text": "大棚", "is_correct": false, "explanation": "搭配：“供应”的对象应是可出售的产品，不说供应“大棚”；且前文已有“设施”，语义重复。"}], "explanations": {"药用植物": "正确。“供应”的对象是植物类产品，与“新鲜叶菜”并列，符合设施栽培的语境。", "石油": "语义：石油不是植物，也不是能保持新鲜的农产品，与“新鲜叶菜”并列不合理。", "矿石": "语义：矿石是无机矿物，与前文的叶菜和设施栽培毫无关联。", "大棚": "搭配：“供应”的对象应是可出售的产品，不说供应“大棚”；且前文已有“设施”，语义重复。"}, "sentence_index": 0, "correct_answer": "药用植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本药用植物写得很好，我看了三遍。", "explanation": "这里应该用〈书〉。药用植物是长在地里的植物，不能“写”，也不能用“本”来数，说的是一本书。"}, {"text": "我在花园里种了一只药用植物。", "explanation": "这里应该用〈株〉。“只”用于动物，植物一般用“株”，不能用“只”来数药用植物。"}, {"text": "这家工厂每天生产几万瓶药用植物。", "explanation": "这里应该用〈药水〉。药用植物是长在土里的植物，不能像药水那样批量灌装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "药用植物", "is_correct": true, "explanation": "正确。与前半句“不是药”形成对比，指可以用于防病治病的植物。"}, {"text": "药丸", "is_correct": false, "explanation": "语义：“药丸”本身就是药，与前半句“不是药”矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“新鲜”多用于食物和花草，一般不说“新鲜的玩具”。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是无机材料，不是可以“新鲜”出售的植物或食物。"}], "explanations": {"药用植物": "正确。与前半句“不是药”形成对比，指可以用于防病治病的植物。", "药丸": "语义：“药丸”本身就是药，与前半句“不是药”矛盾。", "玩具": "搭配：“新鲜”多用于食物和花草，一般不说“新鲜的玩具”。", "玻璃": "语义：玻璃是无机材料，不是可以“新鲜”出售的植物或食物。"}, "sentence_index": 6, "correct_answer": "药用植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他开了一副药用植物。", "explanation": "这里应该用〈中药〉。“副”用于中药方剂，药用植物是植物本身，不能像中药那样开成一副。"}, {"text": "我买了一条药用植物。", "explanation": "这里应该用〈株〉。“条”用于细长的东西，植物应该用“株”。"}, {"text": "他感冒了，打了一针药用植物。", "explanation": "这里应该用〈针剂〉。药用植物是植物，不能注射到身体里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上养着一只药用植物。", "corrected_sentence": "我家阳台上养着一株药用植物。", "error_description": "量词错误：“药用植物”是植物，应该用“株”。“只”用于动物，不能用来数植物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山上采了一本药用植物。", "corrected_sentence": "他在山上采了一株药用植物。", "error_description": "量词错误：“本”用于书册，不能用来数植物，植物应该用“株”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
