INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指物品因使用、时间或自然原因而减少或失去原有价值。", "primary_collocate": null, "pronunciation": "sǔn hào", "ipa": "suən˨˩˦ xɑu˥˩", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "其区位临近消费终端的特性，极大压缩了物流损耗与碳足迹，形成对脆弱全球供应链的韧性替代。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "机器用久了，零件会有损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑的电池损耗很大。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运输时，水果会有一些损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法减少水管的损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎用了三年，损耗已经很明显。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月都会计算仓库的损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服经常洗，也会有自然损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料很结实，损耗比较小。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然损耗", "label": "复合"}, {"form": "损耗率", "label": "复合"}], "register": "中性", "sense_fingerprint": "物品因使用或时间而减少、失去价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：蒸发减少的是水分，“温度”不会因蒸发而被“减少”。"}, {"text": "损耗", "is_correct": true, "explanation": "正确。“减少了蒸发损耗”指蒸发造成的水分流失，符合这段语境。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“减少”一般不与“宣传”搭配，“蒸发宣传”也说不通。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“蒸发”造成的是水分减少，不能说减少“节奏”。"}], "explanations": {"温度": "语义：蒸发减少的是水分，“温度”不会因蒸发而被“减少”。", "损耗": "正确。“减少了蒸发损耗”指蒸发造成的水分流失，符合这段语境。", "宣传": "搭配：“减少”一般不与“宣传”搭配，“蒸发宣传”也说不通。", "节奏": "搭配：“蒸发”造成的是水分减少，不能说减少“节奏”。"}, "sentence_index": 0, "correct_answer": "损耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事让他损耗了面子。", "explanation": "这里应该用〈丢〉。损耗指物品因使用或时间而减少，“面子”不是会被消耗的物品，应说丢了面子。"}, {"text": "这次事故损耗了他的右腿。", "explanation": "这里应该用〈损伤〉。损耗指物品因使用、时间慢慢减少，身体部位在事故中受伤要说损伤。"}, {"text": "这场地震损耗了整座大楼。", "explanation": "这里应该用〈损坏〉。损耗指东西慢慢变少或变坏，地震造成的突然破坏要说损坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "语义：轮胎用了三年不会产生需要“明显”的香味，这里指的是磨损。"}, {"text": "损耗", "is_correct": true, "explanation": "正确。“损耗已经很明显”指轮胎因使用而磨损，符合语境。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”需要有生命的主体，“轮胎”不能有脾气。"}, {"text": "名气", "is_correct": false, "explanation": "语义：“名气”与轮胎的使用年限无关，不能说“已经很明显”。"}], "explanations": {"香味": "语义：轮胎用了三年不会产生需要“明显”的香味，这里指的是磨损。", "损耗": "正确。“损耗已经很明显”指轮胎因使用而磨损，符合语境。", "脾气": "配价：“脾气”需要有生命的主体，“轮胎”不能有脾气。", "名气": "语义：“名气”与轮胎的使用年限无关，不能说“已经很明显”。"}, "sentence_index": 6, "correct_answer": "损耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为迟到损耗了一次好机会。", "explanation": "这里应该用〈错过〉。损耗指物品因使用而减少，机会没抓住要说错过。"}, {"text": "他的意志在生活的磨难中被损耗得更坚强。", "explanation": "这里应该用〈磨练〉。损耗指东西因使用而减少或变坏，意志在磨难中变得坚强要说磨练，不能说损耗。"}, {"text": "那位老人损耗得很厉害，走路都困难。", "explanation": "这里应该用〈衰老〉。损耗用于物品因使用而减少，不能用来形容人的身体变老。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里有一只不小的损耗，需要查清原因。", "corrected_sentence": "仓库里有一笔不小的损耗，需要查清原因。", "error_description": "量词错误：“损耗”作为数量应说“一笔”，不能说“一只”。“只”用于动物或单个物品，改为“一笔”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批机器用了十年，损耗的很厉害。", "corrected_sentence": "这批机器用了十年，损耗很厉害。", "error_description": "多余的“的”：“损耗”作主语，后面直接接“很厉害”，不加“的”，应去掉“的”，写作“损耗很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
