INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主粮指一个国家或地区人们日常饮食中最主要、消费量最大的粮食作物，如水稻、小麦等。", "primary_collocate": null, "pronunciation": "zhǔ liáng", "ipa": "ʈʂu˨˩˦ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当极端气候频发导致主粮产区波动时，分布式的城市食品生产网络展现出显著的风险对冲能力，使地方政府将此类项目纳入关键基础设施的应急规划范畴。", "target_word": "主粮", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在中国南方，大米是人们的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人常把小麦做成面条和馒头，小麦是主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水稻和小麦是中国最重要的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视主粮的生产，不让农民少种粮食。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米在有些地方也是人们每天吃的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆不是我们的主粮，我们一般当菜吃。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年下雨多，主粮的价格没有变化。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲有些国家把木薯当作主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，以前农村人的主粮是玉米面。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主粮产区", "label": "复合"}, {"form": "主糧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一国或一地区日常饮食中最主要的粮食作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。“主粮产区”指粮食作物的产区，填入“主粮”后与“产区”搭配，句意通顺。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“城市产区”不成立，产区指集中生产某种产品的地区，城市不是可以集中生产的产品。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被生产成一个产区，与句中“食品生产网络”的语境相冲突。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁产区”不能成立，地铁是交通设施，不是可以集中生产的产品。"}], "explanations": {"主粮": "正确。“主粮产区”指粮食作物的产区，填入“主粮”后与“产区”搭配，句意通顺。", "城市": "搭配：“城市产区”不成立，产区指集中生产某种产品的地区，城市不是可以集中生产的产品。", "空气": "语义：空气不能被生产成一个产区，与句中“食品生产网络”的语境相冲突。", "地铁": "搭配：“地铁产区”不能成立，地铁是交通设施，不是可以集中生产的产品。"}, "sentence_index": 0, "correct_answer": "主粮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的主粮是房地产和物流。", "explanation": "这里应该用〈主营〉。主粮只指水稻、小麦等粮食作物，说公司的主要业务要用主营，不能用主粮。"}, {"text": "我们村今年种的主粮是棉花和甘蔗。", "explanation": "这里应该用〈经济作物〉。棉花、甘蔗属于经济作物，主粮专指水稻、小麦等口粮作物，不能用来指它们。"}, {"text": "我最喜欢的主粮是炸鸡。", "explanation": "这里应该用〈食物〉。炸鸡是食物，但不是粮食作物，不能说成主粮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。“不是我们的主粮，我们一般当菜吃”形成对照，符合句意。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“不是蔬菜”与后半句“当菜吃”自相矛盾。"}, {"text": "菜肴", "is_correct": false, "explanation": "语义：“不是菜肴”与后半句“当菜吃”自相矛盾。"}, {"text": "菜", "is_correct": false, "explanation": "语义：“不是菜”与后半句“当菜吃”自相矛盾。"}], "explanations": {"主粮": "正确。“不是我们的主粮，我们一般当菜吃”形成对照，符合句意。", "蔬菜": "语义：“不是蔬菜”与后半句“当菜吃”自相矛盾。", "菜肴": "语义：“不是菜肴”与后半句“当菜吃”自相矛盾。", "菜": "语义：“不是菜”与后半句“当菜吃”自相矛盾。"}, "sentence_index": 6, "correct_answer": "主粮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天喝的主粮是牛奶。", "explanation": "这里应该用〈饮料〉。牛奶是饮品，主粮指水稻、小麦等粮食作物，不能用来喝。"}, {"text": "这道菜的主粮是盐和酱油。", "explanation": "这里应该用〈调料〉。盐和酱油是调味品，不是粮食作物，不能作主粮。"}, {"text": "这顿饭的主粮是烤鸭。", "explanation": "这里应该用〈主菜〉。烤鸭是菜肴，主粮指粮食作物，不能指菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家买了一只主粮。", "corrected_sentence": "我们家买了一袋主粮。", "error_description": "“主粮”是粮食类名词，量词应用“袋”，不能用“只”。正确说法是“一袋主粮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片地区只种一个主粮。", "corrected_sentence": "这片地区只种一种主粮。", "error_description": "“主粮”指一类粮食，量词应用“种”，不能用“个”。正确说法是“一种主粮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
