INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12673, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指某种产品集中生产的地理区域。", "primary_collocate": null, "pronunciation": "chǎn qū", "ipa": "tʂʰan˨˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "当极端气候频发导致主粮产区波动时，分布式的城市食品生产网络展现出显著的风险对冲能力，使地方政府将此类项目纳入关键基础设施的应急规划范畴。", "target_word": "产区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "云南是中国有名的茶叶产区。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产区的葡萄很适合酿酒。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水太多，咖啡产区的收成不好。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们去法国的葡萄酒产区旅行了一周。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东北是中国重要的大米产区。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门从产区直接买茶叶。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主要的苹果产区都在北方。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个橙子产区冬天不冷，夏天很热。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客可以到茶叶产区看农民采茶。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "主产区", "label": "复合"}, {"form": "產區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某种产品（如茶叶、葡萄酒、粮食）集中生产的地理区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12673, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "产区", "is_correct": true, "explanation": "正确。产区 chǎn qū 指某种产品集中生产的地理区域。"}, {"text": "展区", "is_correct": false, "explanation": "zhǎn（第三声）与 chǎn（第三声）声母不同，zh 与 ch 相混；展区意思是展览的区域。"}, {"text": "厂区", "is_correct": false, "explanation": "chǎng（第三声）与 chǎn（第三声）韵母不同，ang 与 an 相混；厂区意思是工厂的区域。"}, {"text": "场区", "is_correct": false, "explanation": "chǎng（第三声）与 chǎn（第三声）韵母不同，ang 与 an 相混；场区意思是场地的区域。"}], "explanations": {"产区": "正确。产区 chǎn qū 指某种产品集中生产的地理区域。", "展区": "zhǎn（第三声）与 chǎn（第三声）声母不同，zh 与 ch 相混；展区意思是展览的区域。", "厂区": "chǎng（第三声）与 chǎn（第三声）韵母不同，ang 与 an 相混；厂区意思是工厂的区域。", "场区": "chǎng（第三声）与 chǎn（第三声）韵母不同，ang 与 an 相混；场区意思是场地的区域。"}, "sentence_index": null, "correct_answer": "产区"}, "level_3": {"options": [{"text": "产区", "is_correct": true, "explanation": "正确。“主粮产区波动”指粮食产地的产量或供应变化，填入“产区”句意通顺。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“主粮音量”不成立，音量是声音的大小，不能与“主粮”构成可以波动的对象。"}, {"text": "乐章", "is_correct": false, "explanation": "语义：乐章是音乐的段落，与句中极端气候、风险对冲的语境完全不合。"}, {"text": "电压", "is_correct": false, "explanation": "搭配：“主粮电压”不成立，电压不属于粮食，不能描述主粮的波动。"}], "explanations": {"产区": "正确。“主粮产区波动”指粮食产地的产量或供应变化，填入“产区”句意通顺。", "音量": "搭配：“主粮音量”不成立，音量是声音的大小，不能与“主粮”构成可以波动的对象。", "乐章": "语义：乐章是音乐的段落，与句中极端气候、风险对冲的语境完全不合。", "电压": "搭配：“主粮电压”不成立，电压不属于粮食，不能描述主粮的波动。"}, "sentence_index": 0, "correct_answer": "产区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款产区很香，我每天都喝。", "explanation": "这里应该用〈茶叶〉。产区指地理区域，不能喝，说这款茶叶很香要用茶叶。"}, {"text": "这个产区是一家大公司，有一千名员工。", "explanation": "这里应该用〈公司〉。产区指地理区域，不是企业；一家企业要说公司。"}, {"text": "这个产区的主人去年去世了。", "explanation": "这里应该用〈农场〉。产区是较大的地理范围，没有单一的主人；农场才有主人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产区", "is_correct": true, "explanation": "正确。“从产区直接买茶叶”指从产茶的地方直接购买，符合句意。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不出产茶叶，“从银行直接买茶叶”没有货源的意义。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池不是茶叶的来源地，与“直接买”的货源语境不符。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“买”需要一个卖方或货源，“课本”不能充当卖茶叶的来源。"}], "explanations": {"产区": "正确。“从产区直接买茶叶”指从产茶的地方直接购买，符合句意。", "银行": "语义：银行不出产茶叶，“从银行直接买茶叶”没有货源的意义。", "游泳池": "语义：游泳池不是茶叶的来源地，与“直接买”的货源语境不符。", "课本": "配价：“买”需要一个卖方或货源，“课本”不能充当卖茶叶的来源。"}, "sentence_index": 6, "correct_answer": "产区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村的产区是养猪和种菜。", "explanation": "这里应该用〈产业〉。产区指地理区域，村子的主要行业要说产业。"}, {"text": "这所大学有三个产区，学生们在不同产区上课。", "explanation": "这里应该用〈校区〉。产区指生产某种产品的地区，大学的分校园要说校区，不能说产区。"}, {"text": "这家茶馆的产区有三千平方米。", "explanation": "这里应该用〈面积〉。产区指某种产品集中生产的地理区域，茶馆不是产茶的地方，应说“面积”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村是一只有名的苹果产区。", "corrected_sentence": "我们村是一片有名的苹果产区。", "error_description": "“产区”是一大片地域，量词应用“片”，不能用“只”。正确说法是“一片有名的苹果产区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带是一颗有名的棉花产区。", "corrected_sentence": "这一带是一个有名的棉花产区。", "error_description": "“产区”是地方，量词应用“个”或“片”，“颗”用于粒状物，不能修饰产区。正确说法是“一个有名的棉花产区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为降低已有风险而采取方向相反的金融交易。", "primary_collocate": null, "pronunciation": "duì chōng", "ipa": "tuei˥˩ tʂʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "当极端气候频发导致主粮产区波动时，分布式的城市食品生产网络展现出显著的风险对冲能力，使地方政府将此类项目纳入关键基础设施的应急规划范畴。", "target_word": "对冲", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司用期货对冲价格上涨的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行买了美元来对冲汇率风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用期权对冲手里股票的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主卖出期货，对冲粮价下跌的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司没有对冲油价风险，亏了很多钱。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资者买入黄金，对冲股市下跌的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司提前买油，对冲油价上涨。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对冲了一部分外汇风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对冲可以减少投资的损失，但也要支付费用。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对冲了", "label": "体标"}, {"form": "对冲过", "label": "体标"}, {"form": "对冲基金", "label": "复合"}, {"form": "對沖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "金融上用方向相反的交易来抵消已有风险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对冲", "is_correct": true, "explanation": "对冲：用方向相反的交易抵消已有风险，与句中“风险对冲能力”相符。"}, {"text": "集中", "is_correct": false, "explanation": "语义：“集中”与句中“分布式”的网络特点相反，风险集中不能体现分散应对的能力。"}, {"text": "赌博", "is_correct": false, "explanation": "语域：“赌博”口语色彩重，还带投机意味，与这句书面的风险管理语境不合。"}, {"text": "放大", "is_correct": false, "explanation": "搭配：“放大”一般不与“能力”组合，说“风险放大能力”不自然。"}], "explanations": {"对冲": "对冲：用方向相反的交易抵消已有风险，与句中“风险对冲能力”相符。", "集中": "语义：“集中”与句中“分布式”的网络特点相反，风险集中不能体现分散应对的能力。", "赌博": "语域：“赌博”口语色彩重，还带投机意味，与这句书面的风险管理语境不合。", "放大": "搭配：“放大”一般不与“能力”组合，说“风险放大能力”不自然。"}, "sentence_index": 0, "correct_answer": "对冲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想用房子对冲那笔贷款。", "explanation": "这里应该用〈抵押〉。对冲是用反向交易抵消风险，不用于给贷款提供保障。"}, {"text": "保险公司对冲了他的车祸损失。", "explanation": "这里应该用〈赔偿〉。对冲针对的是尚未发生的价格风险，不用于事后的赔付。"}, {"text": "妈妈用旧衣服对冲了家里的开销。", "explanation": "这里应该用〈节省〉。对冲是金融上的反向交易，不用于日常开支。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对冲", "is_correct": true, "explanation": "对冲：用反向交易抵消股价下跌的风险，符合句意。"}, {"text": "加剧", "is_correct": false, "explanation": "语义：买入黄金的目的是减少风险，说“加剧”与句意相反。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”不能与“风险”组合，说“推迟股市下跌的风险”不成立。"}, {"text": "纠正", "is_correct": false, "explanation": "搭配：“纠正”要接错误或偏差，不能说“纠正股市下跌的风险”。"}], "explanations": {"对冲": "对冲：用反向交易抵消股价下跌的风险，符合句意。", "加剧": "语义：买入黄金的目的是减少风险，说“加剧”与句意相反。", "推迟": "搭配：“推迟”不能与“风险”组合，说“推迟股市下跌的风险”不成立。", "纠正": "搭配：“纠正”要接错误或偏差，不能说“纠正股市下跌的风险”。"}, "sentence_index": 6, "correct_answer": "对冲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用期权对冲了这次的责任。", "explanation": "这里应该用〈规避〉。对冲针对的是价格风险，不能用于法律上的责任。"}, {"text": "他每天早上对冲一杯咖啡提神。", "explanation": "这里应该用〈冲〉。对冲是用反向交易抵消金融风险，不能用于冲泡饮料。"}, {"text": "她对冲了朋友的感情。", "explanation": "这里应该用〈伤害〉。对冲是金融术语，只用于风险，不用于感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用期权对冲的了外汇风险。", "corrected_sentence": "他们用期权对冲了外汇风险。", "error_description": "“的”不能插在动词“对冲”与“了”之间，应说“对冲了外汇风险”，不说“对冲的了外汇风险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农户在期货市场卖空，对冲谷物跌价的了风险。", "corrected_sentence": "农户在期货市场卖空，对冲谷物跌价的风险。", "error_description": "“了”不能插在定语“谷物跌价的”与中心语“风险”之间；应说“对冲谷物跌价的风险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
