INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集商场、酒店、办公等多种功能于一体的大型建筑群。", "primary_collocate": null, "pronunciation": "zōng hé tǐ", "ipa": "tsʊŋ˥ xɤ˧˥ tʰi˨˩", "syllable_count": 3, "sentences": [{"text": "这种综合体里有商场、酒店和公寓。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个综合体里有商店和电影院。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城东新建了一个大型综合体。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座综合体有酒店，也有办公楼。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们周末去综合体吃饭。", "target_word": "综合体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座综合体一共有五层。", "target_word": "综合体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个综合体的地下是停车场。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在综合体里的书店工作。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座综合体里的人很多。", "target_word": "综合体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座综合体里有图书馆和剧场。", "target_word": "综合体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "商业综合体", "label": "复合"}], "register": "中性", "sense_fingerprint": "集多种功能于一体的大型建筑群（商业综合体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "综合体", "is_correct": true, "explanation": "正确：「综合体」指集多种功能于一体的建筑群，里面可以有商场、酒店和公寓。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流工具，里面不可能有商场和酒店。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员是人，不能说「演员里有商场」。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是器具，里面容纳不了商场、酒店和公寓。"}], "explanations": {"综合体": "正确：「综合体」指集多种功能于一体的建筑群，里面可以有商场、酒店和公寓。", "语言": "语义：语言是交流工具，里面不可能有商场和酒店。", "演员": "语义：演员是人，不能说「演员里有商场」。", "乐器": "语义：乐器是器具，里面容纳不了商场、酒店和公寓。"}, "sentence_index": 0, "correct_answer": "综合体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把综合体放进了书包里。", "explanation": "这里应该用〈本子〉。综合体是大型建筑群，不能放进书包。"}, {"text": "妈妈用综合体做饭。", "explanation": "这里应该用〈锅〉。综合体是大型建筑群，不是做饭的工具。"}, {"text": "这座综合体是一个小菜市场。", "explanation": "这里应该用〈菜市场〉。综合体指多种设施组合的建筑群，只卖蔬菜的小市场不是综合体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "综合体", "is_correct": true, "explanation": "正确：「这个综合体的地下是停车场」指建筑群的地下有停车场。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音艺术，不能有地下和停车场。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：「地下」用于建筑物，不说人的地下。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，没有地下，也不能设停车场。"}], "explanations": {"综合体": "正确：「这个综合体的地下是停车场」指建筑群的地下有停车场。", "音乐": "语义：音乐是声音艺术，不能有地下和停车场。", "病人": "搭配：「地下」用于建筑物，不说人的地下。", "课本": "语义：课本是书，没有地下，也不能设停车场。"}, "sentence_index": 6, "correct_answer": "综合体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座综合体只有一间房。", "explanation": "这里应该用〈单间〉。综合体由多种设施组合而成，只有一间房的不能说综合体。"}, {"text": "这座综合体是一块空地。", "explanation": "这里应该用〈场地〉。综合体是建成的多种设施组合，没有建筑的地块不是综合体，应说场地。"}, {"text": "这座综合体是一个小凉亭。", "explanation": "这里应该用〈单体建筑〉。综合体由多种设施组合而成，只有一座小凉亭的是单体建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间综合体里有一家书店和一家餐厅。", "corrected_sentence": "这座综合体里有一家书店和一家餐厅。", "error_description": "错误：「综合体」是大型建筑群，量词应用「座」。「间」用于房间，不用于综合体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市中心正在建一座的大型综合体。", "corrected_sentence": "市中心正在建一座大型综合体。", "error_description": "错误：数量词「一座」后面不能直接加「的」，应说「一座大型综合体」。「大型」是修饰「综合体」的定语，前面不加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确答案。“展示”与“隐藏”在“把东西拿给人看”这一义项上构成反义。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“展示”的义项没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污物，与“展示”的义项没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏之物，与“展示”的义项没有反义关系。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确答案。“展示”与“隐藏”在“把东西拿给人看”这一义项上构成反义。", "搬运": "“搬运”指把东西从一处移到另一处，与“展示”的义项没有反义关系。", "清洗": "“清洗”指用水去除污物，与“展示”的义项没有反义关系。", "修理": "“修理”指修复损坏之物，与“展示”的义项没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确答案。“展示”与“隐藏”在“把东西拿给人看”这一义项上构成反义。"}, {"text": "砍伐", "is_correct": false, "explanation": "“砍伐”指砍倒树木，与“展示”的义项没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "“翻译”指把一种语言转换成另一种语言，与“展示”的义项没有反义关系。"}, {"text": "批改", "is_correct": false, "explanation": "“批改”指评阅作业或文章，与“展示”的义项没有反义关系。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确答案。“展示”与“隐藏”在“把东西拿给人看”这一义项上构成反义。", "砍伐": "“砍伐”指砍倒树木，与“展示”的义项没有反义关系。", "翻译": "“翻译”指把一种语言转换成另一种语言，与“展示”的义项没有反义关系。", "批改": "“批改”指评阅作业或文章，与“展示”的义项没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿出来给别人看，让大家看到。", "primary_collocate": null, "pronunciation": "zhǎn shì", "ipa": "ʈʂan˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他向大家展示了新手机。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上展示着很多照片。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生展示自己的画。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想展示自己的好成绩。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里展示着新来的衣服。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在会上展示了小组的计划。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把作品展示给朋友们看。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想展示新产品。", "target_word": "展示", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在比赛里展示过自己的本事。", "target_word": "展示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在台上展示了舞蹈。", "target_word": "展示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "展示了", "label": "体标"}, {"form": "展示着", "label": "体标"}, {"form": "展示过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西拿出来让大家看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。zhǎn shì，意思是把东西拿出来给别人看。"}, {"text": "战士", "is_correct": false, "explanation": "zhàn shì 与 zhǎn shì 第一音节声调不同，展示的 zhǎn 是第三声，战士的 zhàn 是第四声，意思是士兵。"}, {"text": "战事", "is_correct": false, "explanation": "zhàn shì 与 zhǎn shì 第一音节声调不同（第四声与第三声），意思是战争。"}, {"text": "战史", "is_correct": false, "explanation": "zhàn shǐ 与 zhǎn shì 声调不同，史是第三声，意思是战争的历史。"}, {"text": "长势", "is_correct": false, "explanation": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是生长的态势。"}], "explanations": {"展示": "正确答案。zhǎn shì，意思是把东西拿出来给别人看。", "战士": "zhàn shì 与 zhǎn shì 第一音节声调不同，展示的 zhǎn 是第三声，战士的 zhàn 是第四声，意思是士兵。", "战事": "zhàn shì 与 zhǎn shì 第一音节声调不同（第四声与第三声），意思是战争。", "战史": "zhàn shǐ 与 zhǎn shì 声调不同，史是第三声，意思是战争的历史。", "长势": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是生长的态势。"}, "sentence_index": null, "correct_answer": "展示"}, "level_3": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。“展示”表示把新手机拿给大家看，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」用于房间、地面，不能说「向大家打扫了新手机」。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”指私下保存，不能用“向大家收藏”来表示面向众人的行为。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”说的是修复损坏的东西，新手机不需要修理，句意不通。"}], "explanations": {"展示": "正确答案。“展示”表示把新手机拿给大家看，符合句意。", "打扫": "语义：「打扫」用于房间、地面，不能说「向大家打扫了新手机」。", "收藏": "搭配：“收藏”指私下保存，不能用“向大家收藏”来表示面向众人的行为。", "修理": "语义：“修理”说的是修复损坏的东西，新手机不需要修理，句意不通。"}, "sentence_index": 0, "correct_answer": "展示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱展示在床下。", "explanation": "这里应该用〈隐藏〉。“展示”是把东西拿出来给人看，藏在床下的钱不能这样用。"}, {"text": "这个小孩把糖展示进了肚子里。", "explanation": "这里应该用〈吞进〉。“展示”是把东西拿给人看，糖吞进肚子后就看不见了，不能这样用。"}, {"text": "这件事展示在昨天下午。", "explanation": "这里应该用〈发生〉。事情是发生的，不能拿出来给人看，“展示”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。zhǎn shì，意思是把东西拿出来给人看。"}, {"text": "战时", "is_correct": false, "explanation": "zhàn shí 与 zhǎn shì 两个音节的声调都不同，意思是战争时期。"}, {"text": "涨势", "is_correct": false, "explanation": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是上涨的趋势。"}, {"text": "掌事", "is_correct": false, "explanation": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是主管事务。"}], "explanations": {"展示": "正确答案。zhǎn shì，意思是把东西拿出来给人看。", "战时": "zhàn shí 与 zhǎn shì 两个音节的声调都不同，意思是战争时期。", "涨势": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是上涨的趋势。", "掌事": "zhǎng shì 与 zhǎn shì 韵母不同，zhǎng 带后鼻音 ng，意思是主管事务。"}, "sentence_index": null, "correct_answer": "展示"}, "level_3": {"options": [{"text": "展示", "is_correct": true, "explanation": "正确答案。“展示”表示把作品拿给朋友们看，符合句意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”表示故意不让人知道，与“给朋友们看”的语境矛盾。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”的对象是作业、文章，不能用“批改给朋友们看”来表示让人观看作品。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”表示毁掉，作品被销毁后就不能再给朋友们看。"}], "explanations": {"展示": "正确答案。“展示”表示把作品拿给朋友们看，符合句意。", "隐瞒": "语义：“隐瞒”表示故意不让人知道，与“给朋友们看”的语境矛盾。", "批改": "搭配：“批改”的对象是作业、文章，不能用“批改给朋友们看”来表示让人观看作品。", "销毁": "语义：“销毁”表示毁掉，作品被销毁后就不能再给朋友们看。"}, "sentence_index": 6, "correct_answer": "展示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他展示了大学。", "explanation": "这里应该用〈考上〉。“展示”指把东西拿给人看，大学不能被拿出来展示，这里应说“考上大学”。"}, {"text": "他在工厂里展示了一台机器的噪音。", "explanation": "这里应该用〈发出〉。噪音不是可以拿出来给人看的东西，“展示”不能用于它。"}, {"text": "胃展示了食物。", "explanation": "这里应该用〈消化〉。食物是在胃里被消化的，不能拿出来给人看，“展示”不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板在会议上把展示了新设计。", "corrected_sentence": "老板在会议上展示了新设计。", "error_description": "错误的形式是“把展示了”，正确的形式是“展示了”。“把”字句要求把要处置的对象放在“把”后面，这里“展示”前不能直接加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展览馆展示了着一幅古老的地图。", "corrected_sentence": "展览馆展示着一幅古老的地图。", "error_description": "错误的形式是“展示了着”，正确的形式是“展示着”。“了”和“着”不能同时用在“展示”后面，这里只用“着”表示陈列的状态。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "正确答案。“吸引”与“排斥”在“让人或东西靠近”这一义项上构成反义。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“吸引”的义项没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污物，与“吸引”的义项没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏之物，与“吸引”的义项没有反义关系。"}], "correct_answer": "排斥", "explanations": {"排斥": "正确答案。“吸引”与“排斥”在“让人或东西靠近”这一义项上构成反义。", "搬运": "“搬运”指把东西从一处移到另一处，与“吸引”的义项没有反义关系。", "清洗": "“清洗”指用水去除污物，与“吸引”的义项没有反义关系。", "修理": "“修理”指修复损坏之物，与“吸引”的义项没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "正确答案。“吸引”与“排斥”在“让人或东西靠近”这一义项上构成反义。"}, {"text": "砍伐", "is_correct": false, "explanation": "“砍伐”指砍倒树木，与“吸引”的义项没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "“翻译”指把一种语言转换成另一种语言，与“吸引”的义项没有反义关系。"}, {"text": "批改", "is_correct": false, "explanation": "“批改”指评阅作业或文章，与“吸引”的义项没有反义关系。"}], "correct_answer": "排斥", "explanations": {"排斥": "正确答案。“吸引”与“排斥”在“让人或东西靠近”这一义项上构成反义。", "砍伐": "“砍伐”指砍倒树木，与“吸引”的义项没有反义关系。", "翻译": "“翻译”指把一种语言转换成另一种语言，与“吸引”的义项没有反义关系。", "批改": "“批改”指评阅作业或文章，与“吸引”的义项没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用有趣或好的方式让别人或东西愿意到自己这边来。", "primary_collocate": null, "pronunciation": "xī yǐn", "ipa": "ɕi˥ in˨˩˦", "syllable_count": 2, "sentences": [{"text": "好看的电影吸引人。", "target_word": "吸引", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个公园很吸引小朋友。", "target_word": "吸引", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有趣的故事吸引了孩子们。", "target_word": "吸引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新开的书店吸引了很多学生。", "target_word": "吸引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的声音吸引了大家的注意。", "target_word": "吸引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "便宜的价格吸引着很多顾客来这家店。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱歌的样子吸引过不少观众。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的历史和文化吸引了世界各地的游客。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课很有意思，一下子吸引了全班同学。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老师总能用有趣的故事吸引学生。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸引着", "label": "体标（着）"}, {"form": "吸引了", "label": "体标（了）"}, {"form": "吸引过", "label": "体标（过）"}, {"form": "吸引力", "label": "复合"}], "register": "中性", "sense_fingerprint": "吸引：以有趣、美好的特点让人愿意靠近或关注", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸引", "is_correct": true, "explanation": "正确答案。“吸引”表示用好的特点让人被吸引，符合“好看的电影”的语境。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促”是要求别人快点做事，电影不会催促人，句意不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人，电影不能“欢迎人”。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：好看的电影不会“打扰人”，这与句子所描述的吸引力相反。"}], "explanations": {"吸引": "正确答案。“吸引”表示用好的特点让人被吸引，符合“好看的电影”的语境。", "催促": "语义：“催促”是要求别人快点做事，电影不会催促人，句意不通。", "欢迎": "搭配：“欢迎”的对象是人，电影不能“欢迎人”。", "打扰": "语义：好看的电影不会“打扰人”，这与句子所描述的吸引力相反。"}, "sentence_index": 0, "correct_answer": "吸引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海绵吸引了桌上的水。", "explanation": "这里应该用〈吸收〉。海绵吸收液体用“吸收”，“吸引”指用好的特点让人或东西靠近。"}, {"text": "他在工作中吸引了很多经验。", "explanation": "这里应该用〈积累〉。“吸引”指让人或东西靠近，经验要靠做事逐步积累，不能被吸引。"}, {"text": "这次失败吸引了他的快乐。", "explanation": "这里应该用〈夺走〉。失败让人失去快乐，「吸引」指用好的特点让人或东西靠近，意思正好不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸引", "is_correct": true, "explanation": "正确答案。“吸引”表示样子让观众喜爱，符合句意。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”表示不予理睬，与“吸引过不少观众”的语境相反。"}, {"text": "录制", "is_correct": false, "explanation": "搭配：“录制”的对象是节目、影像，不能以观众为宾语。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或作品，“样子”不能批评观众。"}], "explanations": {"吸引": "正确答案。“吸引”表示样子让观众喜爱，符合句意。", "冷落": "语义：“冷落”表示不予理睬，与“吸引过不少观众”的语境相反。", "录制": "搭配：“录制”的对象是节目、影像，不能以观众为宾语。", "批评": "搭配：“批评”的对象是人或作品，“样子”不能批评观众。"}, "sentence_index": 6, "correct_answer": "吸引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从书中吸引了很多知识。", "explanation": "这里应该用〈吸取〉。“吸引”指让人或东西靠近，不表示从书中获取知识。"}, {"text": "他一口气把钱吸引进了口袋。", "explanation": "这里应该用〈装进〉。“吸引”指用好的特点让人靠近，不表示把东西装进去。"}, {"text": "他在比赛中吸引了冠军。", "explanation": "这里应该用〈夺得〉。“吸引”指用好的方式让人或东西靠近，不能用来表示拿到冠军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌的旋律把吸引了很多听众。", "corrected_sentence": "这首歌的旋律吸引了很多听众。", "error_description": "错误的形式是“把吸引了”，正确的形式是“吸引了”。“把”字句要求把要处置的对象放在“把”后面，这里“旋律”是主语，不能用“把”引出“吸引”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的美食吸引了过很多食客。", "corrected_sentence": "这家餐厅的美食吸引了很多食客。", "error_description": "错误的形式是“吸引了过”，正确的形式是“吸引了”。“了”和“过”不能同时用在“吸引”后面，这里只用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
