INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物体表面之间的附着或结合的特性，形容事物具有不易脱离或改变的性质。", "primary_collocate": null, "pronunciation": "nián xìng", "ipa": "njɛn˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "土地用途的混合开发（mixed-use development）正被重新定义：商业综合体整合垂直农场不再仅是企业社会责任的展示，而成为吸引高端租户、提升品牌粘性的商业策略。", "target_word": "粘性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种胶水粘性很强。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蜂蜜的粘性很大。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "泥土潮湿时粘性更大。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "用久了，胶带的粘性变小了。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件的用户粘性很高。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的内容能增强读者对网站的粘性。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种双面胶粘性很强，一贴上去就不容易掉。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店靠会员活动提高顾客的粘性，让人常常回来。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新胶带粘性很好，贴过的墙也不会留下痕迹。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黏性", "label": "异形词"}, {"form": "用户粘性", "label": "复合"}], "register": "中性", "sense_fingerprint": "粘性：物体能粘住别的东西的特性，也指用户、顾客不易离开的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粘性", "is_correct": true, "explanation": "正确：「粘性」可以被提升，指用户或品牌不易离开的程度，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「提升」用于水平、质量，不用于颜色。"}, {"text": "体重", "is_correct": false, "explanation": "语义：品牌没有体重，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：品牌没有味道，不能用来提升。"}], "explanations": {"粘性": "正确：「粘性」可以被提升，指用户或品牌不易离开的程度，与句意相符。", "颜色": "搭配：「提升」用于水平、质量，不用于颜色。", "体重": "语义：品牌没有体重，句意不通。", "味道": "语义：品牌没有味道，不能用来提升。"}, "sentence_index": 0, "correct_answer": "粘性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "橡皮筋拉长以后能恢复原状，说明它的粘性很好。", "explanation": "这里应该用〈弹性〉。恢复原状靠的是弹性，粘性指粘住别的东西的特性。"}, {"text": "这块木头的粘性很大，放进水里会下沉。", "explanation": "这里应该用〈密度〉。木头下沉由密度决定，粘性说的是粘住别的东西的特性。"}, {"text": "这块钢板的粘性很高，不容易变形。", "explanation": "这里应该用〈硬度〉。不易变形说明硬度高，粘性与变形无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粘性", "is_correct": true, "explanation": "正确：「粘性」指用户不易离开的程度，与「读者对网站」的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：网站没有体重，句意不通。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：内容的硬度与读者留存无关，句意不通。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：「增强」用于能力、感情等，不说「增强对网站的亮度」。"}], "explanations": {"粘性": "正确：「粘性」指用户不易离开的程度，与「读者对网站」的语境相符。", "体重": "语义：网站没有体重，句意不通。", "硬度": "语义：内容的硬度与读者留存无关，句意不通。", "亮度": "搭配：「增强」用于能力、感情等，不说「增强对网站的亮度」。"}, "sentence_index": 6, "correct_answer": "粘性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玻璃的粘性很高，能看清楚外面。", "explanation": "这里应该用〈透明度〉。能看清楚外面靠的是透明度，粘性指粘住别的东西的特性。"}, {"text": "这种锅的粘性很好，加热不会坏。", "explanation": "这里应该用〈耐热性〉。加热不坏说明耐热，粘性与耐热无关。"}, {"text": "这块布料的粘性很好，穿着很舒服。", "explanation": "这里应该用〈柔软度〉。穿着舒服靠的是布料柔软，粘性指粘住别的东西的特性，与布料手感无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种漆粘性很，墙面不容易脱落。", "corrected_sentence": "这种漆粘性很强，墙面不容易脱落。", "error_description": "错误的形式是「粘性很」，正确的形式是「粘性很强」。「很」是程度副词，后面必须接形容词作谓语，这里漏掉了「强」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种薄膜的粘性得很强，贴上去不容易掉。", "corrected_sentence": "这种薄膜的粘性很强，贴上去不容易掉。", "error_description": "助词错误：「粘性」与「很」之间不能插入「得」。「得」用于动词或形容词之后作补语，这里应说「粘性很强」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "容积率是指在一定地块范围内，总建筑面积与用地面积的比值。", "primary_collocate": null, "pronunciation": "róng jī lǜ", "ipa": "ɻʊŋ˧˥ tɕi˥ ly˥˩", "syllable_count": 3, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "容积率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "容积率是建筑面积和用地面积的比值。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的容积率是二点五。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容积率越高，同样大的地上能盖的房子面积就越大。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商想提高这个小区的容积率。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府规定这里的容积率不能超过三。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容积率低的小区，绿地比较多。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房以前，我先查了这个楼盘的容积率。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用地面积不变，建筑面积变大，容积率就会升高。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容积率太高，小区里的人会很多，也会很吵。", "target_word": "容积率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容積率", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "容积率：总建筑面积与用地面积的比值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容积率", "is_correct": true, "explanation": "正确。“政府通过容积率奖励”中，容积率是可用来奖励建设的指标。"}, {"text": "房价", "is_correct": false, "explanation": "语义：房价是房屋的售价，不是政府可以用来奖励开发商的政策工具。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是天气指标，不能作为政府奖励的政策工具。"}, {"text": "物价", "is_correct": false, "explanation": "语义：物价反映商品的价格水平，不能作为“通过……奖励”的手段。"}], "explanations": {"容积率": "正确。“政府通过容积率奖励”中，容积率是可用来奖励建设的指标。", "房价": "语义：房价是房屋的售价，不是政府可以用来奖励开发商的政策工具。", "气温": "语义：气温是天气指标，不能作为政府奖励的政策工具。", "物价": "语义：物价反映商品的价格水平，不能作为“通过……奖励”的手段。"}, "sentence_index": 0, "correct_answer": "容积率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地的容积率是三千平方米。", "explanation": "这里应该用〈建筑面积〉。容积率是建筑面积与用地面积的比值，没有平方米这个单位，说房子总面积要用建筑面积。"}, {"text": "这个小区的容积率是百分之四十。", "explanation": "这里应该用〈绿化率〉。绿化率才用百分数表示绿地占比；容积率是比值，如二点五，不用百分数。"}, {"text": "这块地的容积率达到了百分之六十。", "explanation": "这里应该用〈建筑密度〉。建筑密度用百分数表示建筑占地的比例；容积率是比值，可以超过一，不用百分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容积率", "is_correct": true, "explanation": "正确。“低”修饰的是容积率这一指标，容积率低的小区绿地多。"}, {"text": "分数", "is_correct": false, "explanation": "语义：分数用于考试或比赛，不能用来形容小区的开发强度。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是个人的收入，不是小区的指标，与“小区……低”搭配不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或物的重量，不能用来说小区的“低”。"}], "explanations": {"容积率": "正确。“低”修饰的是容积率这一指标，容积率低的小区绿地多。", "分数": "语义：分数用于考试或比赛，不能用来形容小区的开发强度。", "工资": "语义：工资是个人的收入，不是小区的指标，与“小区……低”搭配不通。", "体重": "语义：体重指人或物的重量，不能用来说小区的“低”。"}, "sentence_index": 6, "correct_answer": "容积率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的容积率很高，每平方公里住了一万人。", "explanation": "这里应该用〈人口密度〉。每平方公里住多少人是人口密度；容积率是建筑面积与用地面积的比值。"}, {"text": "这个楼盘的容积率是每平方米两万元。", "explanation": "这里应该用〈房价〉。每平方米多少钱是房价；容积率是面积的比值，不用钱来表示。"}, {"text": "这座楼的容积率是三十层。", "explanation": "这里应该用〈楼层〉。楼有多少层说楼层；容积率是建筑面积与用地面积的比值，不按层数计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的容积率很多。", "corrected_sentence": "这块地的容积率很高。", "error_description": "“容积率”是比值，形容它的大小应说“高”或“低”，不能说“多”。正确的是“容积率很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的容积率提高的很快。", "corrected_sentence": "这个小区的容积率提高得很快。", "error_description": "补语标记错误：程度补语应用“得”，不用“的”。“提高”后应说“提高得很快”，“提高的很快”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12687, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
