INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12687, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某人的优良行为或成绩给予表扬、奖品等。", "primary_collocate": null, "pronunciation": "jiǎng lì", "ipa": "tɕjɑŋ˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "班主任每学期奖励作业认真的同学，大家都很高兴。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司奖励了表现好的员工一万元。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，考得好的同学，她会奖励一张贴纸。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用小红花奖励进步大的孩子。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈奖励他一本新书，因为他考得好。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府用减税的办法奖励节约用水的家庭。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定奖励这次比赛的第一名一台电脑。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为了奖励我，带我去了动物园。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理奖励了那位帮助客人的服务员五百元。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他救了落水的孩子，市政府奖励了他一万元。", "target_word": "奖励", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奖励了", "label": "体标"}, {"form": "奖励过", "label": "体标"}, {"form": "獎勵", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奖励：对好表现给予表扬或奖品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12687, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奖励", "is_correct": true, "explanation": "正确。奖励 jiǎng lì，指对好的表现给予表扬或奖品。"}, {"text": "讲理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，讲理指说道理，意思不同。"}, {"text": "简历", "is_correct": false, "explanation": "jiǎn 与 jiǎng 的韵尾不同（n 与 ng），简历指个人履历材料，意思不同。"}, {"text": "僵立", "is_correct": false, "explanation": "jiāng 与 jiǎng 声调不同（一声与三声），僵立指直挺挺地站着，意思不同。"}], "explanations": {"奖励": "正确。奖励 jiǎng lì，指对好的表现给予表扬或奖品。", "讲理": "lǐ（第三声）与 lì（第四声）声调不同，讲理指说道理，意思不同。", "简历": "jiǎn 与 jiǎng 的韵尾不同（n 与 ng），简历指个人履历材料，意思不同。", "僵立": "jiāng 与 jiǎng 声调不同（一声与三声），僵立指直挺挺地站着，意思不同。"}, "sentence_index": null, "correct_answer": "奖励"}, "level_3": {"options": [{"text": "奖励", "is_correct": true, "explanation": "正确。“班主任每学期奖励作业认真的同学”中的“奖励”指给予表扬或奖品。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“大家都很高兴”矛盾，班主任不会拒绝作业认真的同学，句意不通。"}, {"text": "销售", "is_correct": false, "explanation": "搭配：“销售”不能用于“作业认真的同学”这样的人，句意不通。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”会让同学不高兴，与“大家都很高兴”矛盾，不符合句意。"}], "explanations": {"奖励": "正确。“班主任每学期奖励作业认真的同学”中的“奖励”指给予表扬或奖品。", "拒绝": "语义：“拒绝”与“大家都很高兴”矛盾，班主任不会拒绝作业认真的同学，句意不通。", "销售": "搭配：“销售”不能用于“作业认真的同学”这样的人，句意不通。", "批评": "语义：“批评”会让同学不高兴，与“大家都很高兴”矛盾，不符合句意。"}, "sentence_index": 0, "correct_answer": "奖励"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弄坏了客户的电脑，老板奖励了客户一百元。", "explanation": "这里应该用〈赔偿〉。奖励是对做得好的人给予好处，弄坏别人的东西应该赔偿，不能用“奖励”。"}, {"text": "他上课玩手机，老师奖励了他。", "explanation": "这里应该用〈处罚〉。上课玩手机应受处罚，“奖励”只用于表现好的人。"}, {"text": "政府奖励了每个失业家庭一千元。", "explanation": "这里应该用〈补贴〉。“奖励”是对优良行为或成绩的回报，给困难家庭的生活补助要用“补贴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奖励", "is_correct": true, "explanation": "正确。“公司决定奖励这次比赛的第一名一台电脑”指发放奖品。"}, {"text": "批发", "is_correct": false, "explanation": "语义：“批发”指成批卖货，不能用来处理给比赛冠军发放电脑的事。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”的对象是书报等印刷品，不能与“第一名”搭配。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指刷墙面，与发放奖品无关。"}], "explanations": {"奖励": "正确。“公司决定奖励这次比赛的第一名一台电脑”指发放奖品。", "批发": "语义：“批发”指成批卖货，不能用来处理给比赛冠军发放电脑的事。", "印刷": "搭配：“印刷”的对象是书报等印刷品，不能与“第一名”搭配。", "粉刷": "语义：“粉刷”指刷墙面，与发放奖品无关。"}, "sentence_index": 6, "correct_answer": "奖励"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这次考试没及格，爸爸奖励了我，让我别灰心。", "explanation": "这里应该用〈鼓励〉。“奖励”是对优良行为或成绩给予的表扬或奖品，考试失败后的安慰和激励要用“鼓励”。"}, {"text": "他父母都下岗了，市政府奖励了他们一年的生活费。", "explanation": "这里应该用〈救济〉。“奖励”针对优良行为或成绩，给生活困难家庭的救助要用“救济”。"}, {"text": "这次出差的所有费用，公司都奖励了我。", "explanation": "这里应该用〈报销〉。“奖励”是对优良表现给予的好处，出差费用的退还要用“报销”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师奖励我了一本书。", "corrected_sentence": "这位老师奖励了我一本书。", "error_description": "“了”应紧跟动词“奖励”，写作“奖励了我一本书”；“奖励我了一本书”把“了”放在宾语“我”后面，不符合汉语语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校奖励着那个孩子一台电脑。", "corrected_sentence": "学校奖励了那个孩子一台电脑。", "error_description": "“着”表示动作正在进行或持续，“奖励”是一次完成的动作，应用“了”，写作“奖励了那个孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
