INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家凭借政治权力，依法无偿地向企业和个人征收的货币或实物，是国家财政收入的主要形式。", "primary_collocate": null, "pronunciation": "shuì shōu", "ipa": "ʂweɪ˥˩ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "税收", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "国家的税收主要用来建设公共设施。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税收是国家财政收入的主要来源。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市今年的税收增加了不少。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府用税收来修路和建学校。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业越多，当地的税收就越多。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想用新办法增加税收。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税收必须依法征收，不能乱收。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的税收在全国排第三。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房地产的税收一直是大家关心的问题。", "target_word": "税收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稅收", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "税收：国家依法征收的财政收入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "税收", "is_correct": true, "explanation": "税收与后面的「减免」组成「税收减免」，指国家对税款的减免政策，符合句意。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是建筑材料，不是可以减免的费用或税款，“减免”与它搭配不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命不是政策工具的减免对象，句中的政策只针对税费。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「体温」与「减免」不搭配，人体的温度无法通过政策减免。"}], "explanations": {"税收": "税收与后面的「减免」组成「税收减免」，指国家对税款的减免政策，符合句意。", "玻璃": "语义：玻璃是建筑材料，不是可以减免的费用或税款，“减免”与它搭配不通。", "寿命": "语义：寿命不是政策工具的减免对象，句中的政策只针对税费。", "体温": "搭配：「体温」与「减免」不搭配，人体的温度无法通过政策减免。"}, "sentence_index": 0, "correct_answer": "税收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的个人所得税收是百分之二十。", "explanation": "这里应该用〈税率〉。百分之几表示征税的比例，是税率；税收是征收到的税款总额，不用百分比表示。"}, {"text": "我去银行存了很多税收。", "explanation": "这里应该用〈存款〉。个人把钱存进银行的是存款；税收是国家依法征收的财政收入，个人不能把它存进银行。"}, {"text": "他每个月的税收都花光了。", "explanation": "这里应该用〈收入〉。个人每月的钱是收入，税收是国家依法征收的财政收入，不能说「税收都花光了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "税收", "is_correct": true, "explanation": "税收指国家依法征收的财政收入，「增加税收」是政府增加财政收入的常见说法，符合句意。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：「哭声」不是政府政策要增加的对象，句意不通。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：「增加」不与「脚印」搭配，句中需要的是表示财政收入的词。"}, {"text": "酸味", "is_correct": false, "explanation": "语义：「酸味」与政府的办法无关，句意荒谬。"}], "explanations": {"税收": "税收指国家依法征收的财政收入，「增加税收」是政府增加财政收入的常见说法，符合句意。", "哭声": "语义：「哭声」不是政府政策要增加的对象，句意不通。", "脚印": "搭配：「增加」不与「脚印」搭配，句中需要的是表示财政收入的词。", "酸味": "语义：「酸味」与政府的办法无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "税收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机违章后，交了一笔税收。", "explanation": "这里应该用〈罚款〉。违章后交给政府的处罚钱叫罚款，税收是国家依法征收的财政收入，不指违章罚钱。"}, {"text": "这学期的税收已经交清了。", "explanation": "这里应该用〈学费〉。学生交给学校的钱是学费，税收是国家的财政收入，不说「税收已经交清」。"}, {"text": "他向灾区捐了一笔税收。", "explanation": "这里应该用〈捐款〉。自愿给灾区的钱叫捐款，税收是强制征收的，不能用于自愿捐助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市今年有很多个税收。", "corrected_sentence": "这座城市今年有很多税收。", "error_description": "量词误用：「税收」是抽象名词，不能用「个」计数，应说「很多税收」，不说「很多个税收」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的税收增长的很快。", "corrected_sentence": "今年的税收增长得很快。", "error_description": "补语标记错误：程度补语应用“得”，不用“的”。“增长”后应说“增长得很快”，“增长的很快”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照法律或规定，减少或免除原本需要做的事情或要付的钱。", "primary_collocate": null, "pronunciation": "jiǎn miǎn", "ipa": "tɕjɛn˨˩˦ mjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "减免", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家小公司今年可以减免一半的税。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对家里困难的学生减免学费。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给受灾的农民减免了税款。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照规定，残疾人可以减免部分费用。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他申请减免罚款，公司同意了。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法规减免了小商店的部分税收。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项减免政策帮助了很多人。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院会减免穷人的住院费。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对小企业减免过一些费用。", "target_word": "减免", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减免了", "label": "体标"}, {"form": "减免过", "label": "体标"}, {"form": "税收减免", "label": "复合"}, {"form": "减免政策", "label": "复合"}], "register": "书面语", "sense_fingerprint": "按法律或规定减少或免除税费等应付的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "减免", "is_correct": true, "explanation": "正确：「减免」读作 jiǎn miǎn，指按规定减少或免除应付的税费。"}, {"text": "见面", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是见面。"}, {"text": "碱面", "is_correct": false, "explanation": "miàn（第四声）与 miǎn（第三声）声调不同，意思是碱面（食用碱）。"}, {"text": "简便", "is_correct": false, "explanation": "biàn 与 miǎn 声母、声调都不同，简便指简单方便，意思不同。"}], "explanations": {"减免": "正确：「减免」读作 jiǎn miǎn，指按规定减少或免除应付的税费。", "见面": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是见面。", "碱面": "miàn（第四声）与 miǎn（第三声）声调不同，意思是碱面（食用碱）。", "简便": "biàn 与 miǎn 声母、声调都不同，简便指简单方便，意思不同。"}, "sentence_index": null, "correct_answer": "减免"}, "level_3": {"options": [{"text": "减免", "is_correct": true, "explanation": "「税收减免」是固定的政策用语，指对税费的减少或免除，符合句意。"}, {"text": "加征", "is_correct": false, "explanation": "语义：「加征」指增加征收，与句中鼓励投资的政策导向相反。"}, {"text": "利息", "is_correct": false, "explanation": "搭配：「税收」后不能接「利息」，税收没有利息这一说法。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与税收政策无关，句中的政策只针对税费。"}], "explanations": {"减免": "「税收减免」是固定的政策用语，指对税费的减少或免除，符合句意。", "加征": "语义：「加征」指增加征收，与句中鼓励投资的政策导向相反。", "利息": "搭配：「税收」后不能接「利息」，税收没有利息这一说法。", "体重": "语义：体重与税收政策无关，句中的政策只针对税费。"}, "sentence_index": 0, "correct_answer": "减免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个包的重量减免了一半。", "explanation": "这里应该用〈减轻〉。重量的变轻用「减轻」；「减免」用于应缴的钱或费用、要做的事，不用于重量。"}, {"text": "政府决定把农产品的税率减免一半。", "explanation": "这里应该用〈降低〉。税率的下调用「降低」；「减免」针对应缴的税款或费用，不说「减免税率」。"}, {"text": "这台机器的噪音减免了很多。", "explanation": "这里应该用〈减弱〉。噪音的变小用「减弱」；「减免」只用于应缴的钱或费用、要做的事，不用于噪音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减免", "is_correct": true, "explanation": "「减免了小商店的部分税收」指减少或免除部分税费，符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：「拆除」的对象是建筑等实体，不能与「税收」搭配。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」指种植作物，与税收无关，句意不通。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：「粉刷」用于墙面等表面，不能用于税收。"}], "explanations": {"减免": "「减免了小商店的部分税收」指减少或免除部分税费，符合句意。", "拆除": "搭配：「拆除」的对象是建筑等实体，不能与「税收」搭配。", "种植": "语义：「种植」指种植作物，与税收无关，句意不通。", "粉刷": "搭配：「粉刷」用于墙面等表面，不能用于税收。"}, "sentence_index": 6, "correct_answer": "减免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路减免了很多距离。", "explanation": "这里应该用〈缩短〉。距离的变短用「缩短」；「减免」只用于应缴的钱或费用、要做的事，不用于距离。"}, {"text": "这辆车的速度减免了一半。", "explanation": "这里应该用〈减慢〉。速度的变慢用「减慢」；「减免」只用于应缴的钱或费用、要做的事，不用于速度。"}, {"text": "学校减免了班级的人数。", "explanation": "这里应该用〈减少〉。人数的变少用「减少」；「减免」针对应缴的税费或费用，不用于人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府去年减免得一部分税款。", "corrected_sentence": "政府去年减免过一部分税款。", "error_description": "「过」误写为「得」：动词后表示经历或完成的体标是「过」，应说「减免过一部分税款」；「减免得」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院去年把穷人的住院费减免。", "corrected_sentence": "这家医院去年把穷人的住院费减免了。", "error_description": "把字句中动词「减免」不能单独结尾，后面要加「了」等成分，应说「把穷人的住院费减免了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
