INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府为了提供公共服务（如教育、医疗、国防等）而进行收支活动的财政体系。", "primary_collocate": null, "pronunciation": "gōng gòng cái zhèng", "ipa": "kʊŋ˥ kʊŋ˥˩ tsʰaɪ˧˥ ʈʂɤŋ˥˩", "syllable_count": 4, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公共财政的钱主要来自税收。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政要用来办教育和医疗。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的公共财政比较稳定。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，公共财政需要更公开。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政支持了农村学校的建设。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的公共财政制度能让资金用得更合理。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里研究公共财政。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共财政出现了压力，政府要少花钱。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把公共财政的报告放到了网上。", "target_word": "公共财政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共财政制度", "label": "复合"}], "register": "书面", "sense_fingerprint": "政府为提供公共服务而收支的财政体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1caa302a-1474-4024-aaca-3acb1e8a52bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共财政", "is_correct": true, "explanation": "符合句意：降低的是政府在污水处理等方面的公共支出。"}, {"text": "私人投资", "is_correct": false, "explanation": "语义：句中要降低的是公共财政的支出，私人投资不属于公共财政。"}, {"text": "税收", "is_correct": false, "explanation": "搭配：税收是财政收入，不能说“税收的长期支出”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是个人收入，不能作为句中这类公共支出的主体。"}], "explanations": {"公共财政": "符合句意：降低的是政府在污水处理等方面的公共支出。", "私人投资": "语义：句中要降低的是公共财政的支出，私人投资不属于公共财政。", "税收": "搭配：税收是财政收入，不能说“税收的长期支出”。", "工资": "语义：工资是个人收入，不能作为句中这类公共支出的主体。"}, "sentence_index": 0, "correct_answer": "公共财政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的公共财政去年亏了很多。", "explanation": "这里应该用〈财务〉。公共财政指政府的收支体系，企业的财务状况不用这个词。"}, {"text": "这个人的公共财政很多。", "explanation": "这里应该用〈财产〉。公共财政指政府的收支体系，个人的财产不能说公共财政。"}, {"text": "我弟弟的公共财政只有二十块钱。", "explanation": "这里应该用〈零花钱〉。公共财政指政府的收支体系，孩子的零花钱不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共财政", "is_correct": true, "explanation": "符合句意：这里的制度指政府的公共收支体系，能让资金用得更合理。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以立制度的对象，“好的心情制度”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能与“好的……制度”搭配，制度不针对空气。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是能让资金合理使用的制度主体，与句意不符。"}], "explanations": {"公共财政": "符合句意：这里的制度指政府的公共收支体系，能让资金用得更合理。", "心情": "语义：心情不是可以立制度的对象，“好的心情制度”说不通。", "空气": "搭配：空气不能与“好的……制度”搭配，制度不针对空气。", "故事": "语义：故事不是能让资金合理使用的制度主体，与句意不符。"}, "sentence_index": 6, "correct_answer": "公共财政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的公共财政卖光了。", "explanation": "这里应该用〈门票〉。公共财政指政府的收支体系，比赛的票不能叫公共财政。"}, {"text": "我每个月的公共财政都花光了。", "explanation": "这里应该用〈收入〉。公共财政指政府的财政体系，个人的收入不能说公共财政。"}, {"text": "他的公共财政很多，买了一套房子。", "explanation": "这里应该用〈存款〉。公共财政指政府的收支体系，个人的存款不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公共财政资金主要用于教育。", "corrected_sentence": "这笔公共财政资金主要用于教育。", "error_description": "量词错误：“公共财政资金”是一笔钱，应用“笔”；“座”用于建筑、山等大型固定物，不能用来数资金。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府正在改革这座公共财政制度。", "corrected_sentence": "政府正在改革这套公共财政制度。", "error_description": "量词错误：“制度”是抽象的体系，应用量词“套”；“座”用于建筑、山等大型固定物，不能用于制度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '321ef0b4-28fe-40fd-8aee-d8be93cf7867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
