INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12697, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指为了某项用途而付出的钱。", "primary_collocate": null, "pronunciation": "zhī chū", "ipa": "ʈʂɨ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "支出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家每个月的收入比支出多。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租是我最大的一笔支出。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的支出太大了，我要少买东西。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把今年的支出写在了表格里。", "target_word": "支出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的支出主要是吃饭和买书。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收入少了，支出也要跟着减少。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天记下自己的收入和支出。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家的教育支出一年比一年多。", "target_word": "支出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这个月的支出和收入算一算。", "target_word": "支出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔支出", "label": "量词"}, {"form": "财政支出", "label": "复合"}, {"form": "教育支出", "label": "复合"}], "register": "书面", "sense_fingerprint": "支出：为某项用途而付出的钱，与收入相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12697, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支出", "is_correct": true, "explanation": "支出：zhī chū，指为某项用途付出的钱，与收入相对。"}, {"text": "指出", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，指出意思是指明。"}, {"text": "制出", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，制出意思是制造出来。"}, {"text": "吃出", "is_correct": false, "explanation": "zh 与 ch 声母不同，吃出（chī chū）意思是吃到某种东西。"}], "explanations": {"支出": "支出：zhī chū，指为某项用途付出的钱，与收入相对。", "指出": "zhī（第一声）与 zhǐ（第三声）声调不同，指出意思是指明。", "制出": "zhī（第一声）与 zhì（第四声）声调不同，制出意思是制造出来。", "吃出": "zh 与 ch 声母不同，吃出（chī chū）意思是吃到某种东西。"}, "sentence_index": null, "correct_answer": "支出"}, "level_3": {"options": [{"text": "收入", "is_correct": false, "explanation": "语义：“收入”与“降低支出”的意思相反，降低公共财政的长期收入说不通。"}, {"text": "支出", "is_correct": true, "explanation": "这里指公共财政为治理项目付出的长期钱款。四个选项中只有“支出”符合“降低……的长期”所指的花费。"}, {"text": "利润", "is_correct": false, "explanation": "语义：公共财政不以利润为目的，降低长期利润的说法不合理。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“存款”是存进去的钱，不能与“降低……的长期”搭配来指公共财政的花费。"}], "explanations": {"收入": "语义：“收入”与“降低支出”的意思相反，降低公共财政的长期收入说不通。", "支出": "这里指公共财政为治理项目付出的长期钱款。四个选项中只有“支出”符合“降低……的长期”所指的花费。", "利润": "语义：公共财政不以利润为目的，降低长期利润的说法不合理。", "存款": "搭配：“存款”是存进去的钱，不能与“降低……的长期”搭配来指公共财政的花费。"}, "sentence_index": 0, "correct_answer": "支出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的月支出主要是工资。", "explanation": "这里应该用〈收入〉。工资是收进来的钱，支出指为某种用途付出的钱。"}, {"text": "我在商店买了两斤支出。", "explanation": "这里应该用〈水果〉之类的东西。支出是花出去的钱，不是可以按斤买的东西。"}, {"text": "我的支出都存在银行里。", "explanation": "这里应该用〈存款〉。支出是已经花出去的钱，不能存进银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高与收入没有关系，收入少了，身高跟着减少说不通。"}, {"text": "支出", "is_correct": true, "explanation": "收入少了，支出也要跟着减少，这是与收入相对的那一项。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与收入没有关系，收入少了，天气也跟着减少说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能说“减少”，它只会增长，不能与这句搭配。"}], "explanations": {"身高": "语义：身高与收入没有关系，收入少了，身高跟着减少说不通。", "支出": "收入少了，支出也要跟着减少，这是与收入相对的那一项。", "天气": "语义：天气与收入没有关系，收入少了，天气也跟着减少说不通。", "年龄": "搭配：“年龄”不能说“减少”，它只会增长，不能与这句搭配。"}, "sentence_index": 6, "correct_answer": "支出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的支出是一个人，我很喜欢他。", "explanation": "这里指人，不能用〈支出〉。支出是花出去的钱，不指人。"}, {"text": "请把这个月的支出装进箱子里。", "explanation": "这里应该用〈账单〉或〈记录〉。支出是抽象的钱数，不能装进箱子。"}, {"text": "请给这个月的支出浇点水。", "explanation": "这里应该用〈花草〉之类的植物。支出是钱，不能浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我有一只大支出，需要省钱。", "corrected_sentence": "这个月我有一笔大支出，需要省钱。", "error_description": "错误在于量词。“支出”应该用“笔”来计量，“只”用于动物，应说“一笔大支出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的支出了很多，我要少买东西。", "corrected_sentence": "这个月的支出很多，我要少买东西。", "error_description": "错误在于“了”。“支出”前有“的”修饰，已是名词短语，后面不能直接加“了”，应说“这个月的支出很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
