INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指公家和私人两个方面。", "primary_collocate": null, "pronunciation": "gōng sī", "ipa": "kʊŋ˥ sɨ˥", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "公私", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他做事不分公私。", "target_word": "公私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事对公私都有好处。", "target_word": "公私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "制定这项制度时，应当兼顾公私。", "target_word": "公私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，公私的钱要分开。", "target_word": "公私", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公私双方都同意这个办法。", "target_word": "公私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师在公私之间分得很清楚。", "target_word": "公私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公私的事情要分开处理。", "target_word": "公私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上班时间不能做公私不分的事。", "target_word": "公私", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家在公私之间寻求平衡。", "target_word": "公私", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公私分明", "label": "复合"}, {"form": "公私兼顾", "label": "复合"}], "register": "书面", "sense_fingerprint": "公私：公家与私人两个方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公私", "is_correct": true, "explanation": "公私指公家和私人两个方面，此处指协作中的“公”与“私”两方，语义通顺。"}, {"text": "男女", "is_correct": false, "explanation": "语义：“男女”指性别，不能作融资模式的协作主体，句意不通。"}, {"text": "文理", "is_correct": false, "explanation": "语义：“文理”指文科与理科，与融资工具和金融投资无关，不合句意。"}, {"text": "春夏", "is_correct": false, "explanation": "搭配：“协作”需要行动主体，“春夏”是季节，不能作协作的一方。"}], "explanations": {"公私": "公私指公家和私人两个方面，此处指协作中的“公”与“私”两方，语义通顺。", "男女": "语义：“男女”指性别，不能作融资模式的协作主体，句意不通。", "文理": "语义：“文理”指文科与理科，与融资工具和金融投资无关，不合句意。", "春夏": "搭配：“协作”需要行动主体，“春夏”是季节，不能作协作的一方。"}, "sentence_index": 0, "correct_answer": "公私"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在一家公私上班。", "explanation": "这里应该用〈公司〉。公私指公家与私人两个方面，不指企业，上班的地方要说公司。"}, {"text": "他判案很公私，大家都服气。", "explanation": "这里应该用〈公正〉。公私指公家与私人两个方面，不能用来形容判案是否公平，形容公平要说“公正”。"}, {"text": "这座公私很大，早上有很多人锻炼。", "explanation": "这里应该用〈公园〉。公私指公家与私人两个方面，不指可以散步锻炼的地方，要说“公园”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公私", "is_correct": true, "explanation": "“公私之间”指公家与私人两个方面，老师在两者间分清界限，句意通顺。"}, {"text": "梦想", "is_correct": false, "explanation": "搭配：“之间”要连接两个相对的一方，“梦想”没有可以与之相对的另一方，不能说“在梦想之间”。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”不是需要“分清”的两方，句子读不通。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“饮食”是吃喝的总称，不能与另一事物构成“之间”的两端，句意不通。"}], "explanations": {"公私": "“公私之间”指公家与私人两个方面，老师在两者间分清界限，句意通顺。", "梦想": "搭配：“之间”要连接两个相对的一方，“梦想”没有可以与之相对的另一方，不能说“在梦想之间”。", "宠物": "语义：“宠物”不是需要“分清”的两方，句子读不通。", "饮食": "语义：“饮食”是吃喝的总称，不能与另一事物构成“之间”的两端，句意不通。"}, "sentence_index": 6, "correct_answer": "公私"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家基金会一直致力于公私事业。", "explanation": "这里应该用〈公益〉。公私指公家与私人两个方面，不指为公众谋利的事业。"}, {"text": "公私不能拿来买私人物品。", "explanation": "这里应该用〈公款〉。公私指两个方面，不指钱款，不能拿来买东西。"}, {"text": "他把公私贴在了门口。", "explanation": "这里应该用〈公告〉。公私指公家与私人两个方面，不指可以张贴的通知，要说“公告”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很会处理公私之前的关系。", "corrected_sentence": "他很会处理公私之间的关系。", "error_description": "“之间”表示两方之间的位置关系，应说“公私之间”；“之前”指时间上的先后，不能用来指公家与私人两方的关系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位领导做事公私明分，从不占公家便宜。", "corrected_sentence": "这位领导做事公私分明，从不占公家便宜。", "error_description": "“分明”是固定组合“公私分明”的一部分，应说“公私分明”，不能颠倒成“公私明分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
