INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "债券是一种有价证券，是政府、金融机构或企业等发行主体为筹集资金而向投资者出具的、承诺按一定利率支付利息并按约定条件偿还本金的债权债务凭证。", "primary_collocate": null, "pronunciation": "zhài quàn", "ipa": "ʈʂai˥˩ tɕʰyɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "债券", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他买了一些政府债券。", "target_word": "债券", "complexity_tier": "T3", "furigana": "tā mǎi le yìxiē zhèngfǔ zhàiquàn", "sentence_source": "generated"}, {"text": "这张债券五年后到期。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行发行了新的债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "债券的利息比存款高。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用发行债券的办法借钱。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把全部积蓄投资于债券。", "target_word": "债券", "complexity_tier": "T3", "furigana": "lǎorén bǎ quánbù jīxù tóuzī yú zhàiquàn", "sentence_source": "generated"}, {"text": "债券到期后可以拿回本金。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得债券比股票安全。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府今年发行了一千亿元债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "公司债券", "label": "复合"}], "register": "正式", "sense_fingerprint": "发行主体筹资时出具的有价证券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc32782-fb0f-4c3a-b549-af30e14c3556') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确答案：债券 zhàiquàn，指一种有价证券，与听到的读音一致。"}, {"text": "债权", "is_correct": false, "explanation": "债权 zhàiquán 与 债券 zhàiquàn 只有第二个字声调不同（quán 第二声，quàn 第四声），意思是债权人享有的请求权。"}, {"text": "战犬", "is_correct": false, "explanation": "战犬 zhànquǎn 与 债券 zhàiquàn 读音相近（zhàn/zhài，quǎn/quàn），意思是军用犬，与证券无关。"}, {"text": "再劝", "is_correct": false, "explanation": "再劝 zàiquàn 与 债券 zhàiquàn 只差声母 z/zh，意思是再次劝说。"}, {"text": "债款", "is_correct": false, "explanation": "债款 zhàikuǎn 与 债券 zhàiquàn 第二个字读音不同（kuǎn/quàn），指欠下的钱，不是有价证券。"}], "explanations": {"债券": "正确答案：债券 zhàiquàn，指一种有价证券，与听到的读音一致。", "债权": "债权 zhàiquán 与 债券 zhàiquàn 只有第二个字声调不同（quán 第二声，quàn 第四声），意思是债权人享有的请求权。", "战犬": "战犬 zhànquǎn 与 债券 zhàiquàn 读音相近（zhàn/zhài，quǎn/quàn），意思是军用犬，与证券无关。", "再劝": "再劝 zàiquàn 与 债券 zhàiquàn 只差声母 z/zh，意思是再次劝说。", "债款": "债款 zhàikuǎn 与 债券 zhàiquàn 第二个字读音不同（kuǎn/quàn），指欠下的钱，不是有价证券。"}, "sentence_index": null, "correct_answer": "债券"}, "level_3": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确。“环境收益债券”是一种金融工具，与句中的“融资模式”“证券化”相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是金融工具，无法被证券化，与“融资模式”“金融工具”冲突。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“环境收益”后面不能接“木材”，木材也不是融资工具。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药是化学品，不是融资工具，与句中的“创新融资”“证券化”冲突。"}], "explanations": {"债券": "正确。“环境收益债券”是一种金融工具，与句中的“融资模式”“证券化”相符。", "公园": "语义：公园不是金融工具，无法被证券化，与“融资模式”“金融工具”冲突。", "木材": "搭配：“环境收益”后面不能接“木材”，木材也不是融资工具。", "农药": "语义：农药是化学品，不是融资工具，与句中的“创新融资”“证券化”冲突。"}, "sentence_index": 0, "correct_answer": "债券"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向银行申请了一笔债券。", "explanation": "这里应该用〈贷款〉。申请的是贷款；债券是政府或企业发行、供投资者购买的有价证券，不能向银行申请。"}, {"text": "他写了一张债券给朋友。", "explanation": "这里应该用〈借条〉。写给朋友的是借条这类个人借据；债券由发行主体出具，个人不能这样写出。"}, {"text": "她每天用债券洗脸。", "explanation": "这里应该用〈毛巾〉。债券是有价证券，不是日常用品，不能用来洗脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd736ec90-6254-40b7-a704-0619c13431c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
